INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('qwibitai/nanoclaw/setup', 'community', 'qwibitai', 'nanoclaw', 'qwibitai/nanoclaw', 'setup', 17653, 2819, 55, '2026-03-03T01:53:46Z', '2026-03-06T06:23:59.584Z', '5d417976c362c365cf0b82dd5ed5d7de076653872d377b033c35a81bc2c2d9a7', '{"id":"qwibitai/nanoclaw/setup","name":"setup","description":{"en":"The setup skill automates configuration for AI agents, supporting WhatsApp, Telegram, and Slack. It benefits developers by simplifying the setup process.","zh":"Setup 是一个轻量级的 OpenClaw 替代方案，运行在容器中，提供安全性和便捷性","ja":"Setup は、コンテナ内で実行される軽量級の OpenClaw 代替ソリューションです","ko":"Setup은 컨테이너 내에서 실행되는 경량급 OpenClaw 대체 솔루션입니다","es":"NanoClaw es una alternativa ligera a OpenClaw que se ejecuta en contenedores para garantizar la seguridad. Conecta con aplicaciones de mensajería como WhatsApp, Telegram y Slack","fr":"NanoClaw est une alternative légère à OpenClaw qui s''exécute dans des conteneurs pour assurer la sécurité. Il se connecte à des applications de messagerie comme WhatsApp, Telegram et Slack","de":"NanoClaw ist eine leichte Alternative zu OpenClaw, die in Containern ausgeführt wird, um die Sicherheit zu gewährleisten. Es verbindet sich mit Messaging-Apps wie WhatsApp, Telegram und Slack","pt":"O Setup é uma ferramenta de configuração que executa em contêineres para garantir a segurança, conectando-se a aplicativos de mensagens como WhatsApp, Telegram e Slack","ru":"Setup - это инструмент настройки, который работает в контейнерах для обеспечения безопасности, подключаясь к приложениям обмена сообщениями, таким как WhatsApp, Telegram и Slack","ar":"Setup هو أداة إعداد تقوم بتشغيل في الحاويات لتأمين الأمان، ويتصل بتطبيقات المراسلة مثل WhatsApp و Telegram و Slack"},"seo":{"title":{"en":"Setup: Automated Configuration for AI Agents | AI Agent S...","zh":"Setup 指南：轻量级 OpenClaw 替代方案","ja":"Setup ガイド：セキュリティ対策の軽量 OpenClaw 代替","ko":"Setup 가이드: 보안을 위한 경량 OpenClaw 대체","es":"Guía de Configuración de NanoClaw: Implementación de Agen...","fr":"Guide de Configuration de NanoClaw: Mise en œuvre d''Agent...","de":"NanoClaw-Konfigurationsleitfaden: Implementierung von KI-...","pt":"Guia de Configuração do Setup: Implementação de AI Agents","ru":"Настройка Setup: Руководство по ИИ Агентам","ar":"دليل إعداد Setup: تطبيق وكلاء الذكاء الاصطناعي"},"description":{"en":"Streamline your AI agent setup with automated configuration and learn how to run setup steps with ease. Get started now!","zh":"使用 Setup skill 实现容器安全，连接 WhatsApp、Telegram、Slack 等，具有内存、定时任务等功能","ja":"Setup スキルを使用してコンテナセキュリティを実現し、WhatsApp、Telegram、Slack などに接続します","ko":"Setup 스킬을 사용하여 컨테이너 보안을 구현하고 WhatsApp, Telegram, Slack 등에 연결합니다","es":"Automatice la configuración de NanoClaw con nuestra guía paso a paso. Aprenda a conectar con WhatsApp, Telegram y Slack de manera segura","fr":"Automatisez la configuration de NanoClaw avec notre guide étape par étape. Découvrez comment se connecter à WhatsApp, Telegram et Slack de manière sécurisée","de":"Automatisieren Sie die Konfiguration von NanoClaw mit unserer Schritt-für-Schritt-Anleitung. Erfahren Sie, wie Sie sicher mit WhatsApp, Telegram und Slack ve...","pt":"Aprenda a configurar o Setup, uma alternativa leve ao OpenClaw, com suporte a contêineres e integração com aplicativos de mensagens","ru":"Узнайте, как настроить Setup, легковесную альтернативу OpenClaw, с поддержкой контейнеров и интеграцией с приложениями обмена сообщениями","ar":"تعلم كيفية إعداد Setup، بديل خفيف الوزن لبرنامج OpenClaw، مع دعم الحاويات وتكامل التطبيقات المراسلة"},"definition":{"en":"Setup is a lightweight alternative to OpenClaw that runs in containers for security, connecting to various messaging apps and featuring memory and scheduled jobs.","zh":"Setup 是一个自动化设置流程的 AI 代理技能，用于简化配置和部署","ja":"Setup は、設定とデプロイを簡素化するための自動化設定プロセスの AI エージェント スキルです","ko":"Setup은 설정과 배포를简素化하기 위한 자동화 설정 프로세스의 AI 에이전트 스킬입니다","es":"NanoClaw es un agente de IA que se configura automáticamente y se ejecuta en contenedores para garantizar la seguridad","fr":"NanoClaw est un agent d''IA qui se configure automatiquement et s''exécute dans des conteneurs pour assurer la sécurité","de":"NanoClaw ist ein KI-Agent, der sich automatisch konfiguriert und in Containern ausgeführt wird, um die Sicherheit zu gewährleisten","pt":"O que é Setup? Uma ferramenta de configuração automatizada para AI Agents","ru":"Что такое Setup? Инструмент автоматической настройки для ИИ Агентов","ar":"ما هو Setup؟ أداة إعداد خودمية لوكلاء الذكاء الاصطناعي"},"features":{"en":["Runs setup steps automatically using `bash setup.sh` and `npx tsx setup/index.ts`","Emits structured status blocks to stdout for monitoring","Logs verbose output to `logs/setup.log` for debugging","Supports channel authentication and configuration choices","Utilizes Anthropic''s Agents SDK for direct integration"],"zh":["支持容器安全","连接 WhatsApp、Telegram、Slack 等消息应用","具有内存和定时任务功能","使用 bash 和 tsx 实现自动化设置","输出结构化状态块和详细日志"],"ja":["コンテナセキュリティをサポート","WhatsApp、Telegram、Slack などのメッセージアプリに接続","メモリとスケジュールジョブ機能を備える","bash と tsx を使用した自動化設定","構造化ステータスブロックと詳細ログを出力"],"ko":["컨테이너 보안 지원","WhatsApp, Telegram, Slack 등의 메시지 앱에 연결","메모리와 스케줄 잡 기능을 갖추고","bash 와 tsx 를 사용한 자동화 설정","구조화된 상태 블록과詳細 로그 출력"],"es":["Ejecución en contenedores para garantizar la seguridad","Conexión con aplicaciones de mensajería como WhatsApp, Telegram y Slack","Memoria y trabajos programados para una mayor eficiencia","Implementación directa en el SDK de Agentes de Anthropic","Uso de bash y npx tsx para la configuración","Registro detallado de la configuración en logs/setup.log"],"fr":["Exécution dans des conteneurs pour assurer la sécurité","Connexion à des applications de messagerie comme WhatsApp, Telegram et Slack","Mémoire et tâches planifiées pour une plus grande efficacité","Mise en œuvre directe dans le SDK d''Agents d''Anthropic","Utilisation de bash et npx tsx pour la configuration","Journal détaillé de la configuration dans logs/setup.log"],"de":["Ausführung in Containern für die Gewährleistung der Sicherheit","Verbindung mit Messaging-Apps wie WhatsApp, Telegram und Slack","Speicher und geplante Aufgaben für eine höhere Effizienz","Direkte Implementierung in dem SDK von Anthropic-Agents","Verwendung von bash und npx tsx für die Konfiguration","Detailliertes Protokoll der Konfiguration in logs/setup.log"],"pt":["Execução em contêineres para segurança","Integração com aplicativos de mensagens como WhatsApp, Telegram e Slack","Suporte a trabalhos agendados e memória","Implementação direta no Agents SDK da Anthropic","Utilização de bash e tsx para execução de comandos","Emissão de blocos de status estruturados para stdout"],"ru":["Выполнение в контейнерах для безопасности","Интеграция с приложениями обмена сообщениями, такими как WhatsApp, Telegram и Slack","Поддержка запланированных задач и памяти","Прямая реализация в Agents SDK от Anthropic","Использование bash и tsx для выполнения команд","Выдача структурированных блоков статуса для stdout"],"ar":["تشغيل في الحاويات لتأمين الأمان","التكامل مع تطبيقات المراسلة مثل WhatsApp و Telegram و Slack","دعم المهام المجدولة والذاكرة","التطبيق المباشر في Agents SDK من Anthropic","استخدام bash و tsx لتنفيذ الأوامر","إصدار كتليب الحالة المهيكلة ل stdout"]},"keywords":{"en":["how to use setup","setup alternative to OpenClaw","setup install guide","what is setup","setup vs OpenClaw","setup configuration for AI agents"],"zh":["AI 代理","OpenClaw 替代方案","容器安全","自动化设置","消息应用集成","内存和定时任务","bash 脚本","tsx 设置"],"ja":["AI エージェント","OpenClaw 代替ソリューション","コンテナセキュリティ","自動化設定","メッセージアプリ統合","メモリとスケジュールジョブ","bash スクリプト","tsx 設定"],"ko":["AI 에이전트","OpenClaw 대체 솔루션","컨테이너 보안","자동화 설정","메시지 앱 통합","메모리와 스케줄 잡","bash 스크립트","tsx 설정"],"es":["agentes de IA","configuración de NanoClaw","seguridad en contenedores","conexión con WhatsApp","conexión con Telegram","conexión con Slack","implementación de agentes de IA","SDK de Agentes de Anthropic","bash","npx tsx"],"fr":["agents d''IA","configuration de NanoClaw","sécurité dans des conteneurs","connexion à WhatsApp","connexion à Telegram","connexion à Slack","mise en œuvre d''agents d''IA","SDK d''Agents d''Anthropic","bash","npx tsx"],"de":["KI-Agents","Konfiguration von NanoClaw","Sicherheit in Containern","Verbindung mit WhatsApp","Verbindung mit Telegram","Verbindung mit Slack","Implementierung von KI-Agents","SDK von Anthropic-Agents","bash","npx tsx"],"pt":["AI Agents","configuração de setup","contêineres de segurança","integração com aplicativos de mensagens","trabalhos agendados","memória","Agents SDK","bash","tsx"],"ru":["ИИ Агенты","настройка setup","контейнеры безопасности","интеграция с приложениями обмена сообщениями","запланированные задачи","память","Agents SDK","bash","tsx"],"ar":["وكلاء الذكاء الاصطناعي","إعداد Setup","حاويات الأمان","تكامل التطبيقات المراسلة","المهام المجدولة","الذاكرة","Agents SDK","bash","tsx"]}},"owner":"qwibitai","repo":"nanoclaw","repoPath":"qwibitai/nanoclaw","stars":17653,"forks":2819,"updatedAt":"2026-03-03T01:53:46Z","topics":["ai-agents","ai-assistant","claude-code","claude-skills","clawdbot"],"category":"community","skillMd":{"name":"setup","description":"Run initial NanoClaw setup. Use when user wants to install dependencies, authenticate messaging channels, register their main channel, or start the background services. Triggers on setup, install, configure nanoclaw, or first-time setup requests.","bodyPreview":"# NanoClaw Setup\n\nRun setup steps automatically. Only pause when user action is required (channel authentication, configuration choices). Setup uses `bash setup.sh` for bootstrap, then `npx tsx setup/index.ts --step <name>` for all other steps. Steps emit structured status blocks to stdout. Verbose logs go to `logs/setup.log`.\n\n**Principle:** When something is broken or missing, fix it. Don''t tell the user to go fix it themselves unless it genuinely requires their manual action (e.g. authenticat","body":"# NanoClaw Setup\n\nRun setup steps automatically. Only pause when user action is required (channel authentication, configuration choices). Setup uses `bash setup.sh` for bootstrap, then `npx tsx setup/index.ts --step <name>` for all other steps. Steps emit structured status blocks to stdout. Verbose logs go to `logs/setup.log`.\n\n**Principle:** When something is broken or missing, fix it. Don''t tell the user to go fix it themselves unless it genuinely requires their manual action (e.g. authenticating a channel, pasting a secret token). If a dependency is missing, install it. If a service won''t start, diagnose and repair. Ask the user for permission when needed, then do the work.\n\n**UX Note:** Use `AskUserQuestion` for all user-facing questions.\n\n## 1. Bootstrap (Node.js + Dependencies)\n\nRun `bash setup.sh` and parse the status block.\n\n- If NODE_OK=false → Node.js is missing or too old. Use `AskUserQuestion: Would you like me to install Node.js 22?` If confirmed:\n  - macOS: `brew install node@22` (if brew available) or install nvm then `nvm install 22`\n  - Linux: `curl -fsSL https://deb.nodesource.com/setup_22.x | sudo -E bash - && sudo apt-get install -y nodejs`, or nvm\n  - After installing Node, re-run `bash setup.sh`\n- If DEPS_OK=false → Read `logs/setup.log`. Try: delete `node_modules` and `package-lock.json`, re-run `bash setup.sh`. If native module build fails, install build tools (`xcode-select --install` on macOS, `build-essential` on Linux), then retry.\n- If NATIVE_OK=false → better-sqlite3 failed to load. Install build tools and re-run.\n- Record PLATFORM and IS_WSL for later steps.\n\n## 2. Check Environment\n\nRun `npx tsx setup/index.ts --step environment` and parse the status block.\n\n- If HAS_AUTH=true → WhatsApp is already configured, note for step 5\n- If HAS_REGISTERED_GROUPS=true → note existing config, offer to skip or reconfigure\n- Record APPLE_CONTAINER and DOCKER values for step 3\n\n## 3. Container Runtime\n\n### 3a. Choose runtime\n\nCheck the preflight results for `APPLE_CONTAINER` and `DOCKER`, and the PLATFORM from step 1.\n\n- PLATFORM=linux → Docker (only option)\n- PLATFORM=macos + APPLE_CONTAINER=installed → Use `AskUserQuestion: Docker (cross-platform) or Apple Container (native macOS)?` If Apple Container, run `/convert-to-apple-container` now, then skip to 4c.\n- PLATFORM=macos + APPLE_CONTAINER=not_found → Docker\n\n### 3a-docker. Install Docker\n\n- DOCKER=running → continue to 4b\n- DOCKER=installed_not_running → start Docker: `open -a Docker` (macOS) or `sudo systemctl start docker` (Linux). Wait 15s, re-check with `docker info`.\n- DOCKER=not_found → Use `AskUserQuestion: Docker is required for running agents. Would you like me to install it?` If confirmed:\n  - macOS: install via `brew install --cask docker`, then `open -a Docker` and wait for it to start. If brew not available, direct to Docker Desktop download at https://docker.com/products/docker-desktop\n  - Linux: install with `curl -fsSL https://get.docker.com | sh && sudo usermod -aG docker $USER`. Note: user may need to log out/in for group membership.\n\n### 3b. Apple Container conversion gate (if needed)\n\n**If the chosen runtime is Apple Container**, you MUST check whether the source code has already been converted from Docker to Apple Container. Do NOT skip this step. Run:\n\n```bash\ngrep -q \"CONTAINER_RUNTIME_BIN = ''container''\" src/container-runtime.ts && echo \"ALREADY_CONVERTED\" || echo \"NEEDS_CONVERSION\"\n```\n\n**If NEEDS_CONVERSION**, the source code still uses Docker as the runtime. You MUST run the `/convert-to-apple-container` skill NOW, before proceeding to the build step.\n\n**If ALREADY_CONVERTED**, the code already uses Apple Container. Continue to 4c.\n\n**If the chosen runtime is Docker**, no conversion is needed. Continue to 4c.\n\n### 3c. Build and test\n\nRun `npx tsx setup/index.ts --step container -- --runtime <chosen>` and parse the status block.\n\n**If BUILD_OK=false:** Read `logs/setup.log` tail for the build error.\n- Cache issue (stale layers): `docker builder prune -f` (Docker) or `container builder stop && container builder rm && container builder start` (Apple Container). Retry.\n- Dockerfile syntax or missing files: diagnose from the log and fix, then retry.\n\n**If TEST_OK=false but BUILD_OK=true:** The image built but won''t run. Check logs — common cause is runtime not fully started. Wait a moment and retry the test.\n\n## 4. Claude Authentication (No Script)\n\nIf HAS_ENV=true from step 2, read `.env` and check for `CLAUDE_CODE_OAUTH_TOKEN` or `ANTHROPIC_API_KEY`. If present, confirm with user: keep or reconfigure?\n\nAskUserQuestion: Claude subscription (Pro/Max) vs Anthropic API key?\n\n**Subscription:** Tell user to run `claude setup-token` in another terminal, copy the token, add `CLAUDE_CODE_OAUTH_TOKEN=<token>` to `.env`. Do NOT collect the token in chat.\n\n**API key:** Tell user to add `ANTHROPIC_API_KEY=<key>` to `.env`.\n\n## 5. Set Up Channels\n\nAskUserQuestion (multiSelect): Which messaging channels do you want to enable?\n- WhatsApp (authenticates via QR code or pairing code)\n- Telegram (authenticates via bot token from @BotFather)\n- Slack (authenticates via Slack app with Socket Mode)\n- Discord (authenticates via Discord bot token)\n\n**Delegate to each selected channel''s own skill.** Each channel skill handles its own code installation, authentication, registration, and JID resolution. This avoids duplicating channel-specific logic and ensures JIDs are always correct.\n\nFor each selected channel, invoke its skill:\n\n- **WhatsApp:** Invoke `/add-whatsapp`\n- **Telegram:** Invoke `/add-telegram`\n- **Slack:** Invoke `/add-slack`\n- **Discord:** Invoke `/add-discord`\n\nEach skill will:\n1. Install the channel code (via `apply-skill`)\n2. Collect credentials/tokens and write to `.env`\n3. Authenticate (WhatsApp QR/pairing, or verify token-based connection)\n4. Register the chat with the correct JID format\n5. Build and verify\n\n**After all channel skills complete**, continue to step 6.\n\n## 6. Mount Allowlist\n\nAskUserQuestion: Agent access to external directories?\n\n**No:** `npx tsx setup/index.ts --step mounts -- --empty`\n**Yes:** Collect paths/permissions. `npx tsx setup/index.ts --step mounts -- --json ''{\"allowedRoots\":[...],\"blockedPatterns\":[],\"nonMainReadOnly\":true}''`\n\n## 7. Start Service\n\nIf service already running: unload first.\n- macOS: `launchctl unload ~/Library/LaunchAgents/com.nanoclaw.plist`\n- Linux: `systemctl --user stop nanoclaw` (or `systemctl stop nanoclaw` if root)\n\nRun `npx tsx setup/index.ts --step service` and parse the status block.\n\n**If FALLBACK=wsl_no_systemd:** WSL without systemd detected. Tell user they can either enable systemd in WSL (`echo -e \"[boot]\\nsystemd=true\" | sudo tee /etc/wsl.conf` then restart WSL) or use the generated `start-nanoclaw.sh` wrapper.\n\n**If DOCKER_GROUP_STALE=true:** The user was added to the docker group after their session started — the systemd service can''t reach the Docker socket. Ask user to run these two commands:\n\n1. Immediate fix: `sudo setfacl -m u:$(whoami):rw /var/run/docker.sock`\n2. Persistent fix (re-applies after every Docker restart):\n```bash\nsudo mkdir -p /etc/systemd/system/docker.service.d\nsudo tee /etc/systemd/system/docker.service.d/socket-acl.conf << ''EOF''\n[Service]\nExecStartPost=/usr/bin/setfacl -m u:USERNAME:rw /var/run/docker.sock\nEOF\nsudo systemctl daemon-reload\n```\nReplace `USERNAME` with the actual username (from `whoami`). Run the two `sudo` commands separately — the `tee` heredoc first, then `daemon-reload`. After user confirms setfacl ran, re-run the service step.\n\n**If SERVICE_LOADED=false:**\n- Read `logs/setup.log` for the error.\n- macOS: check `launchctl list | grep nanoclaw`. If PID=`-` and status non-zero, read `logs/nanoclaw.error.log`.\n- Linux: check `systemctl --user status nanoclaw`.\n- Re-run the service step after fixing.\n\n## 8. Verify\n\nRun `npx tsx setup/index.ts --step verify` and parse the status block.\n\n**If STATUS=failed, fix each:**\n- SERVICE=stopped → `npm run build`, then restart: `launchctl kickstart -k gui/$(id -u)/com.nanoclaw` (macOS) or `systemctl --user restart nanoclaw` (Linux) or `bash start-nanoclaw.sh` (WSL nohup)\n- SERVICE=not_found → re-run step 7\n- CREDENTIALS=missing → re-run step 4\n- CHANNEL_AUTH shows `not_found` for any channel → re-invoke that channel''s skill (e.g. `/add-telegram`)\n- REGISTERED_GROUPS=0 → re-invoke the channel skills from step 5\n- MOUNT_ALLOWLIST=missing → `npx tsx setup/index.ts --step mounts -- --empty`\n\nTell user to test: send a message in their registered chat. Show: `tail -f logs/nanoclaw.log`\n\n## Troubleshooting\n\n**Service not starting:** Check `logs/nanoclaw.error.log`. Common: wrong Node path (re-run step 7), missing `.env` (step 4), missing channel credentials (re-invoke channel skill).\n\n**Container agent fails (\"Claude Code process exited with code 1\"):** Ensure the container runtime is running — `open -a Docker` (macOS Docker), `container system start` (Apple Container), or `sudo systemctl start docker` (Linux). Check container logs in `groups/main/logs/container-*.log`.\n\n**No response to messages:** Check trigger pattern. Main channel doesn''t need prefix. Check DB: `npx tsx setup/index.ts --step verify`. Check `logs/nanoclaw.log`.\n\n**Channel not connecting:** Verify the channel''s credentials are set in `.env`. Channels auto-enable when their credentials are present. For WhatsApp: check `store/auth/creds.json` exists. For token-based channels: check token values in `.env`. Restart the service after any `.env` change.\n\n**Unload service:** macOS: `launchctl unload ~/Library/LaunchAgents/com.nanoclaw.plist` | Linux: `systemctl --user stop nanoclaw`\n"},"lastSynced":"2026-03-06T06:23:59.584Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring streamlined configuration and automation, such as Cursor, Windsurf, and Claude Code, needing efficient setup for WhatsApp, Telegram, and Slack integrations.","zh":"适用于需要简化配置和自动化的AI代理，例如Cursor、Windsurf和Claude Code，需要为WhatsApp、Telegram和Slack集成进行高效设置。","ja":"設定と自動化を簡素化する必要があるAIエージェント、たとえばCursor、Windsurf、Claude Code向けで、WhatsApp、Telegram、Slackの統合のための効率的な設定が必要です。","ko":"구성 및 자동화를 간소화해야 하는 AI 에이전트에 적합합니다. 예를 들어, Cursor, Windsurf 및 Claude Code와 같은 에이전트는 WhatsApp, Telegram 및 Slack 통합을 위한 효율적인 설정이 필요합니다.","es":"Ideal para agentes de IA que requieren una configuración y automatización simplificadas, como Cursor, Windsurf y Claude Code, que necesitan una configuración eficiente para integraciones de WhatsApp, Telegram y Slack.","fr":"Idéal pour les agents IA nécessitant une configuration et une automatisation simplifiées, tels que Cursor, Windsurf et Claude Code, nécessitant une configuration efficace pour les intégrations WhatsApp, Telegram et Slack.","de":"Ideal für KI-Agents, die eine vereinfachte Konfiguration und Automatisierung benötigen, wie z. B. Cursor, Windsurf und Claude Code, die eine effiziente Einrichtung für WhatsApp-, Telegram- und Slack-Integrationen benötigen.","pt":"Ideal para Agentes de IA que exigem configuração e automação simplificadas, como Cursor, Windsurf e Claude Code, necessitando de configuração eficiente para integrações do WhatsApp, Telegram e Slack.","ru":"Идеально для агентов ИИ, требующих упрощенной конфигурации и автоматизации, таких как Cursor, Windsurf и Claude Code, нуждающихся в эффективной настройке для интеграций WhatsApp, Telegram и Slack.","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين يتطلبون تكوينًا وتنفيذًا مبسطًا، مثل Cursor و Windsurf و Claude Code، والذين يحتاجون إلى إعداد كفء لعمليات التكامل مع WhatsApp و Telegram و Slack."},"recommendation":{"en":"Empowers agents to automate configuration using bash and tsx, emitting structured status blocks to stdout and verbose logs to logs/setup.log, thereby simplifying the setup process with protocols like channel authentication and configuration choices.","zh":"赋予代理自动化配置的能力，使用bash和tsx发出结构化的状态块到stdout和详细日志到logs/setup.log，从而简化使用诸如频道认证和配置选项等协议的设置过程。","ja":"bashとtsxを使用して構造化された状態ブロックをstdoutに出力し、詳細なログをlogs/setup.logに出力することで、設定プロセスを簡素化します。チャネル認証や設定オプションなどのプロトコルで設定プロセスを簡素化します。","ko":"bash와 tsx를 사용하여 구조화된 상태 블록을 stdout에 출력하고 로그를 logs/setup.log에 출력함으로써 에이전트가 구성 자동화를 가능하게 하며, 채널 인증 및 구성 선택과 같은 프로토콜을 사용한 설정 과정을 단순화합니다.","es":"Permite a los agentes automatizar la configuración utilizando bash y tsx, emitiendo bloques de estado estructurados a stdout y registros detallados a logs/setup.log, lo que simplifica el proceso de configuración con protocolos como la autenticación de canales y opciones de configuración.","fr":"Permet aux agents d''automatiser la configuration en utilisant bash et tsx, en émettant des blocs de statut structurés à stdout et des journaux détaillés à logs/setup.log, ce qui simplifie le processus de configuration avec des protocoles tels que l''authentification de canaux et les options de configuration.","de":"Ermöglicht es Agents, die Konfiguration mithilfe von bash und tsx zu automatisieren, indem strukturierte Statusblöcke an stdout und detaillierte Protokolle an logs/setup.log emittiert werden, wodurch der Konfigurationsprozess mit Protokollen wie Kanalauthentifizierung und Konfigurationsauswahlen vereinfacht wird.","pt":"Concede aos agentes a capacidade de automatizar a configuração usando bash e tsx, emitindo blocos de status estruturados para stdout e logs verbosos para logs/setup.log, simplificando assim o processo de configuração com protocolos como autenticação de canal e opções de configuração.","ru":"Наделяет агентов возможностью автоматизировать конфигурацию с помощью bash и tsx, издавая структурированные блоки статуса в stdout и подробные журналы в logs/setup.log, тем самым упрощая процесс настройки с протоколами, такими как аутентификация канала и выбор конфигурации.","ar":"يمنح الوكلاء القدرة على توفير التكوين تلقائيًا باستخدام bash و tsx، وإصدار كتل حالة منسقة إلى stdout وسجلات مفصلة إلى logs/setup.log، وبالتالي يبسط عملية الإعداد ببروتوكولات مثل مصادقة القناة وخيارات التكوين."},"useCases":{"en":["Automating setup steps for WhatsApp, Telegram, and Slack","Configuring AI agents with bash setup.sh and npx tsx setup/index.ts","Debugging setup issues with logs/setup.log"],"zh":["自动化WhatsApp、Telegram和Slack的设置步骤","使用bash setup.sh和npx tsx setup/index.ts配置AI代理","使用logs/setup.log调试设置问题"],"ja":["WhatsApp、Telegram、Slackの設定手順を自動化する","bash setup.shとnpx tsx setup/index.tsを使用してAIエージェントを設定する","logs/setup.logを使用して設定の問題をデバッグする"],"ko":["WhatsApp, Telegram 및 Slack의 설정 단계 자동화","bash setup.sh 및 npx tsx setup/index.ts를 사용하여 AI 에이전트 구성","logs/setup.log를 사용하여 설정 문제 디버깅"],"es":["Automatizar los pasos de configuración para WhatsApp, Telegram y Slack","Configurar agentes de IA con bash setup.sh y npx tsx setup/index.ts","Depurar problemas de configuración con logs/setup.log"],"fr":["Automatiser les étapes de configuration pour WhatsApp, Telegram et Slack","Configurer les agents IA avec bash setup.sh et npx tsx setup/index.ts","Déboguer les problèmes de configuration avec logs/setup.log"],"de":["Automatisieren der Einrichtungsschritte für WhatsApp, Telegram und Slack","Konfigurieren von KI-Agents mit bash setup.sh und npx tsx setup/index.ts","Beheben von Einrichtungsproblemen mit logs/setup.log"],"pt":["Automatizar etapas de configuração para WhatsApp, Telegram e Slack","Configurar agentes de IA com bash setup.sh e npx tsx setup/index.ts","Depurar problemas de configuração com logs/setup.log"],"ru":["Автоматизировать шаги настройки для WhatsApp, Telegram и Slack","Настроить агентов ИИ с помощью bash setup.sh и npx tsx setup/index.ts","Отлаживать проблемы настройки с logs/setup.log"],"ar":["توفير خطوات الإعداد لبرامج WhatsApp و Telegram و Slack","تكوين وكلاء الذكاء الاصطناعي باستخدام bash setup.sh و npx tsx setup/index.ts","تصحيح مشاكل الإعداد باستخدام logs/setup.log"]},"limitations":{"en":["Requires user action for channel authentication and configuration choices","Dependent on bash and tsx for setup automation"],"zh":["需要用户执行频道认证和配置选项","依赖bash和tsx进行设置自动化"],"ja":["チャネル認証と設定オプションのためにユーザーの操作が必要","設定の自動化にbashとtsxに依存する"],"ko":["채널 인증 및 구성 선택에 대한 사용자 동작이 필요","설정 자동화에 bash 및 tsx에 의존"],"es":["Requiere acción del usuario para la autenticación de canales y opciones de configuración","Depende de bash y tsx para la automatización de la configuración"],"fr":["Nécessite une action de l''utilisateur pour l''authentification de canaux et les options de configuration","Dépend de bash et tsx pour l''automatisation de la configuration"],"de":["Benutzerhandlungen für Kanalauthentifizierung und Konfigurationsauswahlen erforderlich","Abhängig von bash und tsx für die Automatisierung der Konfiguration"],"pt":["Exige ação do usuário para autenticação de canal e opções de configuração","Depende de bash e tsx para automação de configuração"],"ru":["Требует действий пользователя для аутентификации канала и выбора конфигурации","Зависит от bash и tsx для автоматизации настройки"],"ar":["يتطلب إجراء المستخدم لمصادقة القناة وخيارات التكوين","يعتمد على bash و tsx لتوفير الإعداد"]},"version":4},"contentHash":"5d417976c362c365cf0b82dd5ed5d7de076653872d377b033c35a81bc2c2d9a7","qualityScore":55}');
