INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('qwibitai/nanoclaw/setup', 'setup', 'qwibitai', 'nanoclaw', 'community', 'setup qwibitai nanoclaw community ai-agents ai-assistant claude-code claude-skills clawdbot The setup skill automates configuration for AI agents, supporting WhatsApp, Telegram, and Slack. It benefits developers by simplifying the setup process. Setup 是一个轻量级的 OpenClaw 替代方案，运行在容器中，提供安全性和便捷性 Setup は、コンテナ内で実行される軽量級の OpenClaw 代替ソリューションです Setup은 컨테이너 내에서 실행되는 경량급 OpenClaw 대체 솔루션입니다 NanoClaw es una alternativa ligera a OpenClaw que se ejecuta en contenedores para garantizar la seguridad. Conecta con aplicaciones de mensajería como WhatsApp, Telegram y Slack NanoClaw est une alternative légère à OpenClaw qui s''exécute dans des conteneurs pour assurer la sécurité. Il se connecte à des applications de messagerie comme WhatsApp, Telegram et Slack NanoClaw ist eine leichte Alternative zu OpenClaw, die in Containern ausgeführt wird, um die Sicherheit zu gewährleisten. Es verbindet sich mit Messaging-Apps wie WhatsApp, Telegram und Slack O Setup é uma ferramenta de configuração que executa em contêineres para garantir a segurança, conectando-se a aplicativos de mensagens como WhatsApp, Telegram e Slack Setup - это инструмент настройки, который работает в контейнерах для обеспечения безопасности, подключаясь к приложениям обмена сообщениями, таким как WhatsApp, Telegram и Slack Setup هو أداة إعداد تقوم بتشغيل في الحاويات لتأمين الأمان، ويتصل بتطبيقات المراسلة مثل WhatsApp و Telegram و Slack how to use setup setup alternative to OpenClaw setup install guide what is setup setup vs OpenClaw setup configuration for AI agents AI 代理 OpenClaw 替代方案 容器安全 自动化设置 消息应用集成 内存和定时任务 bash 脚本 tsx 设置 Runs setup steps automatically using `bash setup.sh` and `npx tsx setup/index.ts` Emits structured status blocks to stdout for monitoring Logs verbose output to `logs/setup.log` for debugging Supports channel authentication and configuration choices Utilizes Anthropic''s Agents SDK for direct integration Setup is a lightweight alternative to OpenClaw that runs in containers for security, connecting to various messaging apps and featuring memory and scheduled jobs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shinnytech/caiwenqiang-member-rank/mermaid', 'community', 'shinnytech', 'caiwenqiang-member-rank', 'shinnytech/caiwenqiang-member-rank', 'mermaid', 0, 0, 55, '2026-03-04T13:07:01.812Z', '2026-03-04T14:34:29.691Z', '30cca46e4a8e86a467cded4732d24c0eff4e2e584fb60800a23035ddf802f86a', '{"id":"shinnytech/caiwenqiang-member-rank/mermaid","name":"mermaid","description":{"zh":"Mermaid AI工具提供会员持仓排行榜页面设计功能，帮助开发者快速设计和实现页面","ja":"Mermaid AIエージェントはメンバーホールディングランキングページ設計機能を提供し、開発者が迅速にページを設計し実装できるようにします","ko":"Mermaid AI 에이전트는 회원 보유 순위 페이지 디자인 기능을 제공하여 개발자가 빠르게 페이지를 디자인하고 구현할 수 있습니다","es":"Mermaid es una herramienta de AI que permite diseñar páginas de ranking de cartera de manera eficiente. Conecta con React, Python y Node.js para una integración perfecta","fr":"Mermaid est un outil d''IA qui permet de concevoir des pages de classement de portefeuille de manière efficace. Il se connecte à React, Python et Node.js pour une intégration parfaite","de":"Mermaid ist ein KI-Tool, das das Design von Portfolio-Ranking-Seiten ermöglicht. Es verbindet sich mit React, Python und Node.js für eine perfekte Integration","pt":"A ferramenta Mermaid é uma solução para design de páginas de rank de membros, ajudando desenvolvedores a criar interfaces úteis.","ru":"Инструмент Mermaid является решением для designing страницы рейтинга членов, помогающим разработчикам создавать полезные интерфейсы.","ar":"أداة Mermaid هي حل لتصميم صفحات تصنيف الأعضاء، تساعد المطورين على إنشاء واجهات مفيدة.","en":"会员持仓排行榜页面设计"},"seo":{"title":{"zh":"AI工具：会员持仓排行榜页面设计 - Mermaid","ja":"AIエージェント：メンバーホールディングランキングページ設計 - Mermaid","ko":"AI 에이전트: 회원 보유 순위 페이지 디자인 - Mermaid","es":"Herramientas de AI: Diseño de página de ranking de carter...","fr":"Outils d''IA: Conception de page de classement de portefeu...","de":"KI-Tools: Seiten-Design für Mermaid-Portfolio-Ranking",