INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('viralcode/openwhale/bird', 'bird', 'viralcode', 'openwhale', 'community', 'bird viralcode openwhale community bird是一种自扩展的多智能体助手，使用React、Python和Node.js等技术构建 birdは自己拡張型のマルチエージェントアシスタントで、React、Python、Node.jsなどを使用して構築されています bird는 자체 확장 가능한 멀티 에이전트 어시스턴트로 React, Python, Node.js 등을 사용하여 구축되었습니다 El Asistente de Agente de IA Bird es una herramienta de código abierto que permite a los desarrolladores crear soluciones de IA personalizadas L''Assistant Multi-Agent IA Bird est un outil open source qui permet aux développeurs de créer des solutions d''IA personnalisées Der AI-Agent Bird ist eine selbst-erweiternde Lösung, die es Entwicklern ermöglicht, individuelle IA-Lösungen zu erstellen O Bird é um assistente multiagente de IA autoextensível para desenvolvedores, permitindo a criação de soluções personalizadas Bird - это саморасширяющийся многоагентный помощник ИИ для разработчиков, позволяющий создавать индивидуальные решения طائر هو مساعد متعدد الوكلاء الذكاء الاصطناعي قابل للتوسيع لمطوري البرمجيات، مما يسمح بإنشاء حلول مخصصة Self-Extensible Multi Agent Assistant 🐋 AI智能助手 bird使用教程 bird安装指南 bird与其他AI工具比较 如何使用bird bird的特点和优势 bird CLI命令行接口 bird Agent扩展和自定义 Self-Extensible Multi Agent Assistant 🐋 ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/investor-outreach', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'investor-outreach', 61988, 7678, 55, '2026-03-06T03:39:20Z', '2026-03-06T04:16:34.081Z', 'e1f6e1ac6d85381cdc7f8ae29ff60647f9de46b4c17ef452f7e343ae50749c55', '{"id":"affaan-m/everything-claude-code/investor-outreach","name":"investor-outreach","description":{"en":"The investor-outreach AI Agent Skill generates personalized, concise investor communications for fundraising. It helps developers and founders draft cold emails, warm intro requests, and follow-up messages tailored to specific VCs or angels.","zh":"Investor Outreach AI代理专为开发者设计，集成Claude模型，自动化生成个性化投资者沟通内容，包括冷邮件、暖介绍请求和跟进邮件，显著提升融资效率。","ja":"Investor Outreach AIエージェントは、Claudeモデルを統合し、パーソナライズされた投資家コミュニケーション（コールドメール、ウォームイントロ、フォローアップ）を自動生成する開発者向けツールです。","ko":"Investor Outreach AI 에이전트는 Claude 모델을 통합하여 개인화된 투자자 커뮤니케이션(콜드 이메일, 웜 인트로, 팔로우업)을 자동 생성하는 개발자용 도구입니다.","es":"Investor-outreach es una herramienta que ayuda a los desarrolladores a crear comunicaciones personalizadas y eficaces para inversores, incluyendo correos electrónicos en frío, presentaciones cálidas y seguimientos","fr":"Investor-outreach est un outil qui aide les développeurs à créer des communications personnalisées et efficaces pour les investisseurs, notamment des emails froids, des introductions chaudes et des follow-ups","de":"Investor-outreach ist ein Tool, das Entwicklern hilft, personalisierte und effektive Kommunikationen für Investoren zu erstellen, einschließlich kalter E-Mails, warmer Vorstellungen und Follow-ups","pt":"O AI Agent Investor Outreach integra-se com Claude via MCP para gerar comunicações técnicas e personalizadas para investidores, incluindo cold emails, follow-ups e atualizações de fundraising seguindo regras específicas de concisão e personalização.","ru":"ИИ Агент Investor Outreach интегрируется с Claude через MCP для генерации технических и персонализированных коммуникаций для инвесторов, включая cold emails, follow-ups и обновления для фандрайзинга с соблюдением правил краткости и персонализации.","ar":"يتكامل Investor Outreach AI Agent مع Claude عبر MCP لإنشاء اتصالات تقنية ومخصصة للمستثمرين، بما في ذلك رسائل البريد الإلكتروني الباردة والمتابعات وتحديثات جمع التمويل مع اتباع قواعد الإيجاز والتخصيص."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"investor-outreach","description":"Draft cold emails, warm intro blurbs, follow-ups, update emails, and investor communications for fundraising. Use when the user wants outreach to angels, VCs, strategic investors, or accelerators and needs concise, personalized, investor-facing messaging.","bodyPreview":"# Investor Outreach\n\nWrite investor communication that is short, personalized, and easy to act on.\n\n## When to Activate\n\n- writing a cold email to an investor\n- drafting a warm intro request\n- sending follow-ups after a meeting or no response\n- writing investor updates during a process\n- tailoring outreach based on fund thesis or partner fit\n\n## Core Rules\n\n1. Personalize every outbound message.\n2. Keep the ask low-friction.\n3. Use proof, not adjectives.\n4. Stay concise.\n5. Never send generic co","body":"# Investor Outreach\n\nWrite investor communication that is short, personalized, and easy to act on.\n\n## When to Activate\n\n- writing a cold email to an investor\n- drafting a warm intro request\n- sending follow-ups after a meeting or no response\n- writing investor updates during a process\n- tailoring outreach based on fund thesis or partner fit\n\n## Core Rules\n\n1. Personalize every outbound message.\n2. Keep the ask low-friction.\n3. Use proof, not adjectives.\n4. Stay concise.\n5. Never send generic copy that could go to any investor.\n\n## Cold Email Structure\n\n1. subject line: short and specific\n2. opener: why this investor specifically\n3. pitch: what the company does, why now, what proof matters\n4. ask: one concrete next step\n5. sign-off: name, role, one credibility anchor if needed\n\n## Personalization Sources\n\nReference one or more of:\n- relevant portfolio companies\n- a public thesis, talk, post, or article\n- a mutual connection\n- a clear market or product fit with the investor''s focus\n\nIf that context is missing, ask for it or state that the draft is a template awaiting personalization.\n\n## Follow-Up Cadence\n\nDefault:\n- day 0: initial outbound\n- day 4-5: short follow-up with one new data point\n- day 10-12: final follow-up with a clean close\n\nDo not keep nudging after that unless the user wants a longer sequence.\n\n## Warm Intro Requests\n\nMake life easy for the connector:\n- explain why the intro is a fit\n- include a forwardable blurb\n- keep the forwardable blurb under 100 words\n\n## Post-Meeting Updates\n\nInclude:\n- the specific thing discussed\n- the answer or update promised\n- one new proof point if available\n- the next step\n\n## Quality Gate\n\nBefore delivering:\n- message is personalized\n- the ask is explicit\n- there is no fluff or begging language\n- the proof point is concrete\n- word count stays tight\n"},"category":"official","lastSynced":"2026-03-06T04:16:34.081Z","seo":{"title":{"en":"investor-outreach: Personalized Fundraising Emails | AI A...","zh":"Investor Outreach AI代理设置指南：优化投资者沟通","ja":"Investor Outreach AIエージェントのベストプラクティス","ko":"Investor Outreach AI 에이전트 설정 가이드: 투자자 커뮤니케이션 최적화","es":"Guía de configuración para investor-outreach: Comunicacio...","fr":"Paramétrer investor-outreach: Meilleures pratiques pour l...","de":"Einrichtungsleitfaden für investor-outreach: Effektive Ko...","pt":"Investor Outreach AI Agent: Guia Técnico para Desenvolved...","ru":"ИИ Агент Investor Outreach: техническое руководство для р...","ar":"Investor Outreach AI Agent: دليل تقني للمطورين"},"description":{"en":"Automate personalized investor outreach for angels, VCs & accelerators. This Claude AI skill drafts cold emails, warm intro blurbs & follow-ups using MCP. Ge...","zh":"使用Claude AI代理自动化投资者外联邮件。学习如何生成个性化冷邮件、跟进邮件和投资者更新，基于基金投资主题进行定制，提高融资成功率。","ja":"Claude AIエージェントを使用した投資家向けアウトリーチの自動化。パーソナライズされたコールドメール、フォローアップ、投資家アップデートを生成し、ファンドの投資テーゼに基づいてカスタマイズする方法。","ko":"Claude AI 에이전트를 사용한 투자자 아웃리치 자동화. 개인화된 콜드 이메일, 팔로우업, 투자자 업데이트 생성 및 펀드 테제에 기반한 맞춤형 커뮤니케이션 방법.","es":"Aprende a configurar investor-outreach para enviar correos electrónicos personalizados y seguir-ups a inversores, con ejemplos y consejos prácticos","fr":"Découvrez comment paramétrer investor-outreach pour envoyer des emails personnalisés et des follow-ups aux investisseurs, avec des exemples et des conseils p...","de":"Erfahren Sie, wie Sie investor-outreach einrichten, um personalisierte E-Mails und Follow-ups an Investoren zu senden, mit Beispielen und praktischen Tipps","pt":"Use o AI Agent Investor Outreach com Claude e MCP para automatizar comunicações personalizadas para investidores. Gere cold emails, follow-ups e atualizações...","ru":"Используйте ИИ Агент Investor Outreach с Claude и MCP для автоматизации персонализированных коммуникаций с инвесторами. Генерируйте cold emails, follow-ups и...","ar":"استخدم أداة الذكاء الاصطناعي Investor Outreach مع Claude و MCP لأتمتة الاتصالات المخصصة للمستثمرين. أنشئ رسائل بريد إلكتروني باردة ومتابعات وتحديثات تقنية لج..."},"definition":{"en":"investor-outreach is an AI Agent Skill for Claude that drafts personalized investor communications for fundraising. It generates cold emails, warm intro blurbs, follow-ups, and update emails tailored to specific fund theses and partner fit.","zh":"Investor Outreach是一种AI代理技能，利用Claude模型为开发者自动化生成简洁、个性化且易于执行的投资者沟通内容，包括冷邮件、暖介绍和跟进邮件。","ja":"Investor Outreachは、Claudeモデルを活用し、開発者が簡潔でパーソナライズされた投資家向けコミュニケーション（コールドメール、ウォームイントロ、フォローアップ）を自動生成するAIエージェントスキルです。","ko":"Investor Outreach는 Claude 모델을 활용하여 개발자가 간결하고 개인화된 투자자 대상 커뮤니케이션(콜드 이메일, 웜 인트로, 팔로우업)을 자동 생성하는 AI 에이전트 스킬입니다.","es":"Investor-outreach es una herramienta de AI que ayuda a los desarrolladores a crear comunicaciones personalizadas para inversores","fr":"Investor-outreach est un outil d''IA qui aide les développeurs à créer des communications personnalisées pour les investisseurs","de":"Investor-outreach ist ein AI-Tool, das Entwicklern hilft, personalisierte Kommunikationen für Investoren zu erstellen","pt":"Investor Outreach é um AI Agent para desenvolvedores que usa Claude via MCP para automatizar a criação de comunicações técnicas para investidores. Gera cold emails, follow-ups e atualizações personalizadas para processos de fundraising, seguindo regras de concisão e baixo atrito.","ru":"Investor Outreach — это ИИ Агент для разработчиков, использующий Claude через MCP для автоматизации создания технических коммуникаций для инвесторов. Генерирует cold emails, follow-ups и персонализированные обновления для процессов фандрайзинга с соблюдением правил краткости и низкого трения.","ar":"Investor Outreach هو أداة ذكاء اصطناعي للمطورين تستخدم Claude عبر MCP لأتمتة إنشاء اتصالات تقنية للمستثمرين. ينشئ رسائل بريد إلكتروني باردة ومتابعات وتحديثات مخصصة لعمليات جمع التمويل مع اتباع قواعد الإيجاز وتقليل الاحتكاك."},"features":{"en":["Generates personalized cold emails for angel investors and VCs","Drafts warm introduction request blurbs for strategic investors","Creates follow-up emails after meetings or non-responses","Writes investor update communications during fundraising processes","Tailors outreach based on specific fund thesis and partner fit analysis","Enforces core rules: personalization, low-friction asks, proof over adjectives"],"zh":["基于Claude模型生成个性化冷邮件","自动化暖介绍请求草稿生成","会议后跟进邮件自动化创作","根据基金投资主题定制外联内容","生成简洁且易于执行的投资者更新","集成MCP协议用于开发者工具链"],"ja":["Claudeモデルによるパーソナライズドコールドメール生成","ウォームイントロリクエストの自動ドラフト作成","ミーティング後のフォローアップメール自動作成","ファンド投資テーゼに基づくアウトリーチカスタマイズ","簡潔で行動しやすい投資家アップデート生成","MCPプロトコルとの統合による開発者ツールチェーン対応"],"ko":["Claude 모델 기반 개인화된 콜드 이메일 생성","웜 인트로 요청 자동 초안 생성","미팅 후 팔로우업 이메일 자동 작성","펀드 투자 테제 기반 아웃리치 맞춤화","간결하고 실행 가능한 투자자 업데이트 생성","MCP 프로토콜 통합을 통한 개발자 도구 체인 지원"],"es":["Correos electrónicos personalizados para inversores","Presentaciones cálidas y seguimientos automatizados","Comunicaciones basadas en la tesis del fondo o la compatibilidad del socio","Uso de pruebas en lugar de adjetivos","Mensajes concisos y de baja fricción"],"fr":["Emails personnalisés pour les investisseurs","Présentations chaudes et follow-ups automatisés","Communications basées sur la thèse du fonds ou la compatibilité du partenaire","Utilisation de preuves à la place d''adjectifs","Messages concis et à faible friction"],"de":["Personalisierte E-Mails für Investoren","Warme Vorstellungen und automatisierte Follow-ups","Kommunikationen basierend auf der Fondsthesen oder der Partnerkompatibilität","Verwendung von Beweisen anstelle von Adjektiven","Konzise und niedrig-reibungslose Nachrichten"],"pt":["Integração MCP com Claude para geração de conteúdo técnico","Geração automática de cold emails personalizados para investidores","Criação de follow-ups pós-reunião com base em regras específicas","Personalização baseada em tese de fundo e fit de parceiro","Regras de concisão e uso de provas em vez de adjetivos","Suporte a warm intros e atualizações de processo de fundraising"],"ru":["Интеграция MCP с Claude для генерации технического контента","Автоматическая генерация персонализированных cold emails для инвесторов","Создание follow-ups после встреч на основе конкретных правил","Персонализация на основе тезиса фонда и соответствия партнеру","Правила краткости и использования доказательств вместо прилагательных","Поддержка warm intros и обновлений процесса фандрайзинга"],"ar":["التكامل مع MCP و Claude لتوليد المحتوى التقني","التوليد التلقائي لرسائل البريد الإلكتروني الباردة المخصصة للمستثمرين","إنشاء متابعات بعد الاجتماعات بناءً على قواعد محددة","التخصيص بناءً على أطروحة الصندوق وملاءمة الشريك","قواعد الإيجاز واستخدام الأدلة بدلاً من الصفات","دعم المقدمات الدافئة وتحديثات عملية جمع التمويل"]},"keywords":{"en":["how to use investor-outreach MCP","investor-outreach vs manual email drafting","investor-outreach install guide","what is investor-outreach AI skill","Claude investor outreach capabilities","investor-outreach setup for fundraising","personalized cold email generation","VC fundraising communication tool","investor-outreach alternative for AI agents","warm intro blurb generator Claude"],"zh":["investor outreach AI代理","Claude投资者邮件生成","融资沟通自动化工具","MCP协议开发者集成","个性化冷邮件生成","投资者跟进邮件AI","基金主题匹配外联","LLM投资者沟通"],"ja":["investor outreach AIエージェント","Claude投資家メール生成","資金調達コミュニケーション自動化","MCPプロトコル開発者統合","パーソナライズドコールドメール生成","投資家フォローアップメールAI","ファンドテーゼマッチングアウトリーチ","LLM投資家コミュニケーション"],"ko":["investor outreach AI 에이전트","Claude 투자자 이메일 생성","자금 조달 커뮤니케이션 자동화","MCP 프로토콜 개발자 통합","개인화된 콜드 이메일 생성","투자자 팔로우업 이메일 AI","펀드 테제 매칭 아웃리치","LLM 투자자 커뮤니케이션"],"es":["investor outreach","comunicaciones personalizadas","correos electrónicos en frío","presentaciones cálidas","seguimientos automatizados","AI para desarrolladores","herramientas de productividad para desarrolladores","llm para inversores"],"fr":["investor outreach","communications personnalisées","emails froids","présentations chaudes","follow-ups automatisés","IA pour les développeurs","outils de productivité pour les développeurs","llm pour les investisseurs"],"de":["investor outreach","personalisierte Kommunikationen","kalt-e-Mails","warme Vorstellungen","automatisierte Follow-ups","KI für Entwickler","Produktivitätstools für Entwickler","llm für Investoren"],"pt":["investor outreach AI agent","claude MCP integration","cold emails para investidores","automação fundraising desenvolvedores","geração follow-ups técnicos","personalização comunicações investidores","regras concisão proof not adjectives","ferramentas AI agent para developers"],"ru":["ИИ агент investor outreach","интеграция Claude MCP","cold emails для инвесторов","автоматизация фандрайзинга для разработчиков","генерация технических follow-ups","персонализация коммуникаций с инвесторами","правила краткости proof not adjectives","ИИ инструменты для разработчиков"],"ar":["أداة الذكاء الاصطناعي investor outreach","تكامل Claude MCP","رسائل البريد الإلكتروني الباردة للمستثمرين","أتمتة جمع التمويل للمطورين","إنشاء متابعات تقنية","تخصيص اتصالات المستثمرين","قواعد الإيجاز استخدام الأدلة بدلاً من الصفات","أدوات الذكاء الاصطناعي للمطورين"]}},"agentAnalysis":{"suitability":{"en":"Essential for Fundraising Agents that automate personalized investor communications and relationship management.","zh":"对于自动化个性化投资者沟通和关系管理的Fundraising Agents来说是必不可少的。","ja":"個性化の投資家コミュニケーションと関係管理を自動化するFundraising Agentsに不可欠です。","ko":"개인화된 투자자 커뮤니케이션 및 관계 관리를 자동화하는 Fundraising Agents에게 필수적입니다.","es":"Esencial para los agentes de recaudación de fondos que automatizan las comunicaciones personalizadas con los inversores y la gestión de relaciones.","fr":"Essentiel pour les agents de collecte de fonds qui automatisent les communications personnalisées avec les investisseurs et la gestion des relations.","de":"Wesentlich für Fundraising-Agenten, die personalisierte Investor-Kommunikation und Beziehungsmanagement automatisieren.","pt":"Essencial para Agentes de Captação de Recursos que automatizam comunicações personalizadas com investidores e gestão de relacionamentos.","ru":"Необходим для Агентов по привлечению финансирования, которые автоматизируют персонализированные коммуникации с инвесторами и управление отношениями.","ar":"ضروري لوكلاء جمع التبرعات الذين يقومون بأتمتة الاتصالات المخصصة مع المستثمرين وإدارة العلاقات."},"recommendation":{"en":"Generates concise, personalized investor messaging including cold emails, warm intro blurbs, and follow-up communications tailored to specific fund theses. Uses proof-based language instead of generic adjectives to create high-conversion outreach materials for angels, VCs, and accelerators.","zh":"生成简洁、个性化的投资者消息，包括冷邮件、温暖介绍模糊和跟进通信，针对特定的基金论文。使用基于证明的语言而不是通用形容词来创建高转化率的外联材料，适用于天使投资者、风险投资公司和加速器。","ja":"コンサイスでパーソナライズされた投資家向けメッセージを生成します。コールドメール、ウォームイントロのブラー、フォローアップコミュニケーションなど、特定のファンドテーゼに合わせたメッセージを作成します。汎用的な形容詞ではなく、証拠に基づいた言語を使用して、天使投資家、ベンチャーキャピタル、加速器向けの高コンバージョンレートのアウトリーチ資料を作成します。","ko":"간결하고 개인화된 투자자 메시지를 생성합니다. 특정 펀드 테제에 맞춘 메시지를 생성하며, 이것은 코드 이메일, 따뜻한 소개 블러브 및 후속 커뮤니케이션을 포함합니다. 일반적인 형용사를 사용하지 않고 증거 기반 언어를 사용하여 천사 투자자, 벤처 캐피탈, 가속기에게 높은 전환률의 아웃리치 자료를 생성합니다.","es":"Genera mensajes concisos y personalizados para inversores, incluyendo correos fríos, textos de presentación cálida y comunicaciones de seguimiento adaptadas a las tesis específicas del fondo. Utiliza un lenguaje basado en pruebas en lugar de adjetivos genéricos para crear materiales de outreach de alta conversión para ángeles, fondos de capital riesgo y aceleradoras.","fr":"Génère des messages concis et personnalisés pour les investisseurs, y compris des emails froids, des textes d''introduction chaleureux et des communications de suivi adaptées aux thèses spécifiques du fonds. Utilise un langage basé sur des preuves au lieu d''adjectifs génériques pour créer des matériaux de prospection à haut taux de conversion pour les business angels, les VC et les accélérateurs.","de":"Erzeugt prägnante, personalisierte Nachrichten für Investoren, einschließlich Cold Emails, Warm Intro Blurbs und Follow-up-Kommunikation, die auf spezifische Fonds-Thesen zugeschnitten sind. Verwendet einen auf Beweisen basierenden Sprachstil anstelle generischer Adjektive, um Outreach-Materialien mit hoher Konversionsrate für Business Angels, VCs und Accelerators zu erstellen.","pt":"Gera mensagens concisas e personalizadas para investidores, incluindo e-mails frios, textos de introdução calorosa e comunicações de acompanhamento adaptadas às teses específicas do fundo. Utiliza linguagem baseada em provas em vez de adjetivos genéricos para criar materiais de prospecção de alta conversão para anjos, VCs e aceleradores.","ru":"Генерирует краткие, персонализированные сообщения для инвесторов, включая холодные письма, тексты для теплых представлений и коммуникации для последующего взаимодействия, адаптированные под конкретные тезисы фонда. Использует язык, основанный на доказательствах, вместо общих прилагательных для создания материалов для привлечения с высокой конверсией, предназначенных для бизнес-ангелов, венчурных капиталистов и акселераторов.","ar":"يولد رسائل موجزة ومخصصة للمستثمرين، بما في ذلك رسائل البريد الإلكتروني الباردة، ومقدمات التعريف الدافئة، واتصالات المتابعة المصممة خصيصًا لأطروحات الصندوق المحددة. يستخدم لغة قائمة على الأدلة بدلاً من الصفات العامة لإنشاء مواد تواصل عالية التحويل للمستثمرين الملائكة، وشركات رأس المال المخاطر، ومسرعات الأعمال."},"useCases":{"en":["Drafting personalized cold emails to specific investors","Creating warm introduction requests for referral networks","Generating investor update communications during fundraising processes","Tailoring outreach based on fund thesis compatibility","Automating follow-up sequences after meetings or non-responses"],"zh":["为特定投资者草拟个性化的冷邮件","为推荐网络创建温暖的介绍请求","在筹款过程中生成投资者更新通信","根据基金论文的兼容性量身定制外联","在会议或无响应后自动化跟进序列"],"ja":["特定の投資家向けにパーソナライズされたコールドメールを草案する","紹介ネットワーク用のウォームイントロのリクエストを作成する","資金調達プロセス中の投資家向け更新コミュニケーションを生成する","ファンドテーゼの互換性に基づいてアウトリーチをカスタマイズする","ミーティングまたは無反応後のフォローアップシーケンスを自動化する"],"ko":["특정 투자자에게 개인화된 코드 이메일 초안을 작성합니다","추천 네트워크를 위한 따뜻한 소개 요청을 생성합니다","펀드레이징 과정 중에 투자자 업데이트를 위한 커뮤니케이션을 생성합니다","펀드 테제의 호환성을 기준으로 아웃리치를 맞춤 설정합니다","회의 또는 무응답 이후 후속 시퀀스를 자동화합니다"],"es":["Redactar emails fríos personalizados para inversores específicos","Crear solicitudes de presentación cálida para redes de referidos","Generar comunicaciones de actualización para inversores durante los procesos de recaudación de fondos","Personalizar el outreach basado en la compatibilidad con la tesis del fondo","Automatizar secuencias de seguimiento después de reuniones o falta de respuesta"],"fr":["Rédiger des emails froids personnalisés pour des investisseurs spécifiques","Créer des demandes d''introduction chaleureuse pour les réseaux de référence","Générer des communications de mise à jour pour les investisseurs pendant les processus de collecte de fonds","Adapter la prospection en fonction de la compatibilité avec la thèse du fonds","Automatiser les séquences de suivi après des réunions ou des non-réponses"],"de":["Verfassen personalisierter Cold Emails an bestimmte Investoren","Erstellen von Warm Introduction-Anfragen für Empfehlungsnetzwerke","Generieren von Investor-Update-Kommunikation während Fundraising-Prozessen","Anpassen des Outreachs basierend auf der Kompatibilität der Fonds-These","Automatisieren von Follow-up-Sequenzen nach Meetings oder Nicht-Antworten"],"pt":["Elaboração de e-mails frios personalizados para investidores específicos","Criação de solicitações de apresentação calorosa para redes de referência","Geração de comunicações de atualização para investidores durante os processos de captação de recursos","Personalização da abordagem com base na compatibilidade da tese do fundo","Automatização de sequências de acompanhamento após reuniões ou ausência de resposta"],"ru":["Составление персонализированных холодных писем конкретным инвесторам","Создание запросов на теплое представление для сетей рекомендаций","Генерация коммуникаций с обновлениями для инвесторов в процессе привлечения финансирования","Настройка охвата на основе совместимости с тезисами фонда","Автоматизация последовательностей последующих действий после встреч или отсутствия ответа"],"ar":["صياغة رسائل بريد إلكتروني باردة مخصصة لمستثمرين محددين","إنشاء طلبات تعريف دافئة لشبكات الإحالة","إنشاء اتصالات تحديث للمستثمرين أثناء عمليات جمع التبرعات","تخصيص التواصل بناءً على توافق أطروحة الصندوق","أتمتة تسلسلات المتابعة بعد الاجتماعات أو عدم الرد"]},"limitations":{"en":["Requires specific investor data for personalization","Limited to investor-facing communication contexts","Depends on user-provided proof points and metrics"],"zh":["需要特定的投资者数据来实现个性化","仅限于投资者面向的通信环境","依赖于用户提供的证明点和指标"],"ja":["パーソナライゼーションのために特定の投資家データが必要","投資家向けコミュニケーションのコンテキストに限定","ユーザー提供の証拠ポイントとメトリクスに依存"],"ko":["개인화를 위해 특정 투자자 데이터가 필요합니다","투자자와의 커뮤니케이션 환경에만 한정됩니다","사용자 제공의 증거 포인트 및 메트릭스에 의존합니다"],"es":["Requiere datos específicos del inversor para la personalización","Limitado a contextos de comunicación dirigidos a inversores","Depende de puntos de prueba y métricas proporcionados por el usuario"],"fr":["Nécessite des données spécifiques sur l''investisseur pour la personnalisation","Limité aux contextes de communication avec les investisseurs","Dépend des preuves et des métriques fournies par l''utilisateur"],"de":["Erfordert spezifische Investorendaten für die Personalisierung","Beschränkt auf investororientierte Kommunikationskontexte","Hängt von benutzerbereitgestellten Beweispunkten und Metriken ab"],"pt":["Requer dados específicos do investidor para personalização","Limitado a contextos de comunicação voltados para investidores","Depende de pontos de prova e métricas fornecidos pelo usuário"],"ru":["Требует конкретных данных инвестора для персонализации","Ограничен контекстами коммуникации, ориентированными на инвесторов","Зависит от предоставленных пользователем доказательных пунктов и метрик"],"ar":["يتطلب بيانات محددة للمستثمر للتخصيص","يقتصر على سياقات الاتصال الموجهة للمستثمرين","يعتمد على نقاط الإثبات والمقاييس التي يقدمها المستخدم"]},"version":4},"contentHash":"e1f6e1ac6d85381cdc7f8ae29ff60647f9de46b4c17ef452f7e343ae50749c55","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":55}');
DELETE FROM skills_fts WHERE id = 'affaan-m/everything-claude-code/investor-outreach';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/investor-outreach', 'investor-outreach', 'affaan-m', 'everything-claude-code', 'official', 'investor-outreach affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The investor-outreach AI Agent Skill generates personalized, concise investor communications for fundraising. It helps developers and founders draft cold emails, warm intro requests, and follow-up messages tailored to specific VCs or angels. Investor Outreach AI代理专为开发者设计，集成Claude模型，自动化生成个性化投资者沟通内容，包括冷邮件、暖介绍请求和跟进邮件，显著提升融资效率。 Investor Outreach AIエージェントは、Claudeモデルを統合し、パーソナライズされた投資家コミュニケーション（コールドメール、ウォームイントロ、フォローアップ）を自動生成する開発者向けツールです。 Investor Outreach AI 에이전트는 Claude 모델을 통합하여 개인화된 투자자 커뮤니케이션(콜드 이메일, 웜 인트로, 팔로우업)을 자동 생성하는 개발자용 도구입니다. Investor-outreach es una herramienta que ayuda a los desarrolladores a crear comunicaciones personalizadas y eficaces para inversores, incluyendo correos electrónicos en frío, presentaciones cálidas y seguimientos Investor-outreach est un outil qui aide les développeurs à créer des communications personnalisées et efficaces pour les investisseurs, notamment des emails froids, des introductions chaudes et des follow-ups Investor-outreach ist ein Tool, das Entwicklern hilft, personalisierte und effektive Kommunikationen für Investoren zu erstellen, einschließlich kalter E-Mails, warmer Vorstellungen und Follow-ups O AI Agent Investor Outreach integra-se com Claude via MCP para gerar comunicações técnicas e personalizadas para investidores, incluindo cold emails, follow-ups e atualizações de fundraising seguindo regras específicas de concisão e personalização. ИИ Агент Investor Outreach интегрируется с Claude через MCP для генерации технических и персонализированных коммуникаций для инвесторов, включая cold emails, follow-ups и обновления для фандрайзинга с соблюдением правил краткости и персонализации. يتكامل Investor Outreach AI Agent مع Claude عبر MCP لإنشاء اتصالات تقنية ومخصصة للمستثمرين، بما في ذلك رسائل البريد الإلكتروني الباردة والمتابعات وتحديثات جمع التمويل مع اتباع قواعد الإيجاز والتخصيص. how to use investor-outreach MCP investor-outreach vs manual email drafting investor-outreach install guide what is investor-outreach AI skill Claude investor outreach capabilities investor-outreach setup for fundraising personalized cold email generation VC fundraising communication tool investor-outreach alternative for AI agents warm intro blurb generator Claude investor outreach AI代理 Claude投资者邮件生成 融资沟通自动化工具 MCP协议开发者集成 个性化冷邮件生成 投资者跟进邮件AI 基金主题匹配外联 LLM投资者沟通 Generates personalized cold emails for angel investors and VCs Drafts warm introduction request blurbs for strategic investors Creates follow-up emails after meetings or non-responses Writes investor update communications during fundraising processes Tailors outreach based on specific fund thesis and partner fit analysis Enforces core rules: personalization, low-friction asks, proof over adjectives investor-outreach is an AI Agent Skill for Claude that drafts personalized investor communications for fundraising. It generates cold emails, warm intro blurbs, follow-ups, and update emails tailored to specific fund theses and partner fit.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('akiojin/llmlb/gh-fix-ci', 'community', 'akiojin', 'llmlb', 'akiojin/llmlb', 'gh-fix-ci', 0, 0, 55, '2026-02-28T01:32:52.540Z', '2026-02-28T02:20:35.342Z', '94c0546d84a24daa25732db63c4d6f8102ef7a66085c6f261fcc57ffe31e1cf8', '{"id":"akiojin/llmlb/gh-fix-ci","name":"gh-fix-ci","description":{"zh":"gh-fix-ci是一个分布式LLM路由器，具有负载均衡和自动模型分布，用于提高CI效率","ja":"gh-fix-ciは、分散型LLMルーターであり、負荷分散と自動モデル分散を備えています。CIの効率を向上させます","ko":"gh-fix-ci는 분산형 LLM 라우터로 로드 밸런싱과 자동 모델 분산을 통해 CI 효율성을 높여줍니다","es":"gh-fix-ci es un enrutador LLM distribuido que ofrece equilibrio de carga y distribución automática de modelos para mejorar el rendimiento","fr":"gh-fix-ci est un routeur LLM distribué qui propose un équilibrage de charge et une distribution automatique de modèles pour améliorer les performances","de":"gh-fix-ci ist ein verteilter LLM-Router, der Lastenausgleich und automatische Modellverteilung bietet, um die Leistung zu verbessern","pt":"O gh-fix-ci é uma ferramenta de IA que fornece um roteador LLM distribuído com balanceamento de carga e distribuição automática de modelos","ru":"gh-fix-ci - это инструмент ИИ, который предоставляет распределенный маршрутизатор LLM с балансировкой нагрузки и автоматическим распределением моделей","ar":"gh-fix-ci هو أداة ذكاء اصطناعي تقدم مُوزع LLM الموزع مع توازن الحمل والتوزيع التلقائي للنماذج","en":"Distributed LLM router with load balancing and automatic model distribution"},"seo":{"title":{"zh":"AI工具gh-fix-ci：分布式LLM路由器","ja":"AIエージェントgh-fix-ci：分散型LLMルーター","ko":"AI 에이전트 gh-fix-ci: 분산형 LLM 라우터","es":"Herramientas de AI: gh-fix-ci","fr":"Outils d''IA: gh-fix-ci","de":"KI-Tools: gh-fix-ci","pt":"Ferramentas de IA: gh-fix-ci - Roteador LLM Distribuído","ru":"ИИ Агенты: gh-fix-ci - Распределенный маршрутизатор LLM","ar":"أدوات الذكاء الاصطناعي: gh-fix-ci - مُوزع LLM الموزع","en":"gh-fix-ci"},"description":{"zh":"gh-fix-ci是一个分布式LLM路由器，具有负载均衡和自动模型分布，用于提高CI效率","ja":"gh-fix-ciは、分散型LLMルーターであり、負荷分散と自動モデル分散を備えています。CIの効率を向上させます","ko":"gh-fix-ci는 분산형 LLM 라우터로 로드 밸런싱과 자동 모델 분산을 통해 CI 효율성을 높여줍니다","es":"gh-fix-ci es un enrutador LLM distribuido que ofrece equilibrio de carga y distribución automática de modelos para mejorar el rendimiento","fr":"gh-fix-ci est un routeur LLM distribué qui propose un équilibrage de charge et une distribution automatique de modèles pour améliorer les performances","de":"gh-fix-ci ist ein verteilter LLM-Router, der Lastenausgleich und automatische Modellverteilung bietet, um die Leistung zu verbessern","pt":"O gh-fix-ci é uma ferramenta de IA que fornece um roteador LLM distribuído com balanceamento de carga e distribuição automática de modelos","ru":"gh-fix-ci - это инструмент ИИ, который предоставляет распределенный маршрутизатор LLM с балансировкой нагрузки и автоматическим распределением моделей","ar":"gh-fix-ci هو أداة ذكاء اصطناعي تقدم مُوزع LLM الموزع مع توازن الحمل والتوزيع التلقائي للنماذج","en":"Distributed LLM router with load balancing and automatic model distribution"},"definition":{"en":"Distributed LLM router with load balancing and automatic model distribution"},"features":{"zh":["分布式LLM路由","负载均衡","自动模型分布","提高CI效率","支持多种LLM模型","易于集成和部署"],"ja":["分散型LLMルーティング","負荷分散","自動モデル分散","CIの効率向上","多種のLLMモデルをサポート","容易に統合とデプロイ"],"ko":["분산형 LLM 라우팅","로드 밸런싱","자동 모델 분산","CI 효율성 향상","다양한 LLM 모델 지원","쉽게 통합 및 배포"],"es":["Enrutador LLM distribuido","Equilibrio de carga","Distribución automática de modelos","Mejora del rendimiento","Escalabilidad","Flexibilidad"],"fr":["Routeur LLM distribué","Équilibrage de charge","Distribution automatique de modèles","Amélioration des performances","Évolutivité","Flexibilité"],"de":["Verteilter LLM-Router","Lastenausgleich","Automatische Modellverteilung","Leistungsverbesserung","Skalierbarkeit","Flexibilität"],"pt":["Roteador LLM distribuído","Balanceamento de carga","Distribuição automática de modelos","Integração com pipelines de CI","Suporte a múltiplos ambientes","Escalabilidade e flexibilidade"],"ru":["Распределенный маршрутизатор LLM","Балансировка нагрузки","Автоматическое распределение моделей","Интеграция с конвейерами CI","Поддержка нескольких сред","Масштабируемость и гибкость"],"ar":["مُوزع LLM الموزع","توازن الحمل","التوزيع التلقائي للنماذج","التكامل مع خطوط أنابيب CI","دعم بيئات متعددة","المرونة والتوسع"]},"keywords":{"zh":["如何使用gh-fix-ci","什么是分布式LLM路由","gh-fix-ci安装","gh-fix-ci设置指南","gh-fix-ci替代品","gh-fix-ci vs 其他CI工具","LLM路由器","CI优化","自动模型分布"],"ja":["gh-fix-ciの使い方","分散型LLMルーティングとは","gh-fix-ciのインストール","gh-fix-ciの設定ガイド","gh-fix-ciの代替","gh-fix-ci vs 他のCIツール","LLMルーター","CIの最適化","自動モデル分散"],"ko":["gh-fix-ci 사용법","분산형 LLM 라우팅이란","gh-fix-ci 설치","gh-fix-ci 설정 가이드","gh-fix-ci 대체품","gh-fix-ci vs 다른 CI 도구","LLM 라우터","CI 최적화","자동 모델 분산"],"es":["herramientas de AI","enrutador LLM","equilibrio de carga","distribución automática de modelos","mejora del rendimiento","gh-fix-ci alternativa","gh-fix-ci vs otros","cómo usar gh-fix-ci","guía de instalación de gh-fix-ci","configuración de gh-fix-ci"],"fr":["outils d''IA","routeur LLM","équilibrage de charge","distribution automatique de modèles","amélioration des performances","gh-fix-ci alternative","gh-fix-ci vs autres","comment utiliser gh-fix-ci","guide d''installation de gh-fix-ci","configuration de gh-fix-ci"],"de":["KI-Tools","LLM-Router","Lastenausgleich","automatische Modellverteilung","Leistungsverbesserung","gh-fix-ci Alternative","gh-fix-ci vs andere","wie man gh-fix-ci verwendet","Installationsanleitung für gh-fix-ci","Konfiguration von gh-fix-ci"],"pt":["ferramentas de ia","roteador llm","balanceamento de carga","distribuição de modelos","pipelines de ci","gh-fix-ci alternative","gh-fix-ci vs jenkins","como usar gh-fix-ci","guia de instalação gh-fix-ci","configuração gh-fix-ci"],"ru":["инструменты ии","маршрутизатор llm","балансировка нагрузки","распределение моделей","конвейеры ci","альтернативы gh-fix-ci","gh-fix-ci vs jenkins","как использовать gh-fix-ci","руководство по установке gh-fix-ci","настройка gh-fix-ci"],"ar":["أدوات الذكاء الاصطناعي","مُوزع llm","توازن الحمل","التوزيع النموذجي","خطوط أنابيب ci","بديل gh-fix-ci","gh-fix-ci مقابل jenkins","كيفية استخدام gh-fix-ci","دليل تثبيت gh-fix-ci","إعداد gh-fix-ci"]}},"owner":"akiojin","repo":"llmlb","repoPath":"akiojin/llmlb","stars":0,"forks":0,"updatedAt":"2026-02-28T01:32:52.540Z","topics":[],"category":"community","skillMd":{"name":"gh-fix-ci","description":"Inspect GitHub PR for CI failures, merge conflicts, update-branch requirements, reviewer comments, change requests, and unresolved review threads. Create fix plans and implement after user approval. Resolve review threads and notify reviewers after fixes.","bodyPreview":"# Gh PR Checks Plan Fix\n\n## Overview\n\nUse gh to inspect PRs for:\n\n- Failing CI checks (GitHub Actions)\n- Merge conflicts\n- Update Branch requirements (base branch advanced)\n- Reviewer comments (review summaries, inline comments, issue comments)\n- Change Requests from reviewers\n- Unresolved review threads\n\nThen propose a fix plan, implement after explicit approval, and optionally resolve threads and notify reviewers.\n\n- Depends on the `plan` skill for drafting and approving the fix plan.\n\nPrereq:","body":"# Gh PR Checks Plan Fix\n\n## Overview\n\nUse gh to inspect PRs for:\n\n- Failing CI checks (GitHub Actions)\n- Merge conflicts\n- Update Branch requirements (base branch advanced)\n- Reviewer comments (review summaries, inline comments, issue comments)\n- Change Requests from reviewers\n- Unresolved review threads\n\nThen propose a fix plan, implement after explicit approval, and optionally resolve threads and notify reviewers.\n\n- Depends on the `plan` skill for drafting and approving the fix plan.\n\nPrereq: ensure `gh` is authenticated (for example, run `gh auth login` once), then run `gh auth status` with escalated permissions (include workflow/repo scopes) so `gh` commands succeed.\n\n## Inputs\n\n- `repo`: path inside the repo (default `.`)\n- `pr`: PR number or URL (optional; defaults to current branch PR)\n- `mode`: inspection mode (`checks`, `conflicts`, `reviews`, `all`)\n- `max-review-comments`: max reviewer comments to list per category\n- `required-only`: limit CI checks to required checks only (uses `gh pr checks --required`)\n- `gh` authentication for the repo host\n\n## Quick start\n\n```bash\n# Inspect all (CI, conflicts, reviews) - default mode\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\"\n\n# CI checks only\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --mode checks\n\n# Conflicts only\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --mode conflicts\n\n# Reviews only (Change Requests + Unresolved Threads)\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --mode reviews\n\n# JSON output\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --json\n\n# Required checks only (if gh supports --required)\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --mode checks --required-only\n\n# Limit review comment output\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --max-review-comments 30\n\n# Resolve all unresolved threads after fixing\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --resolve-threads\n\n# Add a comment to notify reviewers\npython \"<path-to-skill>/scripts/inspect_pr_checks.py\" --repo \".\" --pr \"<number>\" --add-comment \"Fixed all issues. Please re-review.\"\n```\n\n## Workflow\n\n1. **Verify gh authentication.**\n   - Run `gh auth status` in the repo with escalated scopes (workflow/repo).\n   - If unauthenticated, ask the user to log in before proceeding.\n\n2. **Resolve the PR.**\n   - Prefer the current branch PR: `gh pr view --json number,url`.\n   - If the user provides a PR number or URL, use that directly.\n\n3. **Inspect based on mode:**\n\n   **Conflicts Mode (`--mode conflicts`):**\n   - Check `mergeable` and `mergeStateStatus` fields.\n   - If `CONFLICTING` or `DIRTY`, report conflict details.\n   - If `BEHIND`, report that the base branch advanced and an Update Branch is required.\n   - Suggest resolution steps: fetch base branch, merge/rebase, resolve conflicts.\n\n   **Reviews Mode (`--mode reviews`):**\n   - Fetch reviews with `CHANGES_REQUESTED` state.\n   - Fetch unresolved review threads using GraphQL.\n   - Fetch reviewer comments (review summaries, inline review comments, issue comments).\n   - Display reviewer, comment body, file path, and line number.\n   - Decide if reviewer feedback requires action (any change request, unresolved thread, or reviewer comment).\n\n   **Checks Mode (`--mode checks`):**\n   - Run bundled script to inspect failing CI checks.\n   - Add `--required-only` to limit output to required checks when supported.\n   - Fetch GitHub Actions logs and extract failure snippets.\n   - For external checks (Buildkite, etc.), report URL only.\n\n   **All Mode (`--mode all`):**\n   - Run all inspections above.\n\n4. **Summarize issues for the user.**\n   - Provide clear summary of all detected issues.\n   - Call out conflicts, change requests, unresolved threads, and CI failures.\n\n5. **Create a plan.**\n   - Use the `plan` skill to draft a fix plan and request approval.\n\n6. **Implement after approval.**\n   - Apply the approved plan, summarize diffs/tests.\n\n7. **Resolve review threads (optional).**\n   - With `--resolve-threads`, resolve all unresolved threads via GraphQL mutation.\n   - Requires `Repository Permissions > Contents: Read and Write`.\n\n8. **Notify reviewers (optional).**\n   - With `--add-comment \"message\"`, post a comment to the PR.\n   - Useful for notifying reviewers that issues have been addressed.\n\n9. **Recheck status.**\n   - After changes, suggest re-running `gh pr checks` to confirm.\n\n## Bundled Resources\n\n### scripts/inspect_pr_checks.py\n\nComprehensive PR inspection tool. Exits non-zero when issues remain.\n\n**Arguments:**\n\n| Argument | Default | Description |\n|----------|---------|-------------|\n| `--repo` | `.` | Path inside the target Git repository |\n| `--pr` | (current) | PR number or URL |\n| `--mode` | `all` | Inspection mode: `checks`, `conflicts`, `reviews`, `all` |\n| `--max-lines` | 160 | Max lines for log snippets |\n| `--context` | 30 | Context lines around failure markers |\n| `--max-review-comments` | 50 | Max reviewer comments to list per category |\n| `--required-only` | false | Limit CI checks to required checks only |\n| `--json` | false | Emit JSON output |\n| `--resolve-threads` | false | Resolve unresolved review threads |\n| `--add-comment` | (none) | Add a comment to the PR |\n\n**Exit codes:**\n\n- `0`: No issues found\n- `1`: Issues detected or error occurred\n\n## New Features\n\n### Conflict Detection\n\nDetects merge conflicts via `mergeable` and `mergeStateStatus` fields.\n\n- `CONFLICTING` / `DIRTY`: Conflict detected\n- `BEHIND`: Base branch advanced; Update Branch required\n- `MERGEABLE` / `CLEAN`: No conflicts\n\n### Change Request Handling\n\nFetches reviews with `state == \"CHANGES_REQUESTED\"` and displays:\n\n- Reviewer name\n- Review body\n- Submission timestamp\n\n### Reviewer Comments\n\nFetches reviewer feedback beyond change requests:\n\n- Review summaries with comment bodies\n- Inline review comments (file/line)\n- PR issue comments\n- Marks review action required if any reviewer feedback exists\n\n### Unresolved Review Threads\n\nUses GraphQL to fetch threads where `isResolved == false`:\n\n- File path and line number\n- Thread ID (for resolution)\n- Comment author and body\n- Outdated status\n\n### Resolve Conversation\n\nUse `--resolve-threads` to mark threads as resolved via GraphQL mutation `resolveReviewThread`.\n\n**Required permissions:**\n\n- Fine-grained PAT: `Pull requests` + `Contents: Read and Write`\n- Classic PAT: `repo` scope\n\n### Reviewer Notification\n\nUse `--add-comment \"message\"` to post a summary comment to the PR after fixes.\n\n## Output Examples\n\n### Text Output\n\n```text\nPR #123: Comprehensive Check Results\n============================================================\n\nMERGE STATUS\n------------------------------------------------------------\nMergeable: CONFLICTING\nMerge State: DIRTY\nBase: main <- Head: feature/my-branch\nAction Required: Resolve conflicts before merging\n\nCHANGE REQUESTS\n------------------------------------------------------------\nFrom @reviewer1 (2025-01-15):\n  \"Please fix these issues...\"\n\nUNRESOLVED REVIEW THREADS\n------------------------------------------------------------\n[1] src/main.ts:42\n    Thread ID: PRRT_xxx123\n    @reviewer1: This needs refactoring...\n\nCI FAILURES\n------------------------------------------------------------\nCheck: build\nDetails: https://github.com/...\nFailure snippet:\n  Error: TypeScript compilation failed\n  ...\n============================================================\n```\n\n### JSON Output\n\n```json\n{\n  \"pr\": \"123\",\n  \"conflicts\": {\n    \"hasConflicts\": true,\n    \"mergeable\": \"CONFLICTING\",\n    \"mergeStateStatus\": \"DIRTY\",\n    \"baseRefName\": \"main\",\n    \"headRefName\": \"feature/my-branch\"\n  },\n  \"changeRequests\": [\n    {\n      \"id\": 123456,\n      \"reviewer\": \"reviewer1\",\n      \"body\": \"Please fix these issues...\",\n      \"submittedAt\": \"2025-01-15T12:00:00Z\"\n    }\n  ],\n  \"unresolvedThreads\": [\n    {\n      \"id\": \"PRRT_xxx123\",\n      \"path\": \"src/main.ts\",\n      \"line\": 42,\n      \"comments\": [\n        {\"author\": \"reviewer1\", \"body\": \"This needs refactoring\"}\n      ]\n    }\n  ],\n  \"ciFailures\": [\n    {\n      \"name\": \"build\",\n      \"status\": \"ok\",\n      \"logSnippet\": \"...\"\n    }\n  ]\n}\n```\n"},"lastSynced":"2026-02-28T02:20:35.342Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub-centric AI Agents needing automated PR inspection and CI fix planning capabilities.","zh":"适用于需要自动化PR检查和CI修复规划功能的GitHub中心AI代理的理想选择。","ja":"GitHub中心のAIエージェントが自動化されたPR検査とCI修正計画機能を必要とする場合に最適です。","ko":"자동화된 PR 검사 및 CI 수정 계획 기능이 필요한 GitHub 중심 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA centrados en GitHub que necesitan capacidades de inspección de PR automatizada y planificación de soluciones de CI.","fr":"Idéal pour les agents d''IA centrés sur GitHub nécessitant des capacités d''inspection de PR automatisées et de planification de correction de CI.","de":"Ideal für GitHub-zentrierte KI-Agents, die automatisierte PR-Inspektion und CI-Fixplanungsfunktionen benötigen.","pt":"Ideal para Agentes de IA centrados no GitHub que precisam de capacidades de inspeção de PR automatizadas e planejamento de correção de CI.","ru":"Идеально для агентов ИИ, ориентированных на GitHub, которым необходимы автоматизированные возможности инспекции PR и планирования исправления CI.","ar":"مثالي للوكلاء الذكاء الاصطناعي المتمركزين على جيت هاب الذين يحتاجون إلى قدرات فحص مراقبة الإصدار الآلي وتخطيط إصلاح CI."},"recommendation":{"en":"Empowers agents to inspect PRs for failing CI checks, merge conflicts, and unresolved review threads, leveraging GitHub Actions and proposing fix plans using the `plan` skill, while optionally resolving threads and notifying reviewers via GitHub APIs and protocols.","zh":"赋予代理检查PR以失败的CI检查、合并冲突和未解决的审查线程的能力，利用GitHub Actions并使用`plan`技能提出修复计划，同时可选地解析线程并通过GitHub API和协议通知审查人员。","ja":"エージェントに、失敗したCIチェック、Mergeの競合、および未解決のレビュースレッドを持つPRを検査する機能を付与し、GitHub Actionsを利用し、`plan`スキルを使用して修正プランを提案し、オプションでスレッドを解決し、GitHub APIおよびプロトコルを介してレビュアーに通知します。","ko":"에이전트가 실패한 CI 검사, 병합 충돌 및 미해결 리뷰 스레드를 가진 PR을 검사할 수 있는 기능을 부여하고 GitHub Actions를 활용하며 `plan` 스킬을 사용하여 수정 계획을 제안하며 선택적으로 스레드를 해결하고 GitHub API 및 프로토콜을 통해 리뷰어에게 알립니다.","es":"Habilita a los agentes a inspeccionar las PR para detectar errores en las comprobaciones de CI, conflictos de fusión y hilos de revisión no resueltos, aprovechando GitHub Actions y proponiendo planes de solución mediante la habilidad `plan`, y opcionalmente resolviendo hilos y notificando a los revisores a través de GitHub APIs y protocolos.","fr":"Permet aux agents d''inspecter les PR pour détecter les erreurs de vérification de CI, les conflits de fusion et les threads de révision non résolus, en exploitant GitHub Actions et en proposant des plans de correction à l''aide de la compétence `plan`, et en résolvant éventuellement les threads et en notifiant les réviseurs via les API et les protocoles GitHub.","de":"Ermächtigt die Agenten, PRs auf fehlerhafte CI-Prüfungen, Merge-Konflikte und unbeantwortete Review-Threads zu überprüfen, GitHub Actions zu nutzen und über die Fähigkeit `plan` Fixpläne vorzuschlagen, und optional Threads zu lösen und Reviewer über GitHub-APIs und -Protokolle zu benachrichtigen.","pt":"Habilita os agentes a inspecionar PRs para verificações de CI com falha, conflitos de mesclagem e threads de revisão não resolvidas, aproveitando as GitHub Actions e propondo planos de correção usando a habilidade `plan`, enquanto opcionalmente resolve threads e notifica revisores via GitHub APIs e protocolos.","ru":"Наделяет агентов возможностью инспектировать PR для проверок CI с неудачами, конфликтов слияния и неразрешенных потоков ревью, используя GitHub Actions и предлагая планы исправления с помощью навыка `plan`, а также необязательно разрешая потоки и уведомляя рецензентов через GitHub API и протоколы.","ar":"تمكين الوكلاء من فحص مراقبة الإصدار للتحقق من اختبارات CI الفاشلة والتعارضات والخيطات غير المحلولة، واستخدام إجراءات جيت هاب واقتراح خطط الإصلاح باستخدام مهارة `plan` ، بالإضافة إلى حل الخيوط وإعلام المراجعين عبر واجهات برمجة تطبيقات جيت هاب والبروتوكولات بشكل اختياري."},"useCases":{"en":["Automating PR checks for failing CI builds","Debugging merge conflicts in GitHub repositories","Streamlining reviewer comment integration and change request management"],"zh":["自动化失败的CI构建的PR检查","调试GitHub存储库中的合并冲突","简化审查人员评论集成和更改请求管理"],"ja":["失敗したCIビルドのPRチェックの自動化","GitHubリポジトリ内のMergeの競合のデバッグ","レビューコメントの統合と変更リクエストの管理の簡素化"],"ko":["실패한 CI 빌드의 PR 검사 자동화","GitHub 리포지토리 내의 병합 충돌 디버깅","리뷰어 코멘트 통합 및 변경 요청 관리 간소화"],"es":["Automatización de comprobaciones de PR para compilaciones de CI con errores","Depuración de conflictos de fusión en repositorios de GitHub","Integración y administración de comentarios de revisores y solicitudes de cambios"],"fr":["Automatisation des vérifications de PR pour les builds de CI défectueux","Débogage des conflits de fusion dans les référentiels GitHub","Intégration et gestion des commentaires des réviseurs et des demandes de modification"],"de":["Automatisierung von PR-Prüfungen für fehlerhafte CI-Builds","Fehlerbehebung bei Merge-Konflikten in GitHub-Repositorys","Integration und Verwaltung von Reviewer-Kommentaren und Änderungsanfragen"],"pt":["Automatizar verificações de PR para compilações CI com falha","Depurar conflitos de mesclagem em repositórios GitHub","Otimizar a integração de comentários de revisor e gerenciamento de solicitações de alteração"],"ru":["Автоматизировать проверки PR для сборок CI с неудачами","Отладить конфликты слияния в репозиториях GitHub","Оптимизировать интеграцию комментариев рецензента и управление запросами на изменение"],"ar":["توسيع التحقق من مراقبة الإصدار للأشكال المترجمة CI الفاشلة","تصحيح أخطاء التعارض في مستودعات جيت هاب","بترتيب دمج تعليقات المراجعين وإدارة طلبات التغيير"]},"limitations":{"en":["Depends on the `plan` skill for fix plan drafting and approval","Requires GitHub API access and authentication","Limited to GitHub repositories with GitHub Actions CI/CD"],"zh":["依赖于`plan`技能进行修复计划草拟和批准","需要GitHub API访问和认证","仅限于具有GitHub Actions CI/CD的GitHub存储库"],"ja":["修正プランの草案作成と承認に`plan`スキルに依存","GitHub APIへのアクセスと認証が必要","GitHub Actions CI/CDを持つGitHubリポジトリに限定"],"ko":["수정 계획 초안 작성 및 승인에 `plan` 스킬에 의존","GitHub API 액세스 및 인증 필요","GitHub Actions CI/CD를 갖춘 GitHub 리포지토리에 제한"],"es":["Depende de la habilidad `plan` para la creación y aprobación de planes de solución","Requiere acceso y autenticación a la API de GitHub","Limitado a repositorios de GitHub con GitHub Actions CI/CD"],"fr":["Dépend de la compétence `plan` pour la rédaction et l''approbation des plans de correction","Nécessite l''accès et l''authentification à l''API GitHub","Limité aux référentiels GitHub avec GitHub Actions CI/CD"],"de":["Hängt von der Fähigkeit `plan` für die Erstellung und Genehmigung von Fixplänen ab","Benötigt GitHub-API-Zugriff und -Authentifizierung","Begrenzt auf GitHub-Repositorys mit GitHub Actions CI/CD"],"pt":["Depende da habilidade `plan` para elaboração e aprovação do plano de correção","Exige acesso e autenticação à API do GitHub","Limitado a repositórios GitHub com GitHub Actions CI/CD"],"ru":["Зависит от навыка `plan` для составления и утверждения плана исправления","Требует доступа и аутентификации к API GitHub","Ограничен репозиториями GitHub с GitHub Actions CI/CD"],"ar":["يعتمد على مهارة `plan` لصياغة وموافقة خطة الإصلاح","يتطلب الوصول والمصادقة على واجهة برمجة تطبيقات جيت هاب","محدود بمستودعات جيت هاب مع إجراءات جيت هاب CI/CD"]},"version":3},"contentHash":"94c0546d84a24daa25732db63c4d6f8102ef7a66085c6f261fcc57ffe31e1cf8","qualityScore":55}');
DELETE FROM skills_fts WHERE id = 'akiojin/llmlb/gh-fix-ci';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('akiojin/llmlb/gh-fix-ci', 'gh-fix-ci', 'akiojin', 'llmlb', 'community', 'gh-fix-ci akiojin llmlb community gh-fix-ci是一个分布式LLM路由器，具有负载均衡和自动模型分布，用于提高CI效率 gh-fix-ciは、分散型LLMルーターであり、負荷分散と自動モデル分散を備えています。CIの効率を向上させます gh-fix-ci는 분산형 LLM 라우터로 로드 밸런싱과 자동 모델 분산을 통해 CI 효율성을 높여줍니다 gh-fix-ci es un enrutador LLM distribuido que ofrece equilibrio de carga y distribución automática de modelos para mejorar el rendimiento gh-fix-ci est un routeur LLM distribué qui propose un équilibrage de charge et une distribution automatique de modèles pour améliorer les performances gh-fix-ci ist ein verteilter LLM-Router, der Lastenausgleich und automatische Modellverteilung bietet, um die Leistung zu verbessern O gh-fix-ci é uma ferramenta de IA que fornece um roteador LLM distribuído com balanceamento de carga e distribuição automática de modelos gh-fix-ci - это инструмент ИИ, который предоставляет распределенный маршрутизатор LLM с балансировкой нагрузки и автоматическим распределением моделей gh-fix-ci هو أداة ذكاء اصطناعي تقدم مُوزع LLM الموزع مع توازن الحمل والتوزيع التلقائي للنماذج Distributed LLM router with load balancing and automatic model distribution 如何使用gh-fix-ci 什么是分布式LLM路由 gh-fix-ci安装 gh-fix-ci设置指南 gh-fix-ci替代品 gh-fix-ci vs 其他CI工具 LLM路由器 CI优化 自动模型分布 Distributed LLM router with load balancing and automatic model distribution');
