INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Thomascountz/claude_skills/github', 'github', 'Thomascountz', 'claude_skills', 'community', 'github Thomascountz claude_skills community 本技能提供了使用GitHub CLI（gh）工具检索和分析GitHub仓库、拉取请求、问题和工作流信息的综合指导 このスキルは、GitHub CLI（gh）ツールを使用してGitHubリポジトリ、プルリクエスト、イシュー、ワークフローに関する情報を取得、分析するための包括的なガイダンスを提供する 이 스킬은 GitHub CLI(gh) 도구를 사용하여 GitHub 저장소, 풀 요청, 문제, 워크플로에 대한 정보를 검색하고 분석하는 방법에 대한 포괄적인 가이드를 제공합니다 La habilidad GitHub CLI proporciona una guía completa para utilizar la herramienta gh y integrarla con Jira CLI La compétence GitHub CLI offre un guide complet pour utiliser l''outil gh et l''intégrer à Jira CLI Die GitHub CLI-Fähigkeit bietet eine umfassende Anleitung zur Verwendung des Tools gh und dessen Integration in Jira CLI A habilidade GitHub CLI fornece orientação abrangente para usar a ferramenta gh para recuperar e analisar informações de repositórios GitHub Навык GitHub CLI предоставляет всестороннее руководство по использованию инструмента gh для извлечения и анализа информации из репозиториев GitHub المهارة واجهة سطر الأوامر جيثب توفر إرشادات شاملة لاستخدام أداة جيثب لاسترجاع وتحليل المعلومات من المستودعات جيثب Claude Code skills for GitHub and Jira CLI integration GitHub CLI gh工具 仓库信息 拉取请求 问题管理 工作流自动化 命令行交互 Claude Code skills for GitHub and Jira CLI integration');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sundial-org/awesome-openclaw-skills/github-kb', 'community', 'sundial-org', 'awesome-openclaw-skills', 'sundial-org/awesome-openclaw-skills', 'github-kb', 0, 0, 55, '2026-02-20T04:13:19.571Z', '2026-02-20T04:22:44.410Z', '8d62830e2d00b0b63fe36620febd451b583dbcfad38acf354a1d77942401e303', '{"id":"sundial-org/awesome-openclaw-skills/github-kb","name":"github-kb","description":{"zh":"github-kb技能为您提供管理本地GitHub知识库和搜索功能的能力，通过gh CLI接口","ja":"github-kbスキルはローカルGitHubナレッジベースの管理と検索機能を提供","ko":"github-kb 스킬은 로컬 GitHub 지식베이스 관리와 검색 기능을 제공","es":"La base de conocimientos de GitHub es una herramienta para gestionar proyectos de forma local y realizar búsquedas con gh CLI","fr":"La base de connaissances GitHub est un outil pour gérer des projets en local et effectuer des recherches avec gh CLI","de":"Die GitHub-Wissensbasis ist ein Tool zum Verwalten von Projekten in lokalen und Durchführen von Suchen mit gh CLI","pt":"O GitHub Knowledge Base é uma ferramenta para gerenciar uma base de conhecimento local do GitHub e realizar buscas via gh CLI. Ele permite configurar variáveis de ambiente para uso","ru":"База Знаний GitHub - это инструмент для управления локальной базой знаний GitHub и выполнения поиска через gh CLI. Он позволяет настраивать переменные среды для использования","ar":"قاعدة المعارف جيثب هي أداة لإدارة قاعدة معرفة محلية لجيثب و実行 عمليات البحث عبر واجهة سطر الأوامر gh. وهي تسمح بضبط متغيرات البيئة للاستخدام","en":"Top OpenClaw skills, regularly updated with the most popular and useful ones."},"seo":{"title":{"zh":"GitHub 知识库管理工具","ja":"GitHub ナレッジベース管理ツール","ko":"GitHub 지식베이스 관리 도구","es":"GitHub Knowledge Base: gestiona tus proyectos","fr":"Base de connaissances GitHub : gérer vos projets","de":"GitHub-Wissensbasis: Verwalten Sie Ihre Projekte","pt":"GitHub Knowledge Base: Otimize Seu Fluxo de Trabalho","ru":"Б