INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sundial-org/awesome-openclaw-skills/github-kb', 'github-kb', 'sundial-org', 'awesome-openclaw-skills', 'community', 'github-kb sundial-org awesome-openclaw-skills community github-kb技能为您提供管理本地GitHub知识库和搜索功能的能力，通过gh CLI接口 github-kbスキルはローカルGitHubナレッジベースの管理と検索機能を提供 github-kb 스킬은 로컬 GitHub 지식베이스 관리와 검색 기능을 제공 La base de conocimientos de GitHub es una herramienta para gestionar proyectos de forma local y realizar búsquedas con gh CLI La base de connaissances GitHub est un outil pour gérer des projets en local et effectuer des recherches avec gh CLI Die GitHub-Wissensbasis ist ein Tool zum Verwalten von Projekten in lokalen und Durchführen von Suchen mit gh CLI O GitHub Knowledge Base é uma ferramenta para gerenciar uma base de conhecimento local do GitHub e realizar buscas via gh CLI. Ele permite configurar variáveis de ambiente para uso База Знаний GitHub - это инструмент для управления локальной базой знаний GitHub и выполнения поиска через gh CLI. Он позволяет настраивать переменные среды для использования قاعدة المعارف جيثب هي أداة لإدارة قاعدة معرفة محلية لجيثب و実行 عمليات البحث عبر واجهة سطر الأوامر gh. وهي تسمح بضبط متغيرات البيئة للاستخدام Top OpenClaw skills, regularly updated with the most popular and useful ones. GitHub知识库 github-kb gh CLI 本地知识库 搜索功能 私有仓库 Top OpenClaw skills, regularly updated with the most popular and useful ones.');
