INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Demerzels-lab/elsamultiskillagent/github-kb', 'github-kb', 'Demerzels-lab', 'elsamultiskillagent', 'community', 'github-kb Demerzels-lab elsamultiskillagent community github-kb技能用于管理本地GitHub知识库，并提供GitHub搜索功能 github-kbスキルはローカルGitHubナレッジベースを管理し、GitHub検索機能を提供 github-kb 스킬은 로컬 GitHub 지식베이스를 관리하고 GitHub 검색 기능을 제공 La habilidad github-kb permite gestionar un repositorio de conocimientos de GitHub local y ofrecer capacidades de búsqueda en GitHub La compétence github-kb permet de gérer un référentiel de connaissances GitHub local et d''offrir des capacités de recherche sur GitHub Die Fähigkeit github-kb ermöglicht die Verwaltung eines lokalen GitHub-Wissensrepositories und bietet GitHub-Suchfunktionen O agente GitHub Knowledge Base permite gerenciar uma base de conhecimento local do GitHub e realizar pesquisas via CLI do GitHub. Агент База Знаний GitHub позволяет управлять локальной базой знаний GitHub и выполнять поиск через CLI GitHub. وكلاء قاعدة المعرفة جيثب يسمح بإدارة قاعدة معرفة جيثب المحلية والبحث من خلال واجهة سطر الأوامر جيثب OpenClaw AI Agent Skills Directory - Discover 1700+ AI Agent Skills github-kb GitHub知识库 gh CLI 本地知识库管理 GitHub搜索 私有仓库 环境变量 OpenClaw AI Agent Skills Directory - Discover 1700+ AI Agent Skills');
