INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vercel/ai/develop-ai-functions-example', 'develop-ai-functions-example', 'vercel', 'ai', 'community', 'develop-ai-functions-example vercel ai community AI Toolkit 是一个免费的开源库，用于构建 AI 驱动的应用和代理。它提供了 TypeScript 开发示例，帮助您快速入门 AI Toolkit は、AI ドリブンのアプリケーションとエージェントを構築するための無料のオープンソース ライブラリです。TypeScript 開発例を提供しています AI Toolkit 은 AI 구동 애플리케이션과 에이전트를 구축하기 위한 무료 오픈소스 라이브러리입니다. TypeScript 개발 예시를 제공합니다 AI Toolkit es una biblioteca de código abierto para desarrollar aplicaciones y agentes con IA. Ofrece ejemplos de funciones de IA para validar y probar. AI Toolkit est une bibliothèque open source pour développer des applications et des agents avec IA. Elle propose des exemples de fonctions d''IA pour valider et tester. AI Toolkit ist eine Open-Source-Bibliothek zum Entwickeln von Anwendungen und Agenten mit IA. Sie bietet Beispiele für IA-Funktionen zur Überprüfung und zum Testen. O AI Toolkit é uma biblioteca de código aberto para TypeScript que permite desenvolver aplicações e agentes com capacidades de IA. Aprenda a usar exemplos de funções de IA para validar e testar suas aplicações AI Toolkit - это открытая библиотека для TypeScript, которая позволяет разрабатывать приложения и агенты с возможностями ИИ. Узнайте, как использовать примеры функций ИИ для проверки и тестирования ваших приложений أداة AI Toolkit هي مكتبة مفتوحة المصدر لغة TypeScript تتيح تطوير التطبيقات والوكلاء ذوي قدرات الإي الأي. تعلم كيفية استخدام أمثلة الدوال الإي الأي لتحقق واختبار تطبيقاتك The AI Toolkit for TypeScript. From the creators of Next.js, the AI SDK is a free open-source library for building AI-powered applications and agents AI Toolkit TypeScript AI 驱动的应用 AI 代理 开源库 免费开发库 The AI Toolkit for TypeScript. From the creators of Next.js, the AI SDK is a free open-source library for building AI-powered applications and agents ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('openai/skills/security-ownership-map', 'community', 'openai', 'skills', 'openai/skills', 'security-ownership-map', 0, 0, 55, '2026-02-20T04:13:19.576Z', '2026-02-20T04:43:13.535Z', 'f06c1a59247569326702c945f397af163ea96cf2ecfdf2dde280605bf89a3ec8', '{"id":"openai/skills/security-ownership-map","name":"security-ownership-map","description":{"zh":"代码安全所有权地图是一个使用Python和Networkx构建的 bipartite 图，用于计算代码文件的所有权风险","ja":"セキュリティ所有権マップは、PythonとNetworkxを使用して構築された二部グラフであり、コードファイルの所有権リスクを計算するために使用","ko":"코드 보안 소유권 맵은 Python과 Networkx를 사용하여 구축된 이분 그래프로서 코드 파일의 소유권 위험을 계산하는 데 사용","es":"El mapa de propiedad de seguridad crea un grafo bipartito de personas y archivos desde el historial de git y calcula el riesgo de propiedad.","fr":"La carte de propriété de sécurité crée un graphe bipartite de personnes et de fichiers à partir de l''historique de git et calcule le risque de propriété.","de":"Die Sicherheitseigentums-Karte erstellt ein bipartites Graphen von Personen und Dateien aus der Git-Historie und berechnet das Eigentumsrisiko.","pt":"O mapa de propriedade de segurança é uma ferramenta que constrói um gráfico bipartido de pessoas e arquivos do histórico do Git para calcular o risco de propriedade","ru":"Карта собственности безопасности - это инструмент, который строит двудольный граф людей и файлов из истории Git для расчета риска собственности","ar":"خريطة ملكية الأمان هي أداة تبني مخططًا ثنائيًا للأشخاص والملفات من تاريخ Git لحساب مخاطر الملكية","en":"Skills Catalog for Codex"},"seo":{"title":{"zh":"代码安全所有权地图","ja":"セキュリティ所有権マップ","ko":"코드 보안 소유권 맵","es":"Mapa de Propiedad de Seguridad","fr":"Carte de Propriété de Sécurité","de":"Sicherheitseigentums-Karte","pt":"Mapa de Propriedade de Segurança","ru":"Карта Собственности Безопасности","ar":"خريطة ملكية الأمان","en":"security-ownership-map"},"description":{"zh":"代码安全所有权地图是一个使用Python和Networkx构建的 bipartite 图，用于计算代码文件的所有权风险","ja":"セキュリティ所有権マップは、PythonとNetworkxを使用して構築された二部グラフであり、コードファイルの所有権リスクを計算するために使用","ko":"코드 보안 소유권 맵은 Python과 Networkx를 사용하여 구축된 이분 그래프로서 코드 파일의 소유권 위험을 계산하는 데 사용","es":"El mapa de propiedad de seguridad crea un grafo bipartito de personas y archivos desde el historial de git y calcula el riesgo de propiedad.","fr":"La carte de propriété de sécurité crée un graphe bipartite de personnes et de fichiers à partir de l''historique de git et calcule le risque de propriété.","de":"Die Sicherheitseigentums-Karte erstellt ein bipartites Graphen von Personen und Dateien aus der Git-Historie und berechnet das Eigentumsrisiko.","pt":"O mapa de propriedade de segurança é uma ferramenta que constrói um gráfico bipartido de pessoas e arquivos do histórico do Git para calcular o risco de prop...","ru":"Карта собственности безопасности - это инструмент, который строит двудольный граф людей и файлов из истории Git для расчета риска собственности","ar":"خريطة ملكية الأمان هي أداة تبني مخططًا ثنائيًا للأشخاص والملفات من تاريخ Git لحساب مخاطر الملكية","en":"Skills Catalog for Codex"},"definition":{"en":"Skills Catalog for Codex"},"features":{"zh":["使用Python和Networkx构建bipartite图","计算代码文件的所有权风险","导出Neo4j和Gephi图形","使用Jaccard相似度构建文件共同变化图","忽略大型和噪音的提交"],"ja":["PythonとNetworkxを使用して二部グラフを構築","コードファイルの所有権リスクを計算","Neo4jとGephiのグラフをエクスポート","Jaccard類似度を使用してファイルの共同変更グラフを構築","大きなノイズのあるコミットを無視"],"ko":["Python과 Networkx를 사용하여 이분 그래프를 구축","코드 파일의 소유권 위험을 계산","Neo4j와 Gephi 그래프를 내보내기","Jaccard 유사도를 사용하여 파일 공동 변경 그래프를 구축","큰 노이즈가 있는 커밋을 무시"],"es":["Grafo bipartito de personas y archivos","Cálculo de riesgo de propiedad","Exportación de artefactos de grafo para Neo4j/Gephi","Detección de comunidad con networkx","Construcción de un grafo de co-cambio de archivos"],"fr":["Graphe bipartite de personnes et de fichiers","Calcul du risque de propriété","Exportation d''artefacts de graphe pour Neo4j/Gephi","Détection de communauté avec networkx","Construction d''un graphe de co-changement de fichiers"],"de":["Bipartiter Graph von Personen und Dateien","Berechnung des Eigentumsrisikos","Export von Graphenartefakten für Neo4j/Gephi","Community-Erkennung mit networkx","Erstellung eines Datei-Co-Change-Graphen"],"pt":["Constrói um gráfico bipartido de pessoas e arquivos do histórico do Git","Calcula o risco de propriedade","Exporta artefatos de gráfico para Neo4j/Gephi","Constroi um gráfico de co-mudança de arquivos","Ignora commits grandes e barulhentos"],"ru":["Строит двудольный граф людей и файлов из истории Git","Расчитывает риск собственности","Экспортирует графические артефакты в Neo4j/Gephi","Строит граф совместных изменений файлов","Игнорирует большие и шумные коммиты"],"ar":["يبني مخططًا ثنائيًا للأشخاص والملفات من تاريخ Git","يحسب مخاطر الملكية","يصدر مكونات المخطط إلى Neo4j/Gephi","يبني مخططًا لتغيير الملفات المشترك","يتجاهل الإعدادات الكبيرة والصاخبة"]},"keywords":{"zh":["代码安全","所有权地图","Python","Networkx","git历史","所有权风险","Neo4j","Gephi"],"ja":["セキュリティ","所有権マップ","Python","Networkx","Git履歴","所有権リスク","Neo4j","Gephi"],"ko":["코드 보안","소유권 맵","Python","Networkx","git 기록","소유권 위험","Neo4j","Gephi"],"es":["mapa de propiedad de seguridad","seguridad de código","grafo bipartito","networkx","git","riesgo de propiedad"],"fr":["carte de propriété de sécurité","sécurité de code","graphe bipartite","networkx","git","risque de propriété"],"de":["Sicherheitseigentums-Karte","Code-Sicherheit","bipartiter Graph","networkx","git","Eigentumsrisiko"],"pt":["segurança","propriedade","git","gráfico bipartido","risco de propriedade","neo4j","gephi","desenvolvimento de software"],"ru":["безопасность","собственность","git","двудольный граф","риск собственности","neo4j","gephi","разработка программного обеспечения"],"ar":["أمان","ملكية","git","مخطط ثنائي","مخاطر الملكية","neo4j","gephi","تطوير البرمجيات"]}},"owner":"openai","repo":"skills","repoPath":"openai/skills","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.576Z","topics":[],"category":"community","skillMd":{"name":"security-ownership-map","description":"Analyze git repositories to build a security ownership topology (people-to-file), compute bus factor and sensitive-code ownership, and export CSV/JSON for graph databases and visualization. Trigger only when the user explicitly wants a security-oriented ownership or bus-factor analysis grounded in git history (for example: orphaned sensitive code, security maintainers, CODEOWNERS reality checks for risk, sensitive hotspots, or ownership clusters). Do not trigger for general maintainer lists or non-security ownership questions.","bodyPreview":"# Security Ownership Map\n\n## Overview\n\nBuild a bipartite graph of people and files from git history, then compute ownership risk and export graph artifacts for Neo4j/Gephi. Also build a file co-change graph (Jaccard similarity on shared commits) to cluster files by how they move together while ignoring large, noisy commits.\n\n## Requirements\n\n- Python 3\n- `networkx` (required; community detection is enabled by default)\n\nInstall with:\n\n```bash\npip install networkx\n```\n\n## Workflow\n\n1. Scope the re","body":"# Security Ownership Map\n\n## Overview\n\nBuild a bipartite graph of people and files from git history, then compute ownership risk and export graph artifacts for Neo4j/Gephi. Also build a file co-change graph (Jaccard similarity on shared commits) to cluster files by how they move together while ignoring large, noisy commits.\n\n## Requirements\n\n- Python 3\n- `networkx` (required; community detection is enabled by default)\n\nInstall with:\n\n```bash\npip install networkx\n```\n\n## Workflow\n\n1. Scope the repo and time window (optional `--since/--until`).\n2. Decide sensitivity rules (use defaults or provide a CSV config).\n3. Build the ownership map with `scripts/run_ownership_map.py` (co-change graph is on by default; use `--cochange-max-files` to ignore supernode commits).\n4. Communities are computed by default; graphml output is optional (`--graphml`).\n5. Query the outputs with `scripts/query_ownership.py` for bounded JSON slices.\n6. Persist and visualize (see `references/neo4j-import.md`).\n\nBy default, the co-change graph ignores common “glue” files (lockfiles, `.github/*`, editor config) so clusters reflect actual code movement instead of shared infra edits. Override with `--cochange-exclude` or `--no-default-cochange-excludes`. Dependabot commits are excluded by default; override with `--no-default-author-excludes` or add patterns via `--author-exclude-regex`.\n\nIf you want to exclude Linux build glue like `Kbuild` from co-change clustering, pass:\n\n```bash\npython skills/skills/security-ownership-map/scripts/run_ownership_map.py \\\n  --repo /path/to/linux \\\n  --out ownership-map-out \\\n  --cochange-exclude \"**/Kbuild\"\n```\n\n## Quick start\n\nRun from the repo root:\n\n```bash\npython skills/skills/security-ownership-map/scripts/run_ownership_map.py \\\n  --repo . \\\n  --out ownership-map-out \\\n  --since \"12 months ago\" \\\n  --emit-commits\n```\n\nDefaults: author identity, author date, and merge commits excluded. Use `--identity committer`, `--date-field committer`, or `--include-merges` if needed.\n\nExample (override co-change excludes):\n\n```bash\npython skills/skills/security-ownership-map/scripts/run_ownership_map.py \\\n  --repo . \\\n  --out ownership-map-out \\\n  --cochange-exclude \"**/Cargo.lock\" \\\n  --cochange-exclude \"**/.github/**\" \\\n  --no-default-cochange-excludes\n```\n\nCommunities are computed by default. To disable:\n\n```bash\npython skills/skills/security-ownership-map/scripts/run_ownership_map.py \\\n  --repo . \\\n  --out ownership-map-out \\\n  --no-communities\n```\n\n## Sensitivity rules\n\nBy default, the script flags common auth/crypto/secret paths. Override by providing a CSV file:\n\n```\n# pattern,tag,weight\n**/auth/**,auth,1.0\n**/crypto/**,crypto,1.0\n**/*.pem,secrets,1.0\n```\n\nUse it with `--sensitive-config path/to/sensitive.csv`.\n\n## Output artifacts\n\n`ownership-map-out/` contains:\n\n- `people.csv` (nodes: people)\n- `files.csv` (nodes: files)\n- `edges.csv` (edges: touches)\n- `cochange_edges.csv` (file-to-file co-change edges with Jaccard weight; omitted with `--no-cochange`)\n- `summary.json` (security ownership findings)\n- `commits.jsonl` (optional, if `--emit-commits`)\n- `communities.json` (computed by default from co-change edges when available; includes `maintainers` per community; disable with `--no-communities`)\n- `cochange.graph.json` (NetworkX node-link JSON with `community_id` + `community_maintainers`; falls back to `ownership.graph.json` if no co-change edges)\n- `ownership.graphml` / `cochange.graphml` (optional, if `--graphml`)\n\n`people.csv` includes timezone detection based on author commit offsets: `primary_tz_offset`, `primary_tz_minutes`, and `timezone_offsets`.\n\n## LLM query helper\n\nUse `scripts/query_ownership.py` to return small, JSON-bounded slices without loading the full graph into context.\n\nExamples:\n\n```bash\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out people --limit 10\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out files --tag auth --bus-factor-max 1\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out person --person alice@corp --limit 10\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out file --file crypto/tls\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out cochange --file crypto/tls --limit 10\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out summary --section orphaned_sensitive_code\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out community --id 3\n```\n\nUse `--community-top-owners 5` (default) to control how many maintainers are stored per community.\n\n## Basic security queries\n\nRun these to answer common security ownership questions with bounded output:\n\n```bash\n# Orphaned sensitive code (stale + low bus factor)\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out summary --section orphaned_sensitive_code\n\n# Hidden owners for sensitive tags\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out summary --section hidden_owners\n\n# Sensitive hotspots with low bus factor\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out summary --section bus_factor_hotspots\n\n# Auth/crypto files with bus factor <= 1\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out files --tag auth --bus-factor-max 1\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out files --tag crypto --bus-factor-max 1\n\n# Who is touching sensitive code the most\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out people --sort sensitive_touches --limit 10\n\n# Co-change neighbors (cluster hints for ownership drift)\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out cochange --file path/to/file --min-jaccard 0.05 --limit 20\n\n# Community maintainers (for a cluster)\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out community --id 3\n\n# Monthly maintainers for the community containing a file\npython skills/skills/security-ownership-map/scripts/community_maintainers.py \\\n  --data-dir ownership-map-out \\\n  --file network/card.c \\\n  --since 2025-01-01 \\\n  --top 5\n\n# Quarterly buckets instead of monthly\npython skills/skills/security-ownership-map/scripts/community_maintainers.py \\\n  --data-dir ownership-map-out \\\n  --file network/card.c \\\n  --since 2025-01-01 \\\n  --bucket quarter \\\n  --top 5\n```\n\nNotes:\n- Touches default to one authored commit (not per-file). Use `--touch-mode file` to count per-file touches.\n- Use `--window-days 90` or `--weight recency --half-life-days 180` to smooth churn.\n- Filter bots with `--ignore-author-regex ''(bot|dependabot)''`.\n- Use `--min-share 0.1` to show stable maintainers only.\n- Use `--bucket quarter` for calendar quarter groupings.\n- Use `--identity committer` or `--date-field committer` to switch from author attribution.\n- Use `--include-merges` to include merge commits (excluded by default).\n\n### Summary format (default)\n\nUse this structure, add fields if needed:\n\n```json\n{\n  \"orphaned_sensitive_code\": [\n    {\n      \"path\": \"crypto/tls/handshake.rs\",\n      \"last_security_touch\": \"2023-03-12T18:10:04+00:00\",\n      \"bus_factor\": 1\n    }\n  ],\n  \"hidden_owners\": [\n    {\n      \"person\": \"alice@corp\",\n      \"controls\": \"63% of auth code\"\n    }\n  ]\n}\n```\n\n## Graph persistence\n\nUse `references/neo4j-import.md` when you need to load the CSVs into Neo4j. It includes constraints, import Cypher, and visualization tips.\n\n## Notes\n\n- `bus_factor_hotspots` in `summary.json` lists sensitive files with low bus factor; `orphaned_sensitive_code` is the stale subset.\n- If `git log` is too large, narrow with `--since` or `--until`.\n- Compare `summary.json` against CODEOWNERS to highlight ownership drift.\n"},"lastSynced":"2026-02-20T04:43:13.535Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced security visualization capabilities through bipartite graphs and community detection.","zh":"非常适合需要通过二分图和社区检测来实现高级安全可视化能力的代码分析代理。","ja":"コード分析エージェントが二部グラフとコミュニティ検出を通じて高度なセキュリティ可視化機能を必要とする場合に最適です。","ko":"코드 분석 에이전트가 비파티트 그래프와 커뮤니티 감지를 통해 고급 보안 시각화 기능을 필요로 할 경우 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan capacidades de visualización de seguridad avanzadas a través de gráficos bipartitos y detección de comunidades.","fr":"Parfait pour les agents d''analyse de code nécessitant des capacités de visualisation de sécurité avancées via des graphiques bipartites et une détection de communautés.","de":"Perfekt für Code-Analyse-Agents, die erweiterte Sicherheitsvisualisierungsfunktionen durch bipartite Graphen und Community-Erkennung benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de capacidades avançadas de visualização de segurança por meio de grafos bipartidos e detecção de comunidades.","ru":"Идеально подходит для агентов кодового анализа, которым необходимы расширенные возможности визуализации безопасности с помощью бипартитных графов и обнаружения сообществ.","ar":"مثالي للوكلاء مُحللين الشفرة الذين يحتاجون إلى إمكانيات متقدمة لمرئية الأمان من خلال الرسوم البيانية ثنائية الجزء وتحديد المجتمع."},"recommendation":{"en":"Empowers agents to compute ownership risk and export graph artifacts for Neo4j/Gephi, utilizing Python 3 and the networkx library to build file co-change graphs based on Jaccard similarity.","zh":"使代理能够计算所有权风险并将图形制品导出到Neo4j/Gephi，利用Python 3和networkx库根据Jaccard相似度建立文件协同更改图。","ja":"エージェントが所有権リスクを計算し、Neo4j/Gephiにグラフアーティファクトをエクスポートできるようにし、Jaccard類似度に基づいてファイルの共同変更グラフをPython 3とnetworkxライブラリで構築します。","ko":"에이전트가 소유권 위험을 계산하고 Neo4j/Gephi에 그래프 아티팩트를 내보낼 수 있도록하며, Jaccard 유사성을 기반으로 파일의 공유 변경 그래프를 Python 3와 networkx 라이브러리로 구축합니다.","es":"Habilita a los agentes para calcular el riesgo de propiedad y exportar artefactos de gráficos para Neo4j/Gephi, utilizando Python 3 y la biblioteca networkx para construir gráficos de co-cambio de archivos basados en la similitud de Jaccard.","fr":"Permet aux agents de calculer le risque de propriété et d''exporter des artefacts de graphiques pour Neo4j/Gephi, en utilisant Python 3 et la bibliothèque networkx pour construire des graphiques de co-changement de fichiers basés sur la similarité de Jaccard.","de":"Ermöglicht es Agenten, den Eigentumsrisiko zu berechnen und Graph-Artefakte für Neo4j/Gephi zu exportieren, indem Python 3 und die networkx-Bibliothek verwendet werden, um Datei-Co-Change-Graphen auf der Grundlage der Jaccard-Ähnlichkeit zu erstellen.","pt":"Habilita os agentes a calcular o risco de propriedade e exportar artefatos de gráfico para Neo4j/Gephi, utilizando Python 3 e a biblioteca networkx para construir gráficos de co-mudança de arquivos com base na semelhança de Jaccard.","ru":"Наделяет агентов возможностью вычислять риск собственности и экспортировать графические артефакты для Neo4j/Gephi, используя Python 3 и библиотеку networkx для построения графиков совместных изменений файлов на основе сходства Джаккарда.","ar":"تمكّن الوكلاء من حساب مخاطر الملكية وتصدير مكونات الرسم البياني إلى Neo4j/Gephi، باستخدام Python 3 ومكتبة networkx لبناء رسوم بيانية لتغييرات الملفات المشتركة بالاعتماد على تشابه Jaccard."},"useCases":{"en":["Visualizing security ownership through bipartite graphs of people and files","Computing ownership risk from git history","Clustering files by co-change patterns using Jaccard similarity"],"zh":["通过人和文件的二分图来可视化安全所有权","从git历史计算所有权风险","使用Jaccard相似度根据协同更改模式对文件进行聚类"],"ja":["人とファイルの二部グラフを通じてセキュリティ所有権を視覚化する","git履歴から所有権リスクを計算する","Jaccard類似度を使用して共同変更パターンに基づいてファイルをクラスタリングする"],"ko":["사람과 파일의 비파티트 그래프를 통해 보안 소유권을 시각화하는 것","git 기록에서 소유권 위험을 계산하는 것","Jaccard 유사성을 사용하여 공유 변경 패턴에 따라 파일을 클러스터링하는 것"],"es":["Visualizar la propiedad de seguridad a través de gráficos bipartitos de personas y archivos","Calcular el riesgo de propiedad a partir del historial de git","Agrupar archivos por patrones de co-cambio utilizando la similitud de Jaccard"],"fr":["Visualiser la propriété de sécurité via des graphiques bipartites de personnes et de fichiers","Calculer le risque de propriété à partir de l''historique de git","Regrouper des fichiers par des modèles de co-changement en utilisant la similarité de Jaccard"],"de":["Sicherheitseigentum durch bipartite Graphen von Personen und Dateien visualisieren","Eigentumsrisiko aus Git-Verlaufsdaten berechnen","Dateien nach Co-Change-Mustern mit Jaccard-Ähnlichkeit gruppieren"],"pt":["Visualizando a propriedade de segurança por meio de grafos bipartidos de pessoas e arquivos","Computando o risco de propriedade a partir do histórico do git","Agrupando arquivos por padrões de co-mudança usando semelhança de Jaccard"],"ru":["Визуализация владения безопасностью с помощью бипартитных графов людей и файлов","Вычисление риска собственности из истории git","Кластеризация файлов по закономерностям совместных изменений с помощью сходства Джаккарда"],"ar":["مرئية ملكية الأمان من خلال الرسوم البيانية ثنائية الجزء للأشخاص والملفات","حساب مخاطر الملكية من سجل التعديلات","تجميع الملفات حسب أنماط التغيير المشترك باستخدام تشابه Jaccard"]},"limitations":{"en":["Requires Python 3","Dependent on networkx library","Limited to analyzing git history"],"zh":["需要Python 3","依赖于networkx库","仅限于分析git历史"],"ja":["Python 3を必要とする","networkxライブラリに依存する","git履歴の分析のみに限定される"],"ko":["Python 3이 필요함","networkx 라이브러리에 의존함","git 기록 분석에만 제한됨"],"es":["Requiere Python 3","Dependiente de la biblioteca networkx","Limitado al análisis del historial de git"],"fr":["Nécessite Python 3","Dépendant de la bibliothèque networkx","Limité à l''analyse de l''historique de git"],"de":["Benötigt Python 3","Abhängig von der networkx-Bibliothek","Begrenzt auf die Analyse des Git-Verlaufs"],"pt":["Requer Python 3","Dependente da biblioteca networkx","Limitado à análise do histórico do git"],"ru":["Требует Python 3","Зависит от библиотеки networkx","Ограничен анализом истории git"],"ar":["يتطلب Python 3","يعتمد على مكتبة networkx","محدود بتحليل سجل التعديلات"]},"version":3},"contentHash":"f06c1a59247569326702c945f397af163ea96cf2ecfdf2dde280605bf89a3ec8","qualityScore":55}');
