INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jeffallan/claude-skills/websocket-engineer', 'websocket-engineer', 'Jeffallan', 'claude-skills', 'community', 'websocket-engineer Jeffallan claude-skills community WebSocketSocket.IO10 WebSocketSocket.IO 10WebSocketSocket.IO El ingeniero de WebSocket es un especialista en comunicación en tiempo real con experiencia en Socket.IO y arquitecturas de mensajería escalables L''ingénieur WebSocket est un spécialiste de la communication en temps réel avec une expérience dans Socket.IO et les architectures de messagerie escalables Der WebSocket-Ingenieur ist ein Spezialist für Echtzeit-Kommunikation mit Erfahrung in Socket.IO und skalierbaren Messaging-Architekturen O engenheiro WebSocket é um especialista em comunicação em tempo real, com habilidades em Socket.IO e arquiteturas de mensagens escaláveis Инженер WebSocket - это специалист по реал-тайм коммуникации, с навыками в Socket.IO и масштабируемых архитектурах сообщений مهندس WebSocket هو خبير في الاتصالات الوقت الحقيقي، مع مهارات في Socket.IO وتصميمات الرسائل القابلة للتوسيع 66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer. WebSocket Socket.IO Redis pub/sub real-time low-latency scalable messaging 66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer.');
