INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HoangNguyen0403/agent-skills-standard/Testing', 'Testing', 'HoangNguyen0403', 'agent-skills-standard', 'community', 'Testing HoangNguyen0403 agent-skills-standard community 测试自动化标准是一套帮助开发者遵循最佳实践的指南，涵盖测试驱动开发、测试框架和工具等 テスト自動化基準は、開発者がベストプラクティスに従うためのガイドラインで、テスト駆動開発、テストフレームワーク、ツールなどを網羅 테스팅 표준은 개발자가 최선의 관행을 따르도록 도와주는 가이드로, 테스트 주도 개발, 테스트 프레임워크, 툴 등이 포함 Nuestra guía de pruebas en Golang cubre los estándares y mejores prácticas para el testing de código Notre guide de test en Golang couvre les normes et les meilleures pratiques pour le testing de code Unsere Anleitung zu Golang-Tests deckt die Standards und Best Practices für Code-Testing ab Este artigo apresenta os padrões e melhores práticas de teste em Golang, com foco em TDD e ferramentas como Testify e Mockery. Эта статья представляет стандарты и лучшие практики тестирования на Golang, с фокусом на TDD и инструментах như Testify и Mockery. يقدم هذا المقال معايير وافضل الممارسات للاختبار في جolang، مع التركيز على TDD وأدوات مثل Testify و Mockery. A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages 测试自动化 TDD 表驱动测试 测试框架 代码重构 自动化测试 开发最佳实践 A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HoangNguyen0403/agent-skills-standard/Performance', 'community', 'HoangNguyen0403', 'agent-skills-standard', 'HoangNguyen0403/agent-skills-standard', 'Performance', 0, 0, 55, '2026-02-20T04:13:19.578Z', '2026-02-20T04:53:53.224Z', '430b6d4b302f7276424b89ed0b11a8b59e9fb9c672db17b69b40a700266a1775', '{"id":"HoangNguyen0403/agent-skills-standard/Performance","name":"Performance","description":{"zh":"性能优化技能是一系列帮助AI Agent遵循编程语言和框架最佳实践的标准和指南","ja":"パフォーマンス最適化スキルは、AIエージェントがプログラミング言語とフレームワークのベストプラクティスに従うための標準とガイドラインのコレクションです","ko":"성능 최적화 스킬은 AI 에이전트가 프로그래밍 언어와 프레임워크의 베스트 프랙티스에 따라 동작하도록 도와주는 표준 및 가이드라인의 모음입니다","es":"Mejora el rendimiento de tus aplicaciones con nuestras mejores prácticas y estándares para programación y frameworks","fr":"Améliorez les performances de vos applications avec nos meilleures pratiques et normes pour la programmation et les frameworks","de":"Verbessern Sie die Leistung Ihrer Anwendungen mit unseren Best Practices und Standards für Programmierung und Frameworks","pt":"Otimização de desempenho em Angular com ChangeDetectionStrategy.OnPush, deferrable views e imagens otimizadas","ru":"Оптимизация производительности в Angular с помощью ChangeDetectionStrategy.OnPush, отложенных представлений и оптимизированных изображений","ar":"تحسين الأداء في Angular باستخدام ChangeDetectionStrategy.OnPush وتصورات مؤجلة وصور مُختزنة","en":"A collection of Agent Skills Standard and Best Practice for Programming Languages, Frameworks that help our AI Agent follow best practies on frameworks and programming laguages"},"seo":{"title":{"zh":"性能优化技能","ja":"パフォーマンス最適化スキル","ko":"성능 최적화 스킬","es":"Optimización de Rendimiento para Desarrolladores","fr":"Performances pour les Développeurs","de":"Leistungsoptimierung für Entwickler","pt":"Otimização de Desempenho em Angular","ru":"Оптимизация Производительности в Angu