INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/iam', 'iam', 'majiayu000', 'claude-skill-registry', 'community', 'iam majiayu000 claude-skill-registry community AWS IAM 是一种安全访问控制服务，提供对 AWS 资源的身份验证和授权 AWS IAM は、AWS リソースへのセキュアなアクセス制御を提供するサービス AWS IAM은 AWS 리소스에 대한 보안 액세스 제어를 제공하는 서비스 AWS IAM es un servicio que permite controlar el acceso a los recursos y servicios de AWS. Ofrece una gestión segura de los accesos y la autenticación AWS IAM est un service qui permet de contrôler l''accès aux ressources et services AWS. Il offre une gestion sécurisée des accès et de l''authentification AWS IAM ist ein Dienst, der die Kontrolle des Zugriffs auf AWS-Ressourcen und -Dienste ermöglicht. Er bietet eine sichere Verwaltung der Zugriffe und der Authentifizierung O AWS IAM é um serviço que permite o controle de acesso seguro aos serviços e recursos da AWS. Ele é fundamental para a segurança da AWS AWS IAM — это сервис, который обеспечивает безопасный контроль доступа к сервисам и ресурсам AWS. Он является фундаментальным для безопасности AWS إدارة الهوية والوصول إلى خدمات الأمازون هو خدمة تتيح التحكم الآمن في الوصول إلى خدمات و موارد الأمازون. وهي أساسية لأمن الأمازون The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app AWS IAM 身份和访问管理 安全访问控制 AWS 安全 IAM 角色 权限管理 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/psi', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'psi', 0, 0, 55, '2026-02-20T04:13:19.578Z', '2026-02-20T04:58:27.814Z', 'b9e814607af13fc53b0c340de10be60ca2249b5482529d3ed30bbc3a7086b4ca', '{"id":"majiayu000/claude-skill-registry/psi","name":"psi","description":{"zh":"PSI是一种结构化的工作流，用于计划、规范和实施变更，采用文档优先的方法","ja":"PSIは、計画、仕様、実装の変更に文書優先のアプローチを使用する構造化されたワークフローです","ko":"PSI는 계획, 사양, 구현의 변경에 문서 우선 접근 방식을 사용하는 구조화된 워크플로입니다","es":"PSI es un flujo de trabajo estructurado para planificar, especificar e implementar cambios con un enfoque de documentación primero","fr":"PSI est un workflow structuré pour planifier, spécifier et mettre en œuvre des modifications avec une approche de documentation première","de":"PSI ist ein strukturierter Workflow zum Planen, Spezifizieren und Implementieren von Änderungen mit einem dokumentationsbasierten Ansatz","pt":"O PSI é um fluxo de trabalho estruturado para planejar, especificar e implementar mudanças com documentação em primeiro lugar, garantindo uma abordagem consistente e eficaz","ru":"PSI - это структурированный рабочий процесс для планирования, спецификации и реализации изменений с документацией в первую очередь, обеспечивающий последовательный и эффективный подход","ar":"PSI هو تدفق عمل منظم لتخطيط وتصميم وتنفيذ التغييرات بأولوية للتوثيق، مما يضمن نهجًا متسقًا وفعالًا","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"PSI技能：计划、规范和实施的结构化工作流","ja":"PSIスキル：計画、仕様、実装の構造化されたワークフロー","ko":"PSI 스킬: 계획, 사양, 구현을 위한 구조화된 워크플로","es":"PSI: Flujo de trabajo estructurado para cambios","fr":"PSI : Workflow structuré pour les modifications","de":"PSI: Strukturierter Workflow für Änderungen","pt":"PSI: Fluxo de Trabalho Estruturado para Desenvolvedores","ru":"PSI: Структурированный рабочий процесс для разработчиков","ar":"PSI: تدفق العمل المنظم لل مطورين","en":"psi"},"description":{"zh":"PSI是一种结构化的工作流，用于计划、规范和实施变更，采用文档优先的方法","ja":"PSIは、計画、仕様、実装の変更に文書優先のアプローチを使用する構造化されたワークフローです","ko":"PSI는 계획, 사양, 구현의 변경에 문서 우선 접근 방식을 사용하는 구조화된 워크플로입니다","es":"PSI es un flujo de trabajo estructurado para planificar, especificar e implementar cambios con un enfoque de documentación primero","fr":"PSI est un workflow structuré pour planifier, spécifier et mettre en œuvre des modifications avec une approche de documentation première","de":"PSI ist ein strukturierter Workflow zum Planen, Spezifizieren und Implementieren von Änderungen mit einem dokumentationsbasierten Ansatz","pt":"O PSI é um fluxo de trabalho estruturado para planejar, especificar e implementar mudanças com documentação em primeiro lugar, garantindo uma abordagem consi...","ru":"PSI - это структурированный рабочий процесс для планирования, спецификации и реализации изменений с документацией в первую очередь, обеспечивающий последоват...","ar":"PSI هو تدفق عمل منظم لتخطيط وتصميم وتنفيذ التغييرات بأولوية للتوثيق، مما يضمن نهجًا متسقًا وفعالًا","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["计划、规范和实施的独立阶段","文档优先的方法","核心原则包括计划、规范和实施","可选的工作流，不是默认设置"],"ja":["計画、仕様、実装の独立した段階","文書優先のアプローチ","核心原則には計画、仕様、実装が含まれる","オプトインのワークフロー、デフォルトではありません"],"ko":["계획, 사양, 구현의 독립적인 단계","문서 우선 접근 방식","핵심 원칙에는 계획, 사양, 구현이 포함됨","선택적인 워크플로, 기본 설정이 아님"],"es":["Flujo de trabajo estructurado","Enfoque de documentación primero","Planificación, especificación e implementación de cambios","Independencia de fases","Actualización de documentación en tiempo real"],"fr":["Workflow structuré","Approche de documentation première","Planification, spécification et mise en œuvre de modifications","Indépendance des phases","Mise à jour de la documentation en temps réel"],"de":["Strukturierter Workflow","Dokumentationsbasierter Ansatz","Planen, Spezifizieren und Implementieren von Änderungen","Unabhängigkeit der Phasen","Echtzeit-Aktualisierung der Dokumentation"],"pt":["Fluxo de trabalho estruturado","Abordagem de documentação em primeiro lugar","Fases independentes","Garantia de documentação atualizada","Opt-in workflow"],"ru":["Структурированный рабочий процесс","Документация в первую очередь","Независимые фазы","Гарантия актуальной документации","Опт-ин рабочий процесс"],"ar":["تدفق عمل منظم","أولوية للتوثيق","مراحل مستقلة","ضمان توثيق محدث","تدفق عمل اختياري"]},"keywords":{"zh":["PSI技能","结构化工作流","计划规范实施","文档优先","开发效率","核心原则"],"ja":["PSIスキル","構造化されたワークフロー","計画仕様実装","文書優先","開発の効率","核心原則"],"ko":["PSI 스킬","구조화된 워크플로","계획 사양 구현","문서 우선","개발 효율성","핵심 원칙"],"es":["PSI","flujo de trabajo estructurado","documentación primero","planificación de cambios","especificación de cambios","implementación de cambios","desarrollo de software","ingeniería de software"],"fr":["PSI","workflow structuré","documentation première","planification de modifications","spécification de modifications","mise en œuvre de modifications","développement de logiciels","ingénierie de logiciels"],"de":["PSI","strukturierter Workflow","dokumentationsbasierter Ansatz","Planung von Änderungen","Spezifizierung von Änderungen","Implementierung von Änderungen","Softwareentwicklung","Softwareingenieurwesen"],"pt":["PSI","fluxo de trabalho","desenvolvimento de software","documentação","planejamento","especificação","implementação"],"ru":["PSI","структурированный рабочий процесс","разработка программного обеспечения","документация","планирование","спецификация","реализация"],"ar":["PSI","تدفق العمل","تطوير البرمجيات","التوثيق","التخطيط","التصميم","التنفيذ"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"psi","description":"Plan-spec-implement workflow for structured development. Only use when explicitly directed by user or when mentioned in project AGENTS.md file. Generates ephemeral plans in ~/.dot-agent/, applies specs to project docs, then implements test-first.","bodyPreview":"# PSI - Plan Spec Implement\n\nStructured workflow for planning, specifying, and implementing changes with documentation-first approach.\n\n## When to Use\n\n**Only use when:**\n- Explicitly directed by the user\n- Mentioned in project `AGENTS.md` file\n\n**Do not use automatically** - this is an opt-in workflow, not a default.\n\n## Core Workflow\n\n**Plan → Spec → Implement**\n\nPhases are **independent** - you can start with any phase, but all must ensure documentation stays up-to-date.\n\n## Key Principles\n\n1","body":"# PSI - Plan Spec Implement\n\nStructured workflow for planning, specifying, and implementing changes with documentation-first approach.\n\n## When to Use\n\n**Only use when:**\n- Explicitly directed by the user\n- Mentioned in project `AGENTS.md` file\n\n**Do not use automatically** - this is an opt-in workflow, not a default.\n\n## Core Workflow\n\n**Plan → Spec → Implement**\n\nPhases are **independent** - you can start with any phase, but all must ensure documentation stays up-to-date.\n\n## Key Principles\n\n1. **Ephemeral planning** - Plans stored in `~/.dot-agent/` (not committed)\n2. **Documentation-first** - Specs applied to project docs/READMEs/AGENTS.md\n3. **Test-first implementation** - Tests for docs/user journeys before code\n4. **Design/review embedded** - Design and review integrated into Plan/Spec phases\n5. **Phase independence** - Each phase can work standalone, all update docs\n\n## Phase Overview\n\n### Plan Phase\n- Generates detailed plans in `~/.dot-agent/repo/YYYY-MM-work-name.plan.md`\n- Research stored in `~/.dot-agent/working-dir/repo/YYYY-MM-work-name.research.md`\n- Embeds design considerations\n- Includes review before proceeding\n\n### Spec Phase\n- Generates specs for: API schemas, interfaces, DTOs, database models, config, env vars, architecture, user journeys, package structure, tech choices\n- Embeds design considerations\n- Reviews specs before applying\n- Applies to: `docs/`, README.md files, AGENTS.md files\n\n### Implement Phase\n- Test-first: tests for docs/user journeys before code\n- CI verification: verify types, tests, lint pass before committing\n- Atomic commits: group related changes with tests\n- Updates docs, README.md, AGENTS.md as code evolves\n- Can work independently if specs exist in docs\n\n## Research Management\n\nDetects phrases like:\n- \"looking at your research\" → Loads research file\n- \"refine your research\" → Updates research file, narrows focus\n\n## Documentation Structure\n\n- **README.md**: Aim for < 1000 lines (not hard rule), can be longer if needed\n- **AGENTS.md**: < 200 lines, inline at root/packages/modules/code level\n- **docs/**: Architecture, roadmap, tech-choices, setup/, user-journeys/, design/\n\n## References\n\nFor detailed protocols, see:\n- `references/plan-phase.md` - Plan generation with embedded design/review\n- `references/spec-phase.md` - Spec generation and application\n- `references/implement-phase.md` - Test-first implementation\n- `references/review-protocol.md` - Reviewing plans/specs/design\n- `references/research-management.md` - Research file handling\n- `references/docs-structure.md` - Documentation organization rules\n- `references/file-paths.md` - Storage paths and conventions\n"},"lastSynced":"2026-02-20T04:58:27.814Z","agentAnalysis":{"suitability":{"en":"Ideal for Methodical Agents requiring a structured workflow for planning, specifying, and implementing changes with a documentation-first approach.","zh":"适合需要结构化工作流程的方法论代理，用于规划、指定和实现更改，并采用文档优先的方法。","ja":"計画、仕様の作成、変更の実施を文書化した上で実行するための構造化されたワークフローを必要とするメソッド論的エージェントに最適です。","ko":"계획, 세부 사항 지정, 변경 사항 구현을 구조화된 워크플로우를 통해 문서화하여 처리하는 메소드 에이전트에게 적합합니다.","es":"Ideal para agentes metódicos que requieren un flujo de trabajo estructurado para planificar, especificar e implementar cambios con un enfoque de documentación primero.","fr":"Idéal pour les agents méthodiques nécessitant un workflow structuré pour planifier, spécifier et mettre en œuvre des changements avec une approche de documentation première.","de":"Ideal für methodische Agenten, die ein strukturiertes Workflow für Planung, Spezifikation und Implementierung von Änderungen mit einem dokumentationsbasierten Ansatz benötigen.","pt":"Ideal para Agentes Metódicos que requerem um fluxo de trabalho estruturado para planejamento, especificação e implementação de alterações com uma abordagem de documentação em primeiro lugar.","ru":"Идеально для Методических Агентов, требующих структурированного рабочего процесса для планирования, спецификации и реализации изменений с подходом документации в первую очередь.","ar":"مثالي لعميل Phương phápية يتطلب تدفق عمل منظم للتخطيط والتحديد والتنفيذ للتغييرات مع نهج وثائق أولاً."},"recommendation":{"en":"Empowers agents to follow a documentation-first approach, ensuring that all phases of the workflow, from planning to implementation, maintain up-to-date documentation using a structured Plan Spec Implement (PSI) methodology, incorporating protocols such as explicit user direction and project file specifications like AGENTS.md.","zh":"赋予代理采用文档优先的方法，确保工作流程的所有阶段，从规划到实施，都保持最新的文档，使用结构化的计划、规范、实施（PSI）方法论，融入诸如明确的用户指引和项目文件规范（如 AGENTS.md）等协议。","ja":"エージェントに文書優先アプローチを採用する権限を与え、計画から実装までのワークフローのすべての段階で最新のドキュメントを維持することを保証する。構造化された計画・仕様・実装（PSI）メソッド論を使用し、明示的なユーザー指示やプロジェクトファイル仕様（例：AGENTS.md）などのプロトコルを組み込む。","ko":"에이전트가 문서 우선 접근 방식을 따르도록 허용하여, 계획에서 구현까지 워크플로의 모든 단계에서最新의 문서를 유지하도록 보장합니다. 구조화된 계획-세부사항-구현(PSI) 방법론을 사용하며, 명확한 사용자 지침 및 프로젝트 파일 사양(예: AGENTS.md)과 같은 프로토콜을 포함합니다.","es":"Permite a los agentes seguir un enfoque de documentación primero, asegurando que todas las fases del flujo de trabajo, desde la planificación hasta la implementación, mantengan una documentación actualizada utilizando una metodología estructurada Plan Spec Implement (PSI), que incorpora protocolos como direcciones de usuario explícitas y especificaciones de archivos de proyecto como AGENTS.md.","fr":"Permet aux agents de suivre une approche de documentation première, en garantissant que toutes les phases du workflow, de la planification à la mise en œuvre, maintiennent une documentation à jour en utilisant une méthodologie structurée Plan Spec Implement (PSI), qui intègre des protocoles tels que des instructions utilisateur explicites et des spécifications de fichiers de projet comme AGENTS.md.","de":"Ermächtigt Agenten, einem dokumentationsbasierten Ansatz zu folgen, um sicherzustellen, dass alle Phasen des Workflows, von der Planung bis zur Implementierung, eine aktuelle Dokumentation mithilfe einer strukturierten Plan Spec Implement (PSI)-Methodik beibehalten, die Protokolle wie explizite Benutzeranweisungen und Projektdateispezifikationen wie AGENTS.md einbezieht.","pt":"Habilita os agentes a seguir uma abordagem de documentação em primeiro lugar, garantindo que todas as fases do fluxo de trabalho, desde o planejamento até a implementação, mantenham documentação atualizada usando uma metodologia estruturada de Plano Especificação Implementação (PSI), incorporando protocolos como direção explícita do usuário e especificações de arquivo de projeto como AGENTS.md.","ru":"Наделяет агентов возможностью следовать подходу документации в первую очередь, гарантируя, что все фазы рабочего процесса, от планирования до реализации, поддерживают актуальную документацию с использованием структурированной методологии План Спецификация Реализация (PSI), включающей протоколы, такие как явное руководство пользователя и спецификации файла проекта, такие как AGENTS.md.","ar":"تمكن الوكيل من اتباع نهج الوثائق أولاً، مما يضمن أن جميع مراحل تدفق العمل، من التخطيط إلى التنفيذ، تحتفظ بالوثائق محدثة باستخدام منهجية مخطط تفاصيل تنفيذ (PSI) منظم، ودمج بروتوكولات مثل توجيه المستخدم الصريح ومواصفات ملف المشروع مثل AGENTS.md."},"useCases":{"en":["Implementing changes with thorough documentation","Specifying project requirements with clarity","Planning workflows with a structured approach"],"zh":["实施变更并记录详细文档","使用清晰的方式指定项目需求","采用结构化方法规划工作流程"],"ja":["変更を実施し、詳細なドキュメントを作成する","プロジェクトの要件を明確に指定する","構造化された方法でワークフローを計画する"],"ko":["변경 사항을 구현하고 자세한 문서를 기록하는 것","프로젝트 요구 사항을 명확하게 지정하는 것","구조화된 방법으로 워크플로우를 계획하는 것"],"es":["Implementar cambios con una documentación exhaustiva","Especificar los requisitos del proyecto con claridad","Planificar flujos de trabajo con un enfoque estructurado"],"fr":["Mettre en œuvre des changements avec une documentation exhaustive","Spécifier les exigences du projet avec clarté","Planifier des flux de travail avec une approche structurée"],"de":["Änderungen mit umfassender Dokumentation implementieren","Projektanforderungen mit Klarheit spezifizieren","Workflows mit einem strukturierten Ansatz planen"],"pt":["Implementação de alterações com documentação aprofundada","Especificação de requisitos de projeto com clareza","Planejamento de fluxos de trabalho com uma abordagem estruturada"],"ru":["Реализация изменений с тщательной документацией","Спецификация требований проекта с ясностью","Планирование рабочих процессов с структурированным подходом"],"ar":["تنفيذ التغييرات مع وثائق متعمقة","تحديد متطلبات المشروع بوضوح","تخطيط تدفقات العمل بطريقة منضبطة"]},"limitations":{"en":["Requires explicit user direction","Mention in project AGENTS.md file necessary","Do not use automatically, opt-in workflow only"],"zh":["需要明确的用户指引","需要在项目 AGENTS.md 文件中提及","不能自动使用，仅支持选择加入的工作流程"],"ja":["明示的なユーザー指示が必要","プロジェクトのAGENTS.mdファイルに記載する必要がある","自動では使用できず、オプトインワークフローのみ"],"ko":["명확한 사용자 지침이 필요합니다.","프로젝트의 AGENTS.md 파일에 언급해야 합니다.","자동으로 사용할 수 없으며, 선택加入 워크플로우만 지원합니다."],"es":["Requiere una dirección de usuario explícita","Mención en el archivo de proyecto AGENTS.md necesaria","No usar de forma automática, flujo de trabajo de opt-in solo"],"fr":["Nécessite une direction utilisateur explicite","Mention dans le fichier de projet AGENTS.md nécessaire","Ne pas utiliser de manière automatique, workflow de opt-in uniquement"],"de":["Benötigt eine explizite Benutzeranweisung","Erwähnung in der Projektdatei AGENTS.md erforderlich","Nicht automatisch verwenden, nur opt-in-Workflow"],"pt":["Requer direção explícita do usuário","Menção no arquivo de projeto AGENTS.md é necessária","Não use automaticamente, fluxo de trabalho opt-in apenas"],"ru":["Требует явного руководства пользователя","Упоминание в файле проекта AGENTS.md необходимо","Не используйте автоматически, только рабочий процесс opt-in"],"ar":["يتطلب توجيه المستخدم الصريح","الاشارة في ملف المشروع AGENTS.md ضرورية","لا تستخدم تلقائيًا، تدفق عمل خيار فقط"]},"version":3},"contentHash":"b9e814607af13fc53b0c340de10be60ca2249b5482529d3ed30bbc3a7086b4ca","qualityScore":55}');
