INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/psi', 'psi', 'majiayu000', 'claude-skill-registry', 'community', 'psi majiayu000 claude-skill-registry community PSI是一种结构化的工作流，用于计划、规范和实施变更，采用文档优先的方法 PSIは、計画、仕様、実装の変更に文書優先のアプローチを使用する構造化されたワークフローです PSI는 계획, 사양, 구현의 변경에 문서 우선 접근 방식을 사용하는 구조화된 워크플로입니다 PSI es un flujo de trabajo estructurado para planificar, especificar e implementar cambios con un enfoque de documentación primero PSI est un workflow structuré pour planifier, spécifier et mettre en œuvre des modifications avec une approche de documentation première PSI ist ein strukturierter Workflow zum Planen, Spezifizieren und Implementieren von Änderungen mit einem dokumentationsbasierten Ansatz O PSI é um fluxo de trabalho estruturado para planejar, especificar e implementar mudanças com documentação em primeiro lugar, garantindo uma abordagem consistente e eficaz PSI - это структурированный рабочий процесс для планирования, спецификации и реализации изменений с документацией в первую очередь, обеспечивающий последовательный и эффективный подход PSI هو تدفق عمل منظم لتخطيط وتصميم وتنفيذ التغييرات بأولوية للتوثيق، مما يضمن نهجًا متسقًا وفعالًا The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app PSI技能 结构化工作流 计划规范实施 文档优先 开发效率 核心原则 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
