INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiskillstore/marketplace/react-email', 'react-email', 'aiskillstore', 'marketplace', 'community', 'react-email aiskillstore marketplace community React Email React React React Email es una herramienta que permite a los desarrolladores crear correos electrónicos personalizados con componentes de React, facilitando la creación de emails modernos y compatibles con todos los clientes de correo electrónico React Email est un outil qui permet aux développeurs de créer des emails personnalisés avec des composants React, facilitant la création d''emails modernes et compatibles avec tous les clients de messagerie React Email ist ein Tool, das es Entwicklern ermöglicht, benutzerdefinierte E-Mails mit React-Komponenten zu erstellen, wodurch die Erstellung moderner und mit allen E-Mail-Clients kompatibler E-Mails erleichtert wird O React Email é uma abordagem moderna para o desenvolvimento de e-mails, permitindo a criação de e-mails HTML personalizados com componentes React. React Email — это современный подход к разработке электронной почты, позволяющий создавать настраиваемые HTML-письма с использованием компонентов React. رياكت إيميل هو نهج حديث لإنشاء رسائل البريد الإلكتروني، مما يسمح بإنشاء رسائل بريد إلكتروني إتش تي إم إل مخصصة باستخدام مكونات رياكت. Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified. React Email React HTML create-email CLI npm yarn React Email React Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified.');
