INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/project-workflow', 'project-workflow', 'majiayu000', 'claude-skill-registry', 'community', 'project-workflow majiayu000 claude-skill-registry community project-workflow技能提供了9个集成的斜杠命令，实现项目生命周期的自动化，包括想法验证、规划、执行、会议管理、上下文保存和发布 project-workflowスキルには、プロジェクトライフサイクルを自動化する9つの統合スラッシュコマンドが含まれています。アイデアの検証、計画、実行、セッション管理、コンテキストの保存、リリースなどが含まれます project-workflow 스킬에는 프로젝트 라이프사이클을 자동화하는 9개의 통합 슬래시 명령어가 포함되어 있습니다. 아이디어 검증, 계획, 실행, 세션 관리, 컨텍스트 저장, 릴리즈 등이 포함됩니다 El Skill de Flujo de Proyecto automatiza el ciclo de vida completo del proyecto, desde la validación de ideas hasta la lanzamiento Le Skill de Flux de Projet automatise le cycle de vie complet du projet, de la validation des idées à la mise en production Das Projekt-Workflow-Skill automatisiert den gesamten Projekt-Lebenszyklus, von der Ideenvalidierung bis zum Release A habilidade de fluxo de projeto automatiza o ciclo de vida do projeto, desde a validação da ideia até a liberação. Возможность рабочего процесса проекта автоматизирует цикл жизни проекта, от проверки идеи до выпуска. مهارة Fluxo دي المشروع تؤتمتيك دورة حياة المشروع، من التحقق من الفكرة إلى الإصدار. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app 项目工作流程自动化 project-workflow技能 斜杠命令 项目生命周期 自动化工具 开发效率 节省时间 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
