INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/ai-first-engineering', 'ai-first-engineering', 'affaan-m', 'everything-claude-code', 'official', 'ai-first-engineering affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity This skill provides an engineering operating model for development teams leveraging AI agents like Anthropic''s Claude for code generation. It outlines critical process shifts and architectural requirements for teams where AI produces a large share of implementation output. AI-First工程是指工程操作模型为团队提供AI代理生成大量实现输出，需要过程转变和架构调整 AIエージェントが大量の実装出力を生成するチームのエンジニアリングオペレーティングモデルを設計するためのガイド AI-First 엔지니어링은 AI 에이전트가大量의 구현 출력을 생성하는 팀을 위한 엔지니어링 운영 모델입니다 Un modelo operativo para equipos donde los agentes de IA generan una gran parte del código. Cambia los procesos de planificación, revisión y arquitectura para ser efectivo con generación de código asistida por IA como Claude Code. Un modèle opérationnel pour les équipes où les agents IA génèrent une grande partie du code. Modifie les processus de planification, revue et architecture pour être efficace avec la génération de code assistée par IA comme Claude Code. Ein Betriebsmodell für Teams, in denen KI-Agenten einen Großteil des Codes generieren. Verändert Planungs-, Review- und Architekturprozesse für effektive KI-gestützte Codegenerierung mit Tools wie Claude Code. Um modelo operacional para equipes onde agentes de IA geram uma grande parte do código. Exige mudanças no processo de revisão e arquitetura para sistemas agent-friendly. Операционная модель для команд, в которых ИИ агенты генерируют значительную часть кода. Требует изменений в процессе ревью и архитектуре для создания agent-friendly систем. نموذج تشغيلي للفرق حيث تقوم أدوات الذكاء الاصطناعي بتوليد حصة كبيرة من código. يتطلب تحولًا في عملية المراجعة وهندسة الأنظمة الصديقة لأدوات الذكاء الاصطناعي. what is ai-first-engineering how to use ai-first-engineering with claude ai-first-engineering vs traditional development ai-first-engineering operating model ai-first-engineering install ai-first-engineering setup guide ai agent architecture explicit boundaries claude code deterministic tests mcp server ai-first-engineering AI-First工程 AI代理 代码生成 过程转变 架构要求 评估覆盖 审查焦点 AI工具 开发工具 Process design for teams using AI-assisted code generation Review focus shift from syntax checking to system behavior analysis Architectural guidance for agent-friendly systems with explicit boundaries Promotion of stable contracts and typed interfaces for deterministic output Emphasis on evaluation coverage over anecdotal confidence Guidance to avoid implicit architectures for improved AI agent performance ai-first-engineering is an operating model for development teams where AI agents generate a significant portion of code implementation. It focuses on process design, review methodologies, and architecture requirements specifically optimized for AI-assisted development workflows with tools like Claude Code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vinta/hal-9000/sync-skills', 'community', 'vinta', 'hal-9000', 'vinta/hal-9000', 'sync-skills', 107, 20, 54, '2026-02-26T06:26:21Z', '2026-03-06T06:30:32.467Z', 'de35947cfe0a4fa226bdf2531948c1d196c52002c484381cea16559c1eb5314c', '{"id":"vinta/hal-9000/sync-skills","name":"sync-skills","description":{"en":"sync-skills automates macOS development environment setup using Ansible playbooks and supports technologies like NodeJS, Python, and Solidity. It benefits developers by simplifying environment configuration.","zh":"sync-skills是一个macOS开发环境自动化工具，支持Ansible Playbooks、Docker和Kubernetes","ja":"sync-skillsはmacOS開発環境自動化ツールで、Ansible Playbooks、Docker、Kubernetesをサポート","ko":"sync-skills는 macOS 개발 환경 자동화 도구로 Ansible Playbooks, Docker 및 Kubernetes를 지원합니다.","es":"sync-skills es una herramienta de automatización de entornos de desarrollo macOS que utiliza Ansible y otros tecnologías para mejorar la eficiencia","fr":"sync-skills est un outil d''automatisation d''environnements de développement macOS qui utilise Ansible et d''autres technologies pour améliorer l''efficacité","de":"sync-skills ist ein Tool zur Automatisierung von macOS-Entwicklungsumgebungen, das Ansible und andere Technologien nutzt, um die Effizienz zu verbessern","pt":"O sync-skills é uma ferramenta de automação de ambientes de desenvolvimento macOS que utiliza Ansible e Docker para simplificar o processo de configuração","ru":"Sync-skills - это инструмент для автоматизации среды разработки macOS, использующий Ansible и Docker для упрощения процесса настройки","ar":"sync-skills هو أداة لأتمتة بيئات التطوير على macOS التي تستخدم Ansible و Docker لتسهيل عملية الإعداد"},"seo":{"title":{"en":"sync-skills: Automated macOS Dev Environment Setup | AI A...","zh":"sync-skills Setup Guide: macOS开发环境自动化","ja":"sync-skills セットアップガイド: macOS開発環境自動化","ko":"sync-skills 설정 가이드: macOS 개발 환경 자동화","es":"Guía de configuración de sync-skills para macOS","fr":"Guide d''installation de sync-skills pour le développement...","de":"Einrichtungsleitfaden für sync-skills unter macOS","pt":"Guia de Configuração do sync-skills para Ambientes de Des...","ru":"Настройка ИИ Агентов: sync-skills для macOS Разработки","ar":"دليل إعداد sync-skills لأتمتة بيئات التطوير على macOS"},"description":{"en":"Discover how sync-skills streamlines macOS development with automated environment setup - explore features and setup guide now","zh":"使用sync-skills实现macOS开发环境自动化，支持Ansible Playbooks、Docker和Kubernetes","ja":"sync-skillsを使用してmacOS開発環境を自動化する、Ansible Playbooks、Docker、Kubernetesをサポート","ko":"sync-skills를 사용하여 macOS 개발 환경을 자동화합니다. Ansible Playbooks, Docker 및 Kubernetes를 지원합니다.","es":"Automatice su entorno de desarrollo macOS con sync-skills y mejore su productividad","fr":"Automatisez votre environnement de développement macOS avec sync-skills et améliorez votre productivité","de":"Automatisieren Sie Ihre macOS-Entwicklungsumgebung mit sync-skills und steigern Sie Ihre Produktivität","pt":"Aprenda a configurar o sync-skills para automatizar ambientes de desenvolvimento macOS com Ansible, Docker e Kubernetes","ru":"Исследуйте возможности ИИ Агентов: настройка sync-skills для автоматизации среды разработки macOS с Ansible, Docker и Kubernetes","ar":"اكتشف كيفية إعداد sync-skills لأتمتة بيئات التطوير على macOS باستخدام Ansible و Docker و Kubernetes"},"definition":{"en":"sync-skills is an opinionated macOS development environment automation tool using Ansible playbooks and supporting multiple programming languages","zh":"sync-skills是一种AI工具，用于自动化macOS开发环境配置","ja":"sync-skillsはAIエージェントの一種で、macOS開発環境設定を自動化する","ko":"sync-skills는 macOS 개발 환경 설정을 자동화하는 AI 도구입니다.","es":"sync-skills es una herramienta de automatización de entornos de desarrollo para macOS","fr":"sync-skills est un outil d''automatisation d''environnements de développement pour macOS","de":"sync-skills ist ein Tool zur Automatisierung von Entwicklungsumgebungen für macOS","pt":"O que é sync-skills? É uma ferramenta de automação de ambientes de desenvolvimento macOS","ru":"Что такое sync-skills? Это инструмент для автоматизации среды разработки macOS","ar":"ما هو sync-skills؟ هو أداة لأتمتة بيئات التطوير على macOS"},"features":{"en":["Glob skills using `skills/*/SKILL.md` in `/usr/local/hal-9000`","Extracts skill names from YAML frontmatter","Rewrites descriptions into short sentences","Updates `README.md` with formatted skill links","Supports Docker and Kubernetes for containerization","Utilizes NodeJS and Python for automation scripts"],"zh":["支持Ansible Playbooks自动化部署","集成Docker和Kubernetes容器化支持","自动化macOS开发环境配置","支持Node.js和Python开发环境","集成Solidity智能合约开发支持"],"ja":["Ansible Playbooks自動化デプロイをサポート","DockerとKubernetesのコンテナ化をサポート","macOS開発環境設定を自動化","Node.jsとPython開発環境をサポート","Solidityスマートコントラクト開発をサポート"],"ko":["Ansible Playbooks 자동화 배포 지원","Docker 및 Kubernetes 컨테이너화 지원","macOS 개발 환경 설정 자동화","Node.js 및 Python 개발 환경 지원","Solidity 스마트 계약 개발 지원"],"es":["Automatización de entornos de desarrollo con Ansible","Compatibilidad con tecnologías como Docker y Kubernetes","Soporte para lenguajes de programación como Node.js y Python","Integración con Claude Code y Solidity","Gestión de habilidades con SKILL.md"],"fr":["Automatisation d''environnements de développement avec Ansible","Compatibilité avec des technologies comme Docker et Kubernetes","Prise en charge de langages de programmation tels que Node.js et Python","Intégration avec Claude Code et Solidity","Gestion des compétences avec SKILL.md"],"de":["Automatisierung von Entwicklungsumgebungen mit Ansible","Kompatibilität mit Technologien wie Docker und Kubernetes","Unterstützung für Programmiersprachen wie Node.js und Python","Integration mit Claude Code und Solidity","Verwaltung von Fähigkeiten mit SKILL.md"],"pt":["Suporte a Ansible para automação de tarefas","Integração com Docker para contêineres","Compatibilidade com Kubernetes para orquestração de contêineres","Gestão de skills com YAML frontmatter","Atualização automática do arquivo README.md"],"ru":["Поддержка Ansible для автоматизации задач","Интеграция с Docker для контейнеров","Совместимость с Kubernetes для оркестровки контейнеров","Управление навыками с помощью YAML frontmatter","Автоматическое обновление файла README.md"],"ar":["دعم Ansible لأتمتة المهام","التكامل مع Docker لل-contêineres","التوافق مع Kubernetes لorchestration contêineres","إدارة المهارات باستخدام YAML frontmatter","تحديث автомático لملف README.md"]},"keywords":{"en":["how to use sync-skills","sync-skills setup guide","macOS development environment automation","Ansible playbooks for macOS","sync-skills vs Docker","sync-skills install on macOS","automating development environments with sync-skills","sync-skills alternative tools","sync-skills and Kubernetes integration"],"zh":["macOS开发环境自动化","Ansible Playbooks","Docker","Kubernetes","Node.js","Python","Solidity","AI工具","sync-skills"],"ja":["macOS開発環境自動化","Ansible Playbooks","Docker","Kubernetes","Node.js","Python","Solidity","AIエージェント","sync-skills"],"ko":["macOS 개발 환경 자동화","Ansible Playbooks","Docker","Kubernetes","Node.js","Python","Solidity","AI 도구","sync-skills"],"es":["herramientas de automatización de desarrollo","entornos de desarrollo macOS","Ansible para macOS","Docker para desarrollo","Kubernetes para desarrollo","Node.js para macOS","Python para macOS"," Claude Code","Solidity para desarrollo"],"fr":["outils d''automatisation de développement","environnements de développement macOS","Ansible pour macOS","Docker pour le développement","Kubernetes pour le développement","Node.js pour macOS","Python pour macOS","Claude Code","Solidity pour le développement"],"de":["Entwicklungsumgebungs-Automatisierungstools","macOS-Entwicklungsumgebungen","Ansible für macOS","Docker für die Entwicklung","Kubernetes für die Entwicklung","Node.js für macOS","Python für macOS","Claude Code","Solidity für die Entwicklung"],"pt":["sync-skills","ambiente de desenvolvimento macOS","automação de tarefas","Ansible","Docker","Kubernetes","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["sync-skills","среда разработки macOS","автоматизация задач","Ansible","Docker","Kubernetes","разработка программного обеспечения","инструменты разработки"],"ar":["sync-skills","بيئة التطوير على macOS","أتمتة المهام","Ansible","Docker","Kubernetes","تطوير البرمجيات","أدوات التطوير"]}},"owner":"vinta","repo":"hal-9000","repoPath":"vinta/hal-9000","stars":107,"forks":20,"updatedAt":"2026-02-26T06:26:21Z","topics":["ansible-playbooks","claude-code","development-environment","docker","kubernetes","macos","nodejs","python","solidity"],"category":"community","skillMd":{"name":"sync-skills","description":"(hal-9000) Use when a skill in skills/ has its name or description changed, or is added or removed — syncs README.md, settings.json, and hal_dotfiles.json","bodyPreview":"# Instructions\n\n**IMPORTANT**: Only use this skill in `/usr/local/hal-9000`. Otherwise, abort.\n\n1. **Discover skills**\n   - Glob `skills/*/SKILL.md` in `/usr/local/hal-9000` only\n   - Extract `name` from each YAML frontmatter\n   - Rewrite each `description` into one short sentence (~10 words max) saying what it does — no \"Use when\" triggers, no verbatim frontmatter copy\n\n2. **Update `README.md`** (the `### Agent Skills` section)\n   - Format: `- [name](skills/name): description`\n   - Use the rewr","body":"# Instructions\n\n**IMPORTANT**: Only use this skill in `/usr/local/hal-9000`. Otherwise, abort.\n\n1. **Discover skills**\n   - Glob `skills/*/SKILL.md` in `/usr/local/hal-9000` only\n   - Extract `name` from each YAML frontmatter\n   - Rewrite each `description` into one short sentence (~10 words max) saying what it does — no \"Use when\" triggers, no verbatim frontmatter copy\n\n2. **Update `README.md`** (the `### Agent Skills` section)\n   - Format: `- [name](skills/name): description`\n   - Use the rewritten description from step 1\n   - Add new skills, remove deleted skills, update changed descriptions\n   - Preserve existing entry order; append new entries at end\n\n3. **Update `dotfiles/.claude/settings.json`** (the `permissions.allow` array)\n   - Sync the `Skill(...)` entries to match discovered user-invocable skills\n   - Only include skills with `user-invocable: true` in frontmatter\n   - Format: `\"Skill(<name>)\"`\n   - Add new skills, remove entries whose skill no longer exists\n   - Preserve existing entry order; append new entries at end\n   - Keep the entries in the same position block (between other tool entries)\n\n4. **Update `dotfiles/hal_dotfiles.json`** (the `links` array)\n   - Format: `{\"dest\": \"{{HOME}}/.claude/skills/<name>/\", \"src\": \"{{REPO_ROOT}}/skills/<name>/\"}`\n   - Add new skill dirs, remove entries whose `\"src\"` matches `{{REPO_ROOT}}/skills/*` but no longer has a matching skill\n   - Preserve existing entry order; append new entries at end\n   - Leave non-skill entries and `copies` array as-is\n\n5. **Run `./bin/hal sync`**, then report what changed.\n"},"lastSynced":"2026-03-06T06:30:32.467Z","agentAnalysis":{"suitability":{"en":"Perfect for macOS Development Agents needing automated environment setup and configuration.","zh":"适合需要自动环境设置和配置的macOS开发代理。","ja":"macOS開発エージェントが自動環境設定と構成を必要とする場合に最適です。","ko":"자동 환경 설정 및 구성이 필요한 macOS 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo de macOS que necesitan una configuración y configuración de entorno automatizada.","fr":"Parfait pour les Agents de Développement macOS ayant besoin d''une configuration et de paramétrage d''environnement automatisés.","de":"Perfekt für macOS-Entwicklungsagenten, die eine automatisierte Umgebungssetup und -konfiguration benötigen.","pt":"Perfeito para agentes de desenvolvimento do macOS que precisam de configuração e instalação de ambiente automatizadas.","ru":"Идеально для агентов разработки macOS, которым необходима автоматизированная настройка и конфигурация среды.","ar":"مثالي لعمليات التطوير على نظام التشغيل macOS التي تحتاج إلى إعداد وتكوين بيئة آلي."},"recommendation":{"en":"Empowers agents to automate macOS development environment setup using Ansible playbooks, supporting technologies like NodeJS, Python, and Solidity, simplifying environment configuration and reducing manual effort.","zh":"使代理能够使用Ansible playbook自动设置macOS开发环境，支持NodeJS、Python和Solidity等技术，简化环境配置并减少手动努力。","ja":"Ansibleプレイブックを使用してmacOS開発環境を自動設定できるようにエージェントをEmpowerし、NodeJS、Python、Solidityなどの技術をサポートし、環境構成を簡素化し、手動労力を削減します。","ko":"에이전트가 Ansible playbook를 사용하여 macOS 개발 환경을 자동으로 설정할 수 있도록 하여 NodeJS, Python 및 Solidity와 같은 기술을 지원하고 환경 구성의 단순화 및 수동 노력의 감소를 가능하게 합니다.","es":"Permite a los agentes automatizar la configuración del entorno de desarrollo de macOS utilizando libros de reproducción de Ansible, que admiten tecnologías como NodeJS, Python y Solidity, simplificando la configuración del entorno y reduciendo el esfuerzo manual.","fr":"Permet aux agents d''automatiser la configuration de l''environnement de développement macOS en utilisant des livres de jeu Ansible, prenant en charge des technologies comme NodeJS, Python et Solidity, simplifiant ainsi la configuration de l''environnement et réduisant les efforts manuels.","de":"Ermöglicht es Agenten, die Einrichtung der macOS-Entwicklungsumgebung mithilfe von Ansible-Playbooks zu automatisieren, die Technologien wie NodeJS, Python und Solidity unterstützen, wodurch die UmgebungsKonfiguration vereinfacht und der manuelle Aufwand reduziert wird.","pt":"Habilita os agentes a automatizar a configuração do ambiente de desenvolvimento do macOS usando playbooks Ansible, suportando tecnologias como NodeJS, Python e Solidity, simplificando a configuração do ambiente e reduzindo o esforço manual.","ru":"Позволяет агентам автоматизировать настройку среды разработки macOS с помощью playbook Ansible, поддерживая технологии như NodeJS, Python и Solidity, упрощая конфигурацию среды и снижая ручные усилия.","ar":"تمكن الوكلاء من توفير إعداد بيئة التطوير على نظام التشغيل macOS آليًا باستخدام كتب لعب Ansible، مع دعم تكنولوجيا مثل NodeJS وPython وSolidity، مما يبسّط إعداد البيئة ويقلل من الجهد اليدوي."},"useCases":{"en":["Automating environment setup for NodeJS projects","Configuring Python development environments with Ansible","Streamlining Solidity development with automated setup"],"zh":["为NodeJS项目自动设置环境","使用Ansible配置Python开发环境","通过自动设置简化Solidity开发"],"ja":["NodeJSプロジェクトの環境を自動設定する","Ansibleを使用してPython開発環境を構成する","自動設定を使用してSolidity開発を簡素化する"],"ko":["NodeJS 프로젝트를 위한 자동 환경 설정","Ansible을 사용하여 Python 개발 환경 구성","자동 설정을 통한 Solidity 개발 단순화"],"es":["Automatización de la configuración del entorno para proyectos NodeJS","Configuración de entornos de desarrollo de Python con Ansible","Optimización del desarrollo de Solidity con una configuración automatizada"],"fr":["Automatisation de la configuration de l''environnement pour les projets NodeJS","Configuration des environnements de développement Python avec Ansible","Optimisation du développement de Solidity avec une configuration automatisée"],"de":["Automatisierung der Umgebungssetup für NodeJS-Projekte","Konfiguration von Python-Entwicklungsumgebungen mit Ansible","Optimierung der Solidity-Entwicklung durch automatisierte Einrichtung"],"pt":["Automatizar a configuração do ambiente para projetos NodeJS","Configurar ambientes de desenvolvimento Python com Ansible","Otimizar o desenvolvimento Solidity com configuração automatizada"],"ru":["Автоматизировать настройку среды для проектов NodeJS","Настроить среды разработки Python с помощью Ansible","Упростить разработку Solidity с помощью автоматизированной настройки"],"ar":["توفير إعداد بيئة آلي لمشاريع NodeJS","تكوين بيئات التطوير Python مع Ansible","تبسيط تطوير Solidity باستخدام الإعداد الآلي"]},"limitations":{"en":["Must be used in /usr/local/hal-9000 directory","Requires Ansible playbooks"],"zh":["必须在/usr/local/hal-9000目录中使用","需要Ansible playbook"],"ja":["/usr/local/hal-9000ディレクトリ内での