INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vinta/hal-9000/sync-skills', 'sync-skills', 'vinta', 'hal-9000', 'community', 'sync-skills vinta hal-9000 community ansible-playbooks claude-code development-environment docker kubernetes macos nodejs python solidity sync-skills automates macOS development environment setup using Ansible playbooks and supports technologies like NodeJS, Python, and Solidity. It benefits developers by simplifying environment configuration. sync-skills是一个macOS开发环境自动化工具，支持Ansible Playbooks、Docker和Kubernetes sync-skillsはmacOS開発環境自動化ツールで、Ansible Playbooks、Docker、Kubernetesをサポート sync-skills는 macOS 개발 환경 자동화 도구로 Ansible Playbooks, Docker 및 Kubernetes를 지원합니다. sync-skills es una herramienta de automatización de entornos de desarrollo macOS que utiliza Ansible y otros tecnologías para mejorar la eficiencia sync-skills est un outil d''automatisation d''environnements de développement macOS qui utilise Ansible et d''autres technologies pour améliorer l''efficacité sync-skills ist ein Tool zur Automatisierung von macOS-Entwicklungsumgebungen, das Ansible und andere Technologien nutzt, um die Effizienz zu verbessern O sync-skills é uma ferramenta de automação de ambientes de desenvolvimento macOS que utiliza Ansible e Docker para simplificar o processo de configuração Sync-skills - это инструмент для автоматизации среды разработки macOS, использующий Ansible и Docker для упрощения процесса настройки sync-skills هو أداة لأتمتة بيئات التطوير على macOS التي تستخدم Ansible و Docker لتسهيل عملية الإعداد how to use sync-skills sync-skills setup guide macOS development environment automation Ansible playbooks for macOS sync-skills vs Docker sync-skills install on macOS automating development environments with sync-skills sync-skills alternative tools sync-skills and Kubernetes integration macOS开发环境自动化 Ansible Playbooks Docker Kubernetes Node.js Python Solidity AI工具 sync-skills Glob skills using `skills/*/SKILL.md` in `/usr/local/hal-9000` Extracts skill names from YAML frontmatter Rewrites descriptions into short sentences Updates `README.md` with formatted skill links Supports Docker and Kubernetes for containerization Utilizes NodeJS and Python for automation scripts sync-skills is an opinionated macOS development environment automation tool using Ansible playbooks and supporting multiple programming languages');
