INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('IsKenKenYa/1Panel-Client/mobile-app-testing', 'mobile-app-testing', 'IsKenKenYa', '1Panel-Client', 'community', 'mobile-app-testing IsKenKenYa 1Panel-Client community 1panel android dart de-v-o-p-s devops devops-tools flutter flutter-app ios mobile-app openapi server-management unofficial-client The mobile-app-testing skill implements comprehensive testing strategies for mobile applications, benefiting developers who need to ensure reliable and high-performance apps. 移动应用测试是确保应用程序可靠性和性能的关键步骤。它包括单元测试、UI 测试、集成测试和性能测试 モバイルアプリテストは、信頼性とパフォーマンスのあるアプリケーションを開発する上で重要なステップです 모바일 앱 테스트는 안정적이고 성능이 좋은 애플리케이션을 개발하는 데 중요한 단계입니다 La prueba de aplicaciones móviles implica unit tests, UI tests, integration tests y pruebas de rendimiento con tecnologías como React Native y Detox Les tests d''applications mobiles impliquent des tests unitaires, des tests d''interface utilisateur, des tests d''intégration et des tests de performances avec des technologies comme React Native et Detox Mobile-App-Tests umfassen Unit-Tests, UI-Tests, Integrationstests und Leistungsprüfungen mit Technologien wie React Native und Detox Implemente estratégias de teste abrangentes para aplicativos móveis com testes unitários, UI e de desempenho Настройте тестирование мобильных приложений с помощью ИИ Агентов и технологий seperti Flutter и OpenAPI نفذ استراتيجيات اختبار شاملة للتطبيقات المحمولة باستخدام أدوات إدارة الخوادم وأدوات مثل Flutter و OpenAPI how to use mobile-app-testing mobile-app-testing setup guide what is mobile-app-testing mobile-app-testing alternative mobile-app-testing vs Appium mobile-app-testing install mobile-app-testing for Flutter mobile-app-testing for iOS and Android mobile-app-testing best practices 移动应用测试 React Native Detox 单元测试 UI 测试 集成测试 性能测试 OpenAPI 多服务器支持 Implements unit tests, UI tests, integration tests, and performance testing for mobile applications Supports automating UI testing across iOS and Android using Jest and Detox Enables performance testing and optimization for mobile apps Facilitates integration testing with backend services using OpenAPI Allows for regression testing before releases mobile-app-testing is a set of techniques for implementing unit tests, UI tests, integration tests, and performance testing for mobile applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('synapticore-io/marimo-flow/pina', 'community', 'synapticore-io', 'marimo-flow', 'synapticore-io/marimo-flow', 'pina', 10, 1, 54, '2026-02-26T21:07:40Z', '2026-03-06T06:46:38.764Z', '1b64ccef232eecc62dc8a2ab591aa189cf9a2558cdf44db614ba562319f7440b', '{"id":"synapticore-io/marimo-flow/pina","name":"pina","description":{"en":"pina is a PyTorch-based library for solving partial differential equations using neural networks, benefiting developers and researchers in scientific machine learning.","zh":"PINA 是一个用于解决偏微分方程的 PyTorch 库，结合 Physics-Informed Neural Networks 和神经操作符","ja":"PINA は、偏微分方程を解くための PyTorch ライブラリで、Physics-Informed Neural Networks とニューラルオペレータを組み合わせる","ko":"PINA는偏미분방정식을 풀기 위한 PyTorch 라이브러리로 Physics-Informed Neural Networks와 신경 연산자를 결합합니다","es":"pina es una biblioteca basada en PyTorch para resolver ecuaciones en derivadas parciales utilizando redes neuronales informadas por física y aprendizaje de operadores","fr":"pina est une bibliothèque basée sur PyTorch pour résoudre des équations aux dérivées partielles en utilisant des réseaux de neurones informés par la physique et un apprentissage d''opérateurs","de":"pina ist eine auf PyTorch basierende Bibliothek zur Lösung von partiellen Differentialgleichungen mit physikinformierten neuronalen Netzen und Operator-Lernen","pt":"O Pina é uma biblioteca PyTorch para solução de equações diferenciais parciais com redes neurais informadas por física. Fornece recursos como Physics-Informed Neural Networks e Neural Operators","ru":"Pina - это библиотека PyTorch для решения задач физики с помощью нейронных сетей. Она включает в себя Physics-Informed Neural Networks и Neural Operators (ИИ Агенты)","ar":"بيانة هي مكتبة بايتورش لحل المعادلات التفاضلية الجزئية باستخدام الشبكات العصبية المحددة физيائيا. توفر ميزات مثل Physics-Informed Neural Networks و Neural Operators"},"seo":{"title":{"en":"pina: Physics-Informed Neural Networks Setup Guide | AI A...","zh":"PINA 设置指南：Physics-Informed Neural Networks 与机器学习","ja":"PINA 導入ガイド：Physics-Informed Neural Networks と AI エージェント","ko":"PINA 구축 가이드: Physics-Informed Neural Networks 및 기계학습","es":"Guía de configuración de pina para redes neuronales infor...","fr":"Guide de mise en place de pina pour les réseaux de neuron...","de":"Einrichtungsleitfaden für pina zur physikinformierten neu...","pt":"Guia de Configuração do Pina para Redes Neurais Informada...","ru":"Настройка Pina для Физически-информированных нейронных се...","ar":"دليل إعداد بيانة للشبكات العصبية المحددة физيائيا"},"description":{"en":"Unlock the power of Physics-Informed Neural Networks with pina. Learn how to solve PDEs using neural networks and get started with PINA today!","zh":"了解 PINA 的技术细节及其在机器学习和 Physics-Informed Neural Networks 中的应用","ja":"PINA の技術的詳細と、AI エージェントおよび Physics-Informed Neural Networks での応用を学ぶ","ko":"PINA의 기술적 세부 사항과 기계학습 및 Physics-Informed Neural Networks에서의 적용에 대해 알아보세요","es":"Descubre cómo pina utiliza redes neuronales informadas por física y aprendizaje de operadores para resolver ecuaciones en derivadas parciales","fr":"Découvrez comment pina utilise des réseaux de neurones informés par la physique et un apprentissage d''opérateurs pour résoudre des équations aux dérivées par...","de":"Erfahren Sie, wie pina physikinformierte neuronale Netze und Operator-Lernen zur Lösung von partiellen Differentialgleichungen einsetzt","pt":"Aprenda a configurar o Pina para solução de equações diferenciais parciais com redes neurais informadas por física e MLflow","ru":"Узнайте, как настроить Pina для решения задач физики с помощью нейронных сетей и отслеживания MLflow (ИИ Агенты)","ar":"تعرف على كيفية إعداد بيانة لحل المعادلات التفاضلية الجزئية باستخدام الشبكات العصبية المحددة физيائيا وملفو"},"definition":{"en":"pina is a Physics-Informed Neural networks for Advanced modeling library, combining PINNs, Neural Operators, and Data-Driven Modeling.","zh":"PINA 是 Physics-Informed Neural networks for Advanced modeling 的缩写，用于科学机器学习","ja":"PINA は Physics-Informed Neural networks for Advanced modeling の略で、科学機械学習に使用される","ko":"PINA는 Physics-Informed Neural networks for Advanced modeling의 약자로 과학 기계학습에 사용됩니다","es":"pina es una biblioteca de aprendizaje automático que combina redes neuronales informadas por física y aprendizaje de operadores para resolver ecuaciones en derivadas parciales","fr":"pina est une bibliothèque d''apprentissage automatique qui combine des réseaux de neurones informés par la physique et un apprentissage d''opérateurs pour résoudre des équations aux dérivées partielles","de":"pina ist eine Bibliothek für maschinelles Lernen, die physikinformierte neuronale Netze und Operator-Lernen kombiniert, um partielle Differentialgleichungen zu lösen","pt":"Pina é uma biblioteca PyTorch para solução de equações diferenciais parciais com redes neurais informadas por física","ru":"Pina - это библиотека PyTorch для решения задач физики с помощью нейронных сетей","ar":"بيانة هي مكتبة بايتورش لحل المعادلات التفاضلية الجزئية باستخدام الشبكات العصبية المحددة физيائيا"},"features":{"en":["Solves forward and inverse PDE problems using Physics-Informed Neural Networks (PINNs)","Utilizes Neural Operators such as FNO and DeepONet for operator learning","Supports Data-Driven Modeling for scientific machine learning applications","Integrates with MLflow for tracking and managing machine learning experiments","Provides interactive ML notebooks with reactive updates and AI assistance"],"zh":["Physics-Informed Neural Networks (PINNs) 支持","神经操作符（Neural Operators）支持","数据驱动建模（Data-Driven Modeling）支持","PyTorch 库","偏微分方程（PDEs）求解","MLflow 跟踪"],"ja":["Physics-Informed Neural Networks (PINNs) のサポート","ニューラルオペレータ（Neural Operators）のサポート","データドリブン モデリング（Data-Driven Modeling）のサポート","PyTorch ライブラリ","偏微分方程式（PDEs）の解決","MLflow トラッキング"],"ko":["Physics-Informed Neural Networks (PINNs) 지원","신경 연산자（Neural Operators）지원","데이터 주도 모델링（Data-Driven Modeling）지원","PyTorch 라이브러리","偏미분방정식（PDEs）해결","MLflow 추적"],"es":["Redes neuronales informadas por física (PINNs) para resolver problemas de ecuaciones en derivadas parciales","Aprendizaje de operadores con FNO y DeepONet","Modelado basado en datos para resolver problemas de ecuaciones en derivadas parciales","Compatibilidad con PyTorch para una fácil integración","Seguimiento de MLflow para monitorear y gestionar experimentos"],"fr":["Réseaux de neurones informés par la physique (PINNs) pour résoudre des problèmes d''équations aux dérivées partielles","Apprentissage d''opérateurs avec FNO et DeepONet","Modélisation basée sur les données pour résoudre des problèmes d''équations aux dérivées partielles","Compatibilité avec PyTorch pour une intégration facile","Suivi de MLflow pour surveiller et gérer des expériences"],"de":["Physikinformierte neuronale Netze (PINNs) zur Lösung von partiellen Differentialgleichungen","Operator-Lernen mit FNO und DeepONet","Datengetriebenes Modellieren zur Lösung von partiellen Differentialgleichungen","Kompatibilität mit PyTorch für eine einfache Integration","MLflow-Tracking zur Überwachung und Verwaltung von Experimenten"],"pt":["Physics-Informed Neural Networks (PINNs) para solução de problemas de equações diferenciais parciais","Neural Operators como FNO e DeepONet para aprendizado de operadores","Integração com MLflow para rastreamento de experimentos","Suporte a redes neurais informadas por física para modelagem avançada","Capacidade de resolver problemas de equações diferenciais parciais para frente e inversos"],"ru":["Physics-Informed Neural Networks (PINNs) для решения задач физики","Neural Operators как FNO и DeepONet для обучения операторов","Интеграция с MLflow для отслеживания экспериментов (ИИ Агенты)","Поддержка физически-информированных нейронных сетей для продвинутого моделирования","Возможность решать задачи физики для прямых и обратных задач"],"ar":["Physics-Informed Neural Networks (PINNs) لحل مشاكل المعادلات التفاضلية الجزئية","Neural Operators مثل FNO و DeepONet للتعلم التشغيلي","التكامل مع MLflow لتتبع التجارب","دعم الشبكات العصبية المحددة физيائيا للنمذجة المتقدمة","القدرة على حل مشاكل المعادلات التفاضلية الجزئية للأمام والخلف"]},"keywords":{"en":["how to use pina","pina vs PyTorch","pina install guide","what is pina","pina alternative to traditional PDE solvers","pina setup for scientific machine learning","pina MLflow integration","pina for Physics-Informed Neural Networks","pina tutorial for beginners"],"zh":["PINA","Physics-Informed Neural Networks","机器学习","PyTorch","偏微分方程","MLflow","AI 工具","AI 에ージェнт","数据驱动建模"],"ja":["PINA","Physics-Informed Neural Networks","AI エージェント","機械学習","PyTorch","偏微分方程式","MLflow","ニューラルオペレータ","データドリブン モデリング"],"ko":["PINA","Physics-Informed Neural Networks","기계학습","PyTorch","偏미분방정식","MLflow","AI 도구","신경 연산자","데이터 주도 모델링"],"es":["pina","redes neuronales informadas por física","aprendizaje de operadores","ecuaciones en derivadas parciales","PyTorch","MLflow","modelado basado en datos","herramientas de aprendizaje automático","agentes de inteligencia artificial"],"fr":["pina","réseaux de neurones informés par la physique","apprentissage d''opérateurs","équations aux dérivées partielles","PyTorch","MLflow","modélisation basée sur les données","outils d''apprentissage automatique","agents d''intelligence artificielle"],"de":["pina","physikinformierte neuronale Netze","Operator-Lernen","partielle Differentialgleichungen","PyTorch","MLflow","datengetriebenes Modellieren","Werkzeuge für maschinelles Lernen","Künstliche Intelligenz-Tools"],"pt":["Pina","Redes Neurais Informadas por Física","Equações Diferenciais Parciais","MLflow","PyTorch","Physics-Informed Neural Networks","Neural Operators","Modelagem Avançada"],"ru":["Pina","Физически-информированные нейронные сети","Задачи физики","MLflow","PyTorch","Physics-Informed Neural Networks","Neural Operators","ИИ Агенты","Продвинутое моделирование"],"ar":["بيانة","الشبكات العصبية المحددة физيائيا","المعادلات التفاضلية الجزئية","ملفو","بايتورش","Physics-Informed Neural Networks","Neural Operators","النمذجة المتقدمة","أدوات الذكاء الاصطناعي"]}},"owner":"synapticore-io","repo":"marimo-flow","repoPath":"synapticore-io/marimo-flow","stars":10,"forks":1,"updatedAt":"2026-02-26T21:07:40Z","topics":["interactive","machine-learning","marimo","mlflow","notebooks"],"category":"community","skillMd":{"name":"pina","description":"Physics-Informed Neural Networks with PINA - solve PDEs, inverse problems, and operator learning with PyTorch","bodyPreview":"# PINA Development Skill\n\nExpert guidance for Physics-Informed Neural Networks (PINNs) and Scientific Machine Learning with PINA.\n\n## What is PINA?\n\nPINA (Physics-Informed Neural networks for Advanced modeling) is a PyTorch-based library for solving partial differential equations (PDEs) using neural networks. It combines:\n\n- **Physics-Informed Neural Networks (PINNs)**: Solve forward and inverse PDE problems\n- **Neural Operators**: FNO, DeepONet for operator learning\n- **Data-Driven Modeling**:","body":"# PINA Development Skill\n\nExpert guidance for Physics-Informed Neural Networks (PINNs) and Scientific Machine Learning with PINA.\n\n## What is PINA?\n\nPINA (Physics-Informed Neural networks for Advanced modeling) is a PyTorch-based library for solving partial differential equations (PDEs) using neural networks. It combines:\n\n- **Physics-Informed Neural Networks (PINNs)**: Solve forward and inverse PDE problems\n- **Neural Operators**: FNO, DeepONet for operator learning\n- **Data-Driven Modeling**: Supervised learning with physics constraints\n- **Reduced Order Modeling**: POD-NN for efficient simulations\n\nBuilt on: **PyTorch**, **PyTorch Lightning**, **PyTorch Geometric**\n\n## Core Workflow\n\nEvery PINA project follows these 4 steps:\n\n```python\nfrom pina import Trainer\nfrom pina.problem import SpatialProblem\nfrom pina.solver import PINN\nfrom pina.model import FeedForward\n\n# Step 1: Define Problem\nproblem = MyProblem()\nproblem.discretise_domain(n=100, mode=\"grid\")\n\n# Step 2: Design Model\nmodel = FeedForward(input_dimensions=1, output_dimensions=1, layers=[64, 64])\n\n# Step 3: Define Solver\nsolver = PINN(problem, model)\n\n# Step 4: Train\ntrainer = Trainer(solver, max_epochs=1000, accelerator=''gpu'')\ntrainer.train()\n```\n\n## Simple ODE Example\n\n```python\nfrom pina.problem import SpatialProblem\nfrom pina.domain import CartesianDomain\nfrom pina.condition import Condition\nfrom pina.equation import Equation, FixedValue\nfrom pina.operator import grad\nimport torch\n\ndef ode_equation(input_, output_):\n    \"\"\"PDE residual: du/dx - u = 0\"\"\"\n    u_x = grad(output_, input_, components=[\"u\"], d=[\"x\"])\n    u = output_.extract([\"u\"])\n    return u_x - u\n\nclass SimpleODE(SpatialProblem):\n    output_variables = [\"u\"]\n    spatial_domain = CartesianDomain({\"x\": [0, 1]})\n\n    domains = {\n        \"x0\": CartesianDomain({\"x\": 0.0}),  # Boundary\n        \"D\": CartesianDomain({\"x\": [0, 1]})  # Interior\n    }\n\n    conditions = {\n        \"bound_cond\": Condition(domain=\"x0\", equation=FixedValue(1.0)),\n        \"phys_cond\": Condition(domain=\"D\", equation=Equation(ode_equation))\n    }\n\n    def solution(self, pts):\n        \"\"\"Analytical solution for validation.\"\"\"\n        return torch.exp(pts.extract([\"x\"]))\n\nproblem = SimpleODE()\n```\n\n## Models\n\n### FeedForward Networks\n\n```python\nfrom pina.model import FeedForward\n\n# Basic network\nmodel = FeedForward(\n    input_dimensions=2,\n    output_dimensions=1,\n    layers=[64, 64, 64],  # Hidden layers\n    func=torch.nn.Tanh   # Activation function\n)\n\n# Alternative activations\nmodel = FeedForward(\n    input_dimensions=1,\n    output_dimensions=1,\n    layers=[100, 100, 100],\n    func=torch.nn.Softplus  # or torch.nn.SiLU\n)\n```\n\nSee [Custom Models Reference](references/custom_models.md) for advanced architectures including:\n- Hard constraints\n- Fourier feature embeddings\n- Periodic boundary embeddings\n- POD-NN\n- Graph neural networks\n\nSee [Neural Operators Reference](references/neural_operators.md) for operator learning with FNO, DeepONet, and more.\n\n## PINN Solver\n\n```python\nfrom pina.solver import PINN\nfrom pina.optim import TorchOptimizer\nimport torch\n\npinn = PINN(\n    problem=problem,\n    model=model,\n    optimizer=TorchOptimizer(torch.optim.Adam, lr=0.001)\n)\n```\n\nSee [Advanced Solvers Reference](references/advanced_solvers.md) for:\n- Self-Adaptive PINN (SAPINN)\n- Supervised Solver\n- Custom solvers\n- Training strategies\n\n## Training\n\n### Basic Training\n\n```python\nfrom pina import Trainer\nfrom pina.callbacks import MetricTracker\n\n# Discretize domain\nproblem.discretise_domain(n=1000, mode=\"random\", domains=\"all\")\n\n# Create trainer\ntrainer = Trainer(\n    solver=pinn,\n    max_epochs=1500,\n    accelerator=\"cpu\",  # or \"gpu\"\n    enable_model_summary=False,\n    callbacks=[MetricTracker()]\n)\n\n# Train\ntrainer.train()\n```\n\n### Training Configuration\n\n```python\ntrainer = Trainer(\n    solver=solver,\n    max_epochs=1000,\n    accelerator=\"gpu\",\n    devices=1,\n    batch_size=32,\n    gradient_clip_val=0.1,  # Gradient clipping\n    callbacks=[MetricTracker()]\n)\ntrainer.train()\n```\n\n### Testing\n\n```python\n# Test the model\ntest_results = trainer.test()\n\n# Manual evaluation\nwith torch.no_grad():\n    test_pts = problem.spatial_domain.sample(100, \"grid\")\n    prediction = solver(test_pts)\n    true_solution = problem.solution(test_pts)\n    error = torch.abs(prediction - true_solution)\n```\n\n## Domain Discretization\n\n### Sampling Modes\n\n```python\n# Grid sampling (uniform points)\nproblem.discretise_domain(n=100, mode=\"grid\", domains=[\"D\", \"x0\"])\n\n# Random sampling (Monte Carlo)\nproblem.discretise_domain(n=1000, mode=\"random\", domains=\"all\")\n\n# Latin Hypercube Sampling\nproblem.discretise_domain(n=500, mode=\"lh\", domains=[\"D\"])\n\n# Manual sampling\npts = problem.spatial_domain.sample(256, \"grid\", variables=\"x\")\n```\n\n**Best Practice**: Start with grid for testing, use random/LH for training with more points.\n\n## Visualization\n\n```python\nimport matplotlib.pyplot as plt\n\n@torch.no_grad()\ndef plot_solution(solver, n_points=256):\n    # Sample points\n    pts = solver.problem.spatial_domain.sample(n_points, \"grid\")\n\n    # Get predictions\n    predicted = solver(pts).extract(\"u\").detach()\n    true = solver.problem.solution(pts).detach()\n\n    # Plot comparison\n    fig, axes = plt.subplots(1, 3, figsize=(15, 5))\n\n    axes[0].plot(pts.extract([\"x\"]), true, label=\"True\", color=\"blue\")\n    axes[0].set_title(\"True Solution\")\n    axes[0].legend()\n\n    axes[1].plot(pts.extract([\"x\"]), predicted, label=\"PINN\", color=\"green\")\n    axes[1].set_title(\"PINN Solution\")\n    axes[1].legend()\n\n    diff = torch.abs(true - predicted)\n    axes[2].plot(pts.extract([\"x\"]), diff, label=\"Error\", color=\"red\")\n    axes[2].set_title(\"Absolute Error\")\n    axes[2].legend()\n\n    plt.tight_layout()\n    plt.show()\n```\n\nSee [Visualization Reference](references/visualization.md) for comprehensive plotting techniques.\n\n## Best Practices\n\n### 1. Start Simple\n\n```python\n# Begin with small network\nmodel = FeedForward(input_dimensions=2, output_dimensions=1, layers=[20, 20])\n\n# Gradually increase complexity\nmodel = FeedForward(input_dimensions=2, output_dimensions=1, layers=[64, 64, 64])\n```\n\n### 2. Monitor Losses\n\n```python\nfrom pina.callbacks import MetricTracker\n\ntrainer = Trainer(\n    solver=pinn,\n    max_epochs=1000,\n    callbacks=[MetricTracker([\"train_loss\", \"bound_cond_loss\", \"phys_cond_loss\"])]\n)\n```\n\n### 3. Two-Phase Training\n\n```python\n# Phase 1: Rough solution (high LR)\npinn = PINN(problem, model, optimizer=TorchOptimizer(torch.optim.Adam, lr=0.01))\ntrainer = Trainer(pinn, max_epochs=500)\ntrainer.train()\n\n# Phase 2: Refinement (low LR)\npinn.optimizer.param_groups[0][''lr''] = 0.001\ntrainer = Trainer(pinn, max_epochs=1500)\ntrainer.train()\n```\n\n## MLflow Integration\n\nTrack PINA experiments with MLflow for reproducibility and comparison:\n\n```python\nimport mlflow\nfrom pina import Trainer\nfrom pina.solver import PINN\n\n# Set experiment\nmlflow.set_experiment(\"pina-poisson-solver\")\n\nwith mlflow.start_run(run_name=\"baseline\"):\n    # Log hyperparameters\n    mlflow.log_params({\n        \"layers\": [64, 64, 64],\n        \"activation\": \"Tanh\",\n        \"learning_rate\": 0.001,\n        \"n_points\": 1000,\n        \"epochs\": 1500\n    })\n\n    # Setup and train\n    problem.discretise_domain(n=1000, mode=\"random\")\n    trainer = Trainer(solver, max_epochs=1500)\n    trainer.train()\n\n    # Log final metrics\n    mlflow.log_metric(\"final_loss\", trainer.callback_metrics[\"train_loss\"])\n\n    # Log model\n    mlflow.pytorch.log_model(solver.model, \"pinn_model\")\n```\n\n### Marimo Dashboard Integration\n\nCreate interactive PINA dashboards with marimo:\n\n```python\nimport marimo as mo\nfrom pina.solver import PINN\n\n# UI controls for hyperparameters\nlayers = mo.ui.slider(1, 5, value=3, label=\"Hidden Layers\")\nneurons = mo.ui.slider(16, 128, value=64, step=16, label=\"Neurons/Layer\")\nlr = mo.ui.number(value=0.001, start=0.0001, stop=0.1, label=\"Learning Rate\")\n\n# Train button\ntrain_btn = mo.ui.run_button(label=\"Train PINN\")\n\n# In another cell: run training when button clicked\nif train_btn.value:\n    model = FeedForward(\n        input_dimensions=2,\n        output_dimensions=1,\n        layers=[neurons.value] * layers.value\n    )\n    # ... train and visualize\n```\n\n### Using context7 for Documentation\n\nQuery up-to-date PINA documentation directly:\n\n```\n# context7 Library ID (no resolve needed):\n# - /mathlab/pina (official docs, 2345 snippets)\n\n# Example: query-docs(\"/mathlab/pina\", \"FeedForward model parameters\")\n```\n\n## When to Use This Skill\n\n✅ **Use PINA when:**\n- Solving PDEs with neural networks\n- Need to incorporate physics constraints\n- Working with inverse problems\n- Building neural operators (FNO, DeepONet)\n- Reduced order modeling\n- Scientific ML research\n\n❌ **Don''t use PINA when:**\n- Pure data-driven tasks (use standard PyTorch)\n- Not dealing with differential equations\n- Need classical numerical solvers (FEM, FVM)\n\n## Reference Documentation\n\nDetailed documentation organized by topic:\n\n- **[Problem Types](references/problem_types.md)**: ODE, Poisson, Wave, Inverse problems, custom equations\n- **[Neural Operators](references/neural_operators.md)**: FNO, DeepONet, Kernel Neural Operator\n- **[Custom Models](references/custom_models.md)**: Hard constraints, Fourier features, periodic embeddings, POD-NN, GNNs\n- **[Advanced Solvers](references/advanced_solvers.md)**: SAPINN, supervised solver, custom solvers, training strategies\n- **[Visualization](references/visualization.md)**: Plotting techniques, error analysis, animations\n\n## Complete Examples\n\nReady-to-run example scripts:\n\n- **[Poisson 2D](examples/poisson_2d.py)**: Complete 2D Poisson equation solver with visualization\n- **[Wave Equation](examples/wave_equation.py)**: Time-dependent wave equation with animations\n- **[FNO Example](examples/fno_example.py)**: Fourier Neural Operator for operator learning\n- **[Inverse Problem](examples/inverse_problem.py)**: Learn unknown parameters from data\n\n## Resources\n\n- **Documentation**: https://mathlab.github.io/PINA/\n- **GitHub**: https://github.com/mathLab/PINA\n- **Paper**: https://joss.theoj.org/papers/10.21105/joss.04813\n- **Tutorials**: https://github.com/mathLab/PINA/tree/master/tutorials\n"},"lastSynced":"2026-03-06T06:46:38.764Z","agentAnalysis":{"suitability":{"en":"Perfect for Scientific Machine Learning Agents needing advanced Physics-Informed Neural Networks (PINNs) capabilities with PyTorch.","zh":"非常适合需要高级物理信息神经网络（PINNs）功能的科学机器学习代理，具有 PyTorch。","ja":"PyTorch を使用した高度な物理情報ニューラルネットワーク（PINNs）機能を必要とする科学機械学習エージェントに最適。","ko":"PyTorch를 사용한 고급 물리 정보 신경 네트워크(PINNs) 기능이 필요한 과학 머신 러닝 에이전트에 적합합니다.","es":"Perfecto para Agentes de Aprendizaje Automático Científico que necesitan capacidades avanzadas de Redes Neurales Informadas por Física (PINNs) con PyTorch.","fr":"Parfait pour les Agents d''Apprentissage Automatique Scientifique ayant besoin de capacités avancées de Réseaux de Neurones Informés par la Physique (PINNs) avec PyTorch.","de":"Perfekt für wissenschaftliche Machine-Learning-Agents, die erweiterte Physics-Informed Neural Networks (PINNs)-Funktionen mit PyTorch benötigen.","pt":"Perfeito para Agentes de Aprendizado de Máquina Científica que necessitam de capacidades avançadas de Redes Neurais Informadas por Física (PINNs) com PyTorch.","ru":"Идеально подходит для научных агентов машинного обучения, требующих расширенных возможностей физически информированных нейронных сетей (PINNs) с PyTorch.","ar":"مثالي لعمليات الوكيل العلمي للتعلم الآلي التي تحتاج إلى قدرات متقدمة من الشبكات العصبية المُحَدَدة بِالفيزياء (PINNs) مع PyTorch."},"recommendation":{"en":"Empowers agents to solve forward and inverse partial differential equations (PDEs) using neural networks, leveraging Physics-Informed Neural Networks (PINNs), Neural Operators like FNO and DeepONet, and Data-Driven Modeling, all within the PyTorch framework.","zh":"赋予代理使用神经网络解决前向和逆向偏微分方程（PDEs），利用物理信息神经网络（PINNs），神经算子如 FNO 和 DeepONet，以及数据驱动建模，所有这些都在 PyTorch 框架内。","ja":"エージェントが神経ネットワークを使用して前方と逆方向の偏微分方程式（PDEs）を解くことを可能にし、物理情報ニューラルネットワーク（PINNs）、神経演算子 such as FNO と DeepONet、データ駆動型モデリングを利用し、すべてこれらを PyTorch フレームワーク内で。","ko":"에이전트가 신경망을 사용하여 전방 및 역방향 편미분 방정식(PDEs)을 해결할 수 있도록 하여 물리 정보 신경망(PINNs), 신경 연산자(FNO 및 DeepONet) 및 데이터 주도 모델링을 활용하고 모든 것을 PyTorch 프레임워크 내에서 수행할 수 있도록 합니다.","es":"Habilita a los agentes a resolver ecuaciones en derivadas parciales directas e inversas (PDEs) utilizando redes neuronales, aprovechando Redes Neurales Informadas por Física (PINNs), Operadores Neuronales como FNO y DeepONet, y Modelado basado en Datos, todo dentro del marco de PyTorch.","fr":"Permet aux agents de résoudre des équations aux dérivées partielles directes et inverses (PDEs) en utilisant des réseaux de neurones, en exploitant des Réseaux de Neurones Informés par la Physique (PINNs), des Opérateurs Neuraux comme FNO et DeepONet, et la Modélisation basée sur les Données, le tout dans le cadre de PyTorch.","de":"Ermöglicht es Agents, vorwärts- und inverse partielle Differentialgleichungen (PDEs) mit neuronalen Netzen zu lösen, indem es Physics-Informed Neural Networks (PINNs), neuronale Operatoren wie FNO und DeepONet sowie datengetriebene Modellierung innerhalb des PyTorch-Frameworks nutzt.","pt":"Habilita os agentes a resolver equações diferenciais parciais diretas e inversas usando redes neurais, aproveitando Redes Neurais Informadas por Física (PINNs), Operadores Neurais como FNO e DeepONet e Modelagem Orientada por Dados, tudo dentro do framework PyTorch.","ru":"Наделяет агентов возможностью решать прямые и обратные частные дифференциальные уравнения (ЧДУ) с помощью нейронных сетей, используя физически информированные нейронные сети (PINNs), нейронные операторы, такие как FNO и DeepONet, и моделирование, основанное на данных, все в рамках фреймворка PyTorch.","ar":"تمكّن الوكيل من حل المعادلات التفاضلية الجزئية الأمامية والخلفية باستخدام الشبكات العصبية، واستغلال الشبكات العصبية المُحَدَدة بِالفيزياء (PINNs) والمشغلات العصبية مثل FNO وDeepONet والتعلم القائم على البيانات، كل ذلك داخل إطار PyTorch."},"useCases":{"en":["Solving complex partial differential equations (PDEs) for scientific simulations","Implementing Neural Operators for operator learning in various domains","Developing data-driven models for real-world applications using PINA''s PyTorch-based library"],"zh":["解决科学模拟的复杂偏微分方程（PDEs）","在各个领域中实现神经运算符以进行运算符学习","使用 PINA 的 PyTorch 基础库开发面向实际应用的数据驱动模型"],"ja":["科学シミュレーションの複雑な偏微分方程式（PDEs）を解く","さまざまなドメインでオペレータ学習のためのニューラルオペレータを実装する","PINA の PyTorch ベースのライブラリを使用して実際のアプリケーション向けのデータ駆動型モデルを開発する"],"ko":["과학 시뮬레이션을 위한 복잡한 편미분 방정식(PDEs) 풀이","신경 연산자를 다양한 도메인에서 연산자 학습에 사용하여 구현","PINA의 PyTorch 기반 라이브러리를 사용하여 실제 애플리케이션을 위한 데이터 주도 모델 개발"],"es":["Resolución de ecuaciones en derivadas parciales complejas (PDEs) para simulaciones científicas","Implementación de Operadores Neuronales para el aprendizaje de operadores en varios dominios","Desarrollo de modelos basados en datos para aplicaciones del mundo real utilizando la biblioteca basada en PyTorch de PINA"],"fr":["Résolution d''équations aux dérivées partielles complexes (PDEs) pour des simulations scientifiques","Mise en œuvre d''Opérateurs Neuraux pour l''apprentissage d''opérateurs dans divers domaines","Développement de modèles basés sur les données pour des applications du monde réel en utilisant la bibliothèque basée sur PyTorch de PINA"],"de":["Lösen komplexer partieller Differentialgleichungen (PDEs) für wissenschaftliche Simulationen","Implementierung neuronaler Operatoren für Operator-Lernen in verschiedenen Bereichen","Entwicklung datengetriebener Modelle für reale Anwendungen unter Verwendung der PyTorch-basierten Bibliothek von PINA"],"pt":["Resolver equações diferenciais parciais complexas (PDEs) para simulações científicas","Implementar Operadores Neurais para aprendizado de operador em vários domínios","Desenvolver modelos baseados em dados para aplicações do mundo real usando a biblioteca baseada em PyTorch da PINA"],"ru":["Решать сложные частные дифференциальные уравнения (ЧДУ) для научных симуляций","Реализовывать нейронные операторы для обучения операторов в различных областях","Разрабатывать модели, основанные на данных, для реальных приложений с помощью библиотеки PINA на основе PyTorch"],"ar":["حل المعادلات التفاضلية الجزئية المعقدة (PDEs) لمحاكاة علمية","تنفيذ مشغلات عصبية للتعلم المشغل في مجالات متعددة","تطوير نماذج قائمة على البيانات لتطبيقات العالم الحقيقي باستخدام مكتبة PINA القائمة على PyTorch"]},"limitations":{"en":["Requires PyTorch installation and compatibility","Limited to solving partial differential equations and related scientific machine learning tasks"],"zh":["需要 PyTorch 安装和兼容性","仅限于解偏微分方程和相关的科学机器学习任务"],"ja":["PyTorch のインストールと互換性が必要","偏微分方程式と関連する科学機械学習タスクの解決のみに限定"],"ko":["PyTorch 설치 및 호환성이 필요함","편미분 방정식 및 관련 과학 머신 러닝 작업의 풀이만으로 제한됨"],"es":["Requiere instalación y compatibilidad de PyTorch","Limitado a la resolución de ecuaciones en derivadas parciales y tareas de aprendizaje automático científico relacionadas"],"fr":["Nécessite l''installation et la compatibilité de PyTorch","Limité à la résolution d''équations aux dérivées partielles et aux tâches d''apprentissage automatique scientifique associées"],"de":["Benötigt PyTorch-Installation und -Kompatibilität","Begrenzt auf das Lösen partieller Differentialgleichungen und damit verbundene wissenschaftliche Machine-Learning-Aufgaben"],"pt":["Requer instalação e compatibilidade do PyTorch","Limitado à resolução de equações diferenciais parciais e tarefas de aprendizado de máquina científica relacionadas"],"ru":["Требует установки и совместимости PyTorch","Ограничен решением частных дифференциальных уравнений и связанных с этим задач научного машинного обучения"],"ar":["يتطلب تثبيت PyTorch ومتوافقيته","محدود بحل المعادلات التفاضلية الجزئية والمهام المرتبطة بالتعلم الآلي العلمي"]},"version":4},"contentHash":"1b64ccef232eecc62dc8a2ab591aa189cf9a2558cdf44db614ba562319f7440b","qualityScore":54}');
