INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('synapticore-io/marimo-flow/pina', 'pina', 'synapticore-io', 'marimo-flow', 'community', 'pina synapticore-io marimo-flow community interactive machine-learning marimo mlflow notebooks pina is a PyTorch-based library for solving partial differential equations using neural networks, benefiting developers and researchers in scientific machine learning. PINA 是一个用于解决偏微分方程的 PyTorch 库，结合 Physics-Informed Neural Networks 和神经操作符 PINA は、偏微分方程を解くための PyTorch ライブラリで、Physics-Informed Neural Networks とニューラルオペレータを組み合わせる PINA는偏미분방정식을 풀기 위한 PyTorch 라이브러리로 Physics-Informed Neural Networks와 신경 연산자를 결합합니다 pina es una biblioteca basada en PyTorch para resolver ecuaciones en derivadas parciales utilizando redes neuronales informadas por física y aprendizaje de operadores pina est une bibliothèque basée sur PyTorch pour résoudre des équations aux dérivées partielles en utilisant des réseaux de neurones informés par la physique et un apprentissage d''opérateurs pina ist eine auf PyTorch basierende Bibliothek zur Lösung von partiellen Differentialgleichungen mit physikinformierten neuronalen Netzen und Operator-Lernen O Pina é uma biblioteca PyTorch para solução de equações diferenciais parciais com redes neurais informadas por física. Fornece recursos como Physics-Informed Neural Networks e Neural Operators Pina - это библиотека PyTorch для решения задач физики с помощью нейронных сетей. Она включает в себя Physics-Informed Neural Networks и Neural Operators (ИИ Агенты) بيانة هي مكتبة بايتورش لحل المعادلات التفاضلية الجزئية باستخدام الشبكات العصبية المحددة физيائيا. توفر ميزات مثل Physics-Informed Neural Networks و Neural Operators how to use pina pina vs PyTorch pina install guide what is pina pina alternative to traditional PDE solvers pina setup for scientific machine learning pina MLflow integration pina for Physics-Informed Neural Networks pina tutorial for beginners PINA Physics-Informed Neural Networks 机器学习 PyTorch 偏微分方程 MLflow AI 工具 AI 에ージェнт 数据驱动建模 Solves forward and inverse PDE problems using Physics-Informed Neural Networks (PINNs) Utilizes Neural Operators such as FNO and DeepONet for operator learning Supports Data-Driven Modeling for scientific machine learning applications Integrates with MLflow for tracking and managing machine learning experiments Provides interactive ML notebooks with reactive updates and AI assistance pina is a Physics-Informed Neural networks for Advanced modeling library, combining PINNs, Neural Operators, and Data-Driven Modeling.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('charl-kruger/charl/agents-sdk', 'community', 'charl-kruger', 'charl', 'charl-kruger/charl', 'agents-sdk', 0, 0, 54, '2026-03-07T12:46:33.564Z', '2026-03-07T12:57:30.862Z', '7c54b8dc6556f2a5698d29b6bd6409edd244e7e46031acacd14f4a5a6296a8f7', '{"id":"charl-kruger/charl/agents-sdk","name":"agents-sdk","description":{"en":"The agents-sdk is an npm package for developers to build persistent, stateful AI agents on Cloudflare Workers. It requires durable object bindings and SQLite migrations for state management, targeting developers creating long-lived AI applications.","zh":"Cloudflare Agents SDK 是一个用于构建持久、状态管理的 AI 代理的工具，基于 Cloudflare Workers 和 SQLite 存储","ja":"Cloudflare Agents SDK は、Cloudflare Workers と SQLite ストレージに基づいて、持続的で状態管理された AI エージェントを構築するためのツール","ko":"Cloudflare Agents SDK는 Cloudflare Workers와 SQLite 스토리지를 기반으로 지속적이고 상태 관리된 AI 에이전트를 구축하는 도구","es":"El SDK de agents permite a los desarrolladores crear agentes de inteligencia artificial estatales en Cloudflare Workers utilizando el paquete npm ''agents''","fr":"Le SDK d''agents permet aux développeurs de créer des agents d''intelligence artificielle étatiques sur Cloudflare Workers en utilisant le paquet npm ''agents''","de":"Das agents-SDK ermöglicht es Entwicklern, Zustands-IA-Agenten in Cloudflare Workers mithilfe des npm-Pakets ''agents'' zu erstellen","pt":"O Agents SDK permite criar agentes de IA persistentes e stateful com Cloudflare Workers. Veja como instalar e configurar.","ru":"Agents SDK позволяет создавать персистентные и состоятельные ИИ агенты с Cloudflare Workers. Узнайте, как установить и настроить.","ar":"يسمح Agents SDK بإنشاء وكلاء ذكاء اصطناعي متواصلين وثابتين مع Cloudflare Workers. تعلم كيفية التثبيت والتكوين."},"seo":{"title":{"en":"agents-sdk: Build Persistent AI Agents on Workers | AI Ag...","zh":"Cloudflare Agents SDK 入门指南 - 构建持久的 AI 代理","ja":"Cloudflare Agents SDK Setup Guide - AIエージェントの構築","ko":"Cloudflare Agents SDK 시작 가이드 - 지속적인 AI 에이전트 구축","es":"Guía de configuración de agents-sdk para desarrolladores","fr":"Mise en route de agents-sdk pour les développeurs","de":"Einrichtungsleitfaden für agents-sdk-Entwickler","pt":"Guia de Configuração do Agents SDK para Ferramentas de IA","ru":"Руководство по настройке Agents SDK для ИИ Агентов","ar":"دليل إعداد Agents SDK لأدوات الذكاء الاصطناعي"},"description":{"en":"Learn how the agents-sdk npm package enables stateful AI agents on Cloudflare Workers. Our guide covers durable object bindings, SQLite migrations, and persi...","zh":"使用 Cloudflare Agents SDK 和 Workers 构建持久的 AI 代理，实现状态管理和 SQLite 存储","ja":"Cloudflare Agents SDK と Workers を使用して、状態管理と SQLite ストレージを実現する持続的な AI エージェントを構築","ko":"Cloudflare Agents SDK와 Workers를 사용하여 상태 관리와 SQLite 스토리지를 구현하는 지속적인 AI 에이전트를 구축","es":"Aprende a instalar y configurar agents-sdk para crear agentes de inteligencia artificial estatales en Cloudflare Workers","fr":"Découvrez comment installer et configurer agents-sdk pour créer des agents d''intelligence artificielle étatiques sur Cloudflare Workers","de":"Erfahren Sie, wie Sie agents-sdk installieren und konfigurieren, um Zustands-IA-Agenten in Cloudflare Workers zu erstellen","pt":"Aprenda a instalar e configurar o Agents SDK para criar agentes de IA persistentes e stateful com Cloudflare Workers","ru":"Узнайте, как установить и настроить Agents SDK для создания персистентных и состоятельных ИИ агентов с Cloudflare Workers","ar":"تعلم كيفية تثبيت وتكوين Agents SDK لإنشاء وكلاء ذكاء اصطناعي متواصلين وثابتين مع Cloudflare Workers"},"definition":{"en":"agents-sdk is an npm package that provides the tools to build persistent, stateful AI agents on Cloudflare Workers. It utilizes Durable Objects for statefulness and requires specific bindings and SQLite migrations in the wrangler.jsonc configuration file.","zh":"Cloudflare Agents SDK 是一个用于构建持久的 AI 代理的软件开发工具包","ja":"Cloudflare Agents SDK は、持続的な AI エージェントを構築するためのソフトウェア開発キット","ko":"Cloudflare Agents SDK는 지속적인 AI 에이전트를 구축하는 소프트웨어 개발 키트","es":"Un agente de inteligencia artificial estatal es un programa que utiliza el SDK de agents para mantener un estado en Cloudflare Workers","fr":"Un agent d''intelligence artificielle étatique est un programme qui utilise le SDK d''agents pour maintenir un état sur Cloudflare Workers","de":"Ein Zustands-IA-Agent ist ein Programm, das das agents-SDK verwendet, um einen Zustand in Cloudflare Workers beizubehalten","pt":"O Agents SDK é uma biblioteca que permite criar agentes de IA persistentes e stateful com Cloudflare Workers","ru":"Agents SDK - это библиотека, которая позволяет создавать персистентные и состоятельные ИИ агенты с Cloudflare Workers","ar":"Agents SDK هو مكتبة تسمح بإنشاء وكلاء ذكاء اصطناعي متواصلين وثابتين مع Cloudflare Workers"},"features":{"en":["Installs via npm install agents for immediate use in projects","Requires durable_objects bindings in wrangler.jsonc for state management","Uses class_name binding that must match your Agent class name exactly","Requires SQLite migrations tagged for persistent data storage","Enables building stateful AI agents on the Cloudflare Workers platform"],"zh":["使用npm包`agents`构建持久的AI代理","支持Cloudflare Workers和SQLite存储","需要在`wrangler.jsonc`中绑定Agent类","支持状态管理和持久化","使用JSONC配置文件进行设置"],"ja":["npmパッケージ`agents`を使用して持続的なAIエージェントを構築","Cloudflare WorkersとSQLiteストレージをサポート","Agentクラスを`wrangler.jsonc`にバインドする必要","状態管理と永続化をサポート","JSONC設定ファイルを使用して設定"],"ko":["npm 패키지 `agents`를 사용하여 지속적인 AI 에이전트를 구축","Cloudflare Workers와 SQLite 스토리지를 지원","Agent 클래스를 `wrangler.jsonc`에 바인드해야 함","상태 관리와 영속화를 지원","JSONC 설정 파일을 사용하여 설정"],"es":["Creación de agentes de inteligencia artificial estatales en Cloudflare Workers","Uso del paquete npm ''agents'' para la instalación","Requiere una vinculación en ''wrangler.jsonc'' para el funcionamiento","Soporte para almacenamiento de SQLite","Posibilidad de crear clases de agentes personalizadas"],"fr":["Création d''agents d''intelligence artificielle étatiques sur Cloudflare Workers","Utilisation du paquet npm ''agents'' pour l''installation","Nécessite une liaison dans ''wrangler.jsonc'' pour le fonctionnement","Prise en charge du stockage SQLite","Possibilité de créer des classes d''agents personnalisées"],"de":["Erstellung von Zustands-IA-Agenten in Cloudflare Workers","Verwendung des npm-Pakets ''agents'' für die Installation","Erfordert eine Bindung in ''wrangler.jsonc'' für den Betrieb","Unterstützung für SQLite-Speicher","Möglichkeit, benutzerdefinierte Agentenklassen zu erstellen"],"pt":["Criação de agentes de IA persistentes e stateful","Integração com Cloudflare Workers","Uso do pacote npm ''agents''","Requer binding em ''wrangler.jsonc''","Suporte a armazenamento SQLite","Requer lista de classes de agentes para migração"],"ru":["Создание персистентных и состоятельных ИИ агентов","Интеграция с Cloudflare Workers","Использование пакета npm ''agents''","Требуется привязка в ''wrangler.jsonc''","Поддержка хранилища SQLite","Требуется список классов агентов для миграции"],"ar":["إنشاء وكلاء ذكاء اصطناعي متواصلين وثابتين","التكامل مع Cloudflare Workers","استخدام حزمة npm ''agents''","يتطلب ربطًا في ''wrangler.jsonc''","دعم تخزين SQLite","يتطلب قائمة بفصول الوكلاء للترحيل"]},"keywords":{"en":["how to use agents-sdk","what is agents-sdk","agents-sdk vs durable objects","agents-sdk alternative","agents-sdk install guide","agents-sdk setup Cloudflare Workers","agents-sdk npm package","agents-sdk wrangler.jsonc configuration"],"zh":["Cloudflare Agents SDK","AI 代理","持久性","状态管理","SQLite 存储","Cloudflare Workers","npm 包","wrangler.jsonc"],"ja":["Cloudflare Agents SDK","AIエージェント","持続性","状態管理","SQLiteストレージ","Cloudflare Workers","npmパッケージ","wrangler.jsonc"],"ko":["Cloudflare Agents SDK","AI 에이전트","지속성","상태 관리","SQLite 스토리지","Cloudflare Workers","npm 패키지","wrangler.jsonc"],"es":["agents-sdk","Cloudflare Workers","inteligencia artificial estatal","npm agents","wrangler.jsonc","SQLite","desarrollo de agentes de IA","configuración de agents-sdk","creación de agentes de inteligencia artificial"],"fr":["agents-sdk","Cloudflare Workers","intelligence artificielle étatique","npm agents","wrangler.jsonc","SQLite","développement d''agents d''IA","configuration de agents-sdk","création d''agents d''intelligence artificielle"],"de":["agents-sdk","Cloudflare Workers","Zustands-IA","npm agents","wrangler.jsonc","SQLite","Entwicklung von IA-Agenten","Konfiguration von agents-sdk","Erstellung von Zustands-IA-Agenten"],"pt":["Agents SDK","IA","Cloudflare Workers","npm agents","wrangler.jsonc","SQLite","desenvolvimento de IA","ferramentas de IA","Guia de configuração"],"ru":["Agents SDK","ИИ","Cloudflare Workers","npm agents","wrangler.jsonc","SQLite","разработка ИИ","инструменты ИИ","Руководство по настройке"],"ar":["Agents SDK","الذكاء الاصطناعي","Cloudflare Workers","npm agents","wrangler.jsonc","SQLite","تطوير الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","دليل الإعداد"]}},"owner":"charl-kruger","repo":"charl","repoPath":"charl-kruger/charl","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.564Z","topics":[],"category":"community","skillMd":{"name":"agents-sdk","description":"Build stateful AI agents using the Cloudflare Agents SDK. Load when creating agents with persistent state, scheduling, RPC, MCP servers, email handling, or streaming chat. Covers Agent class, AIChatAgent, state management, and Code Mode for reduced token usage.","bodyPreview":"# Cloudflare Agents SDK\n\nBuild persistent, stateful AI agents on Cloudflare Workers using the `agents` npm package.\n\n## FIRST: Verify Installation\n\n```bash\nnpm install agents\n```\n\nAgents require a binding in `wrangler.jsonc`:\n\n```jsonc\n{\n  \"durable_objects\": {\n    // \"class_name\" must match your Agent class name exactly\n    \"bindings\": [{ \"name\": \"Counter\", \"class_name\": \"Counter\" }]\n  },\n  \"migrations\": [\n    // Required: list all Agent classes for SQLite storage\n    { \"tag\": \"v1\", \"new_sqlite_","body":"# Cloudflare Agents SDK\n\nBuild persistent, stateful AI agents on Cloudflare Workers using the `agents` npm package.\n\n## FIRST: Verify Installation\n\n```bash\nnpm install agents\n```\n\nAgents require a binding in `wrangler.jsonc`:\n\n```jsonc\n{\n  \"durable_objects\": {\n    // \"class_name\" must match your Agent class name exactly\n    \"bindings\": [{ \"name\": \"Counter\", \"class_name\": \"Counter\" }]\n  },\n  \"migrations\": [\n    // Required: list all Agent classes for SQLite storage\n    { \"tag\": \"v1\", \"new_sqlite_classes\": [\"Counter\"] }\n  ]\n}\n```\n\n## Choosing an Agent Type\n\n| Use Case                      | Base Class    | Package               |\n| ----------------------------- | ------------- | --------------------- |\n| Custom state + RPC, no chat   | `Agent`       | `agents`              |\n| Chat with message persistence | `AIChatAgent` | `@cloudflare/ai-chat` |\n| Building an MCP server        | `McpAgent`    | `agents/mcp`          |\n\n## Key Concepts\n\n- **Agent** base class provides state, scheduling, RPC, MCP, and email capabilities\n- **AIChatAgent** adds streaming chat with automatic message persistence and resumable streams\n- **Code Mode** generates executable code instead of tool calls—reduces token usage significantly\n- **this.state / this.setState()** - automatic persistence to SQLite, broadcasts to clients\n- **this.schedule()** - schedule tasks at Date, delay (seconds), or cron expression\n- **@callable** decorator - expose methods to clients via WebSocket RPC\n\n## Quick Reference\n\n| Task            | API                                                        |\n| --------------- | ---------------------------------------------------------- |\n| Persist state   | `this.setState({ count: 1 })`                              |\n| Read state      | `this.state.count`                                         |\n| Schedule task   | `this.schedule(60, \"taskMethod\", payload)`                 |\n| Schedule cron   | `this.schedule(\"0 * * * *\", \"hourlyTask\")`                 |\n| Cancel schedule | `this.cancelSchedule(id)`                                  |\n| Queue task      | `this.queue(\"processItem\", payload)`                       |\n| SQL query       | `` this.sql`SELECT * FROM users WHERE id = ${id}` ``       |\n| RPC method      | `@callable() async myMethod() { ... }`                     |\n| Streaming RPC   | `@callable({ streaming: true }) async stream(res) { ... }` |\n\n## Minimal Agent\n\n```typescript\nimport { Agent, routeAgentRequest, callable } from \"agents\";\n\ntype State = { count: number };\n\nexport class Counter extends Agent<Env, State> {\n  initialState = { count: 0 };\n\n  @callable()\n  increment() {\n    this.setState({ count: this.state.count + 1 });\n    return this.state.count;\n  }\n}\n\nexport default {\n  fetch: (req, env) =>\n    routeAgentRequest(req, env) ?? new Response(\"Not found\", { status: 404 })\n};\n```\n\n## Streaming Chat Agent\n\nUse `AIChatAgent` for chat with automatic message persistence and resumable streaming.\n\n**Install additional dependencies first:**\n\n```bash\nnpm install @cloudflare/ai-chat ai @ai-sdk/openai\n```\n\n**Add wrangler.jsonc config** (same pattern as base Agent):\n\n```jsonc\n{\n  \"durable_objects\": {\n    \"bindings\": [{ \"name\": \"Chat\", \"class_name\": \"Chat\" }]\n  },\n  \"migrations\": [{ \"tag\": \"v1\", \"new_sqlite_classes\": [\"Chat\"] }]\n}\n```\n\n```typescript\nimport { AIChatAgent } from \"@cloudflare/ai-chat\";\nimport { routeAgentRequest } from \"agents\";\nimport { streamText, convertToModelMessages } from \"ai\";\nimport { openai } from \"@ai-sdk/openai\";\n\nexport class Chat extends AIChatAgent<Env> {\n  async onChatMessage(onFinish) {\n    const result = streamText({\n      model: openai(\"gpt-4o\"),\n      messages: await convertToModelMessages(this.messages),\n      onFinish\n    });\n    return result.toUIMessageStreamResponse();\n  }\n}\n\nexport default {\n  fetch: (req, env) =>\n    routeAgentRequest(req, env) ?? new Response(\"Not found\", { status: 404 })\n};\n```\n\n**Client** (React):\n\n```tsx\nimport { useAgent } from \"agents/react\";\nimport { useAgentChat } from \"@cloudflare/ai-chat/react\";\n\nconst agent = useAgent({ agent: \"Chat\", name: \"my-chat\" });\nconst { messages, input, handleSubmit } = useAgentChat({ agent });\n```\n\n## Detailed References\n\n- **[references/state-scheduling.md](references/state-scheduling.md)** - State persistence, scheduling, queues\n- **[references/streaming-chat.md](references/streaming-chat.md)** - AIChatAgent, resumable streams, UI patterns\n- **[references/codemode.md](references/codemode.md)** - Generate code instead of tool calls (token savings)\n- **[references/mcp.md](references/mcp.md)** - MCP server integration\n- **[references/email.md](references/email.md)** - Email routing and handling\n\n## When to Use Code Mode\n\nCode Mode generates executable JavaScript instead of making individual tool calls. Use it when:\n\n- Chaining multiple tool calls in sequence\n- Complex conditional logic across tools\n- MCP server orchestration (multiple servers)\n- Token budget is constrained\n\nSee [references/codemode.md](references/codemode.md) for setup and examples.\n\n## Best Practices\n\n1. **Prefer streaming**: Use `streamText` and `toUIMessageStreamResponse()` for chat\n2. **Use AIChatAgent for chat**: Handles message persistence and resumable streams automatically\n3. **Type your state**: `Agent<Env, State>` ensures type safety for `this.state`\n4. **Use @callable for RPC**: Cleaner than manual WebSocket message handling\n5. **Code Mode for complex workflows**: Reduces round-trips and token usage\n6. **Schedule vs Queue**: Use `schedule()` for time-based, `queue()` for sequential processing\n"},"lastSynced":"2026-03-07T12:57:30.862Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloudflare Agents needing persistent, stateful AI applications with durable object bindings and SQLite migrations.","zh":"适合需要持久、有状态 AI 应用程序的 Cloudflare Agents，具有可靠的对象绑定和 SQLite 迁移。","ja":"Cloudflare Agents に対して、持続的なステートフル AI アプリケーションと堅牢なオブジェクト バインディングおよび SQLite 移行が必要な場合に適しています。","ko":"클라우드플레어 에이전트에 적합하며 지속적이고 상태가 있는 AI 애플리케이션과 견고한 객체 바인딩 및 SQLite 마이그레이션이 필요합니다.","es":"Ideal para los agentes de Cloudflare que necesitan aplicaciones de IA persistentes y con estado, con enlaces de objetos duraderos y migraciones de SQLite.","fr":"Parfait pour les agents Cloudflare nécessitant des applications d''IA persistantes et avec état, avec des liaisons d''objets durables et des migrations SQLite.","de":"Perfekt für Cloudflare Agents, die persistente, zustandsbehaftete KI-Anwendungen mit durable object bindings und SQLite-Migrationen benötigen.","pt":"Perfeito para Agentes Cloudflare que precisam de aplicações de IA persistentes e stateful com vinculações de objetos duráveis e migrações SQLite.","ru":"Идеально для агентов Cloudflare, которым требуются постоянные, stateful-приложения ИИ с прочными связями объектов и миграциями SQLite.","ar":"مثالي للوكلاء Cloudflare الذين يحتاجون إلى تطبيقات ذكاء اصطناعي مستمرة وتخزين الحالة مع ربط كائنات متينة وترحيلات SQLite."},"recommendation":{"en":"Empowers agents to build long-lived AI applications on Cloudflare Workers using the `agents` npm package, leveraging durable object bindings and SQLite migrations for robust state management, and targeting developers with wrangler.jsonc configurations.","zh":"赋予代理构建长期运行的 AI 应用程序的能力，使用 Cloudflare Workers 和 `agents` npm 包，利用可靠的对象绑定和 SQLite 迁移进行状态管理，并针对具有 wrangler.jsonc 配置的开发人员。","ja":"エージェントが Cloudflare Workers と `agents` npm パッケージを使用して、長期間実行される AI アプリケーションを構築できるようにすることで、堅牢なオブジェクト バインディングと SQLite 移行を使用したロバストな状態管理を提供し、wrangler.jsonc 構成を持つ開発者を対象としています。","ko":"에이전트가 Cloudflare Workers와 `agents` npm 패키지를 사용하여 장기간 실행되는 AI 애플리케이션을 구축할 수 있도록 하여 강력한 객체 바인딩과 SQLite 마이그레이션을 사용한 강력한 상태 관리를 제공하며 wrangler.jsonc 구성이 있는 개발자를 대상으로 합니다.","es":"Permite a los agentes construir aplicaciones de IA de larga duración en Cloudflare Workers utilizando el paquete npm `agents`, aprovechando los enlaces de objetos duraderos y las migraciones de SQLite para una gestión de estado robusta, y dirigido a desarrolladores con configuraciones de wrangler.jsonc.","fr":"Permet aux agents de construire des applications d''IA de longue durée sur Cloudflare Workers en utilisant le package npm `agents`, en tirant parti des liaisons d''objets durables et des migrations SQLite pour une gestion d''état robuste, et ciblant les développeurs avec des configurations wrangler.jsonc.","de":"Ermöglicht es Agents, langlebige KI-Anwendungen auf Cloudflare Workers mit dem `agents` npm-Paket zu erstellen, nutzt durable object bindings und SQLite-Migrationen für robustes Zustandsmanagement und richtet sich an Entwickler mit wrangler.jsonc-Konfigurationen.","pt":"Habilita os agentes a construir aplicações de IA de longa duração no Cloudflare Workers usando o pacote npm `agents`, aproveitando as vinculações de objetos duráveis e as migrações SQLite para um gerenciamento de estado robusto, e direcionando os desenvolvedores com configurações wrangler.jsonc.","ru":"Наделяет агентов возможностью создавать долгоживущие приложения ИИ на Cloudflare Workers с использованием пакета npm `agents`, используя прочные связи объектов и миграции SQLite для надежного управления состоянием, и ориентируясь на разработчиков с конфигурациями wrangler.jsonc.","ar":"تمكّن الوكلاء من بناء تطبيقات ذكاء اصطناعي طويلة الأمد على Cloudflare Workers باستخدام حزمة npm `agents` ، واستخدام ربط الكائنات المتينة وترحيلات SQLite لإدارة الحالة القوية ، والاستهداف المطورين مع تكوينات wrangler.jsonc."},"useCases":{"en":["Building persistent AI agents with Cloudflare Workers","Managing state with durable object bindings and SQLite migrations","Creating long-lived AI applications with the `agents` npm package"],"zh":["使用 Cloudflare Workers 构建持久的 AI 代理","使用可靠的对象绑定和 SQLite 迁移管理状态","使用 `agents` npm 包构建长期运行的 AI 应用程序"],"ja":["Cloudflare Workers を使用して持続的な AI エージェントを構築する","堅牢なオブジェクト バインディングと SQLite 移行を使用して状態を管理する","`agents` npm パッケージを使用して長期間実行される AI アプリケーションを構築する"],"ko":["클라우드플레어 워커를 사용하여 지속적인 AI 에이전트 구축","강력한 객체 바인딩과 SQLite 마이그레이션을 사용하여 상태 관리","`agents` npm 패키지를 사용하여 장기간 실행되는 AI 애플리케이션 구축"],"es":["Construcción de agentes de IA persistentes con Cloudflare Workers","Gestión del estado con enlaces de objetos duraderos y migraciones de SQLite","Creación de aplicaciones de IA de larga duración con el paquete npm `agents`"],"fr":["Construction d''agents d''IA persistants avec Cloudflare Workers","Gestion de l''état avec des liaisons d''objets durables et des migrations SQLite","Création d''applications d''IA de longue durée avec le package npm `agents`"],"de":["Aufbau persistenter KI-Agents mit Cloudflare Workers","Zustandsverwaltung mit durable object bindings und SQLite-Migrationen","Erstellung langlebiger KI-Anwendungen mit dem `agents` npm-Paket"],"pt":["Construção de agentes de IA persistentes com Cloudflare Workers","Gerenciamento de estado com vinculações de objetos duráveis e migrações SQLite","Criação de aplicações de IA de longa duração com o pacote npm `agents`"],"ru":["Создание постоянных агентов ИИ с Cloudflare Workers","Управление состоянием с помощью прочных связей объектов и миграций SQLite","Создание долгоживущих приложений ИИ с помощью пакета npm `agents`"],"ar":["بناء وكلاء ذكاء اصطناعي مستمرين مع Cloudflare Workers","إدارة الحالة باستخدام ربط الكائنات المتينة وترحيلات SQLite","إنشاء تطبيقات ذكاء اصطناعي طويلة الأمد باستخدام حزمة npm `agents`"]},"limitations":{"en":["Requires durable object bindings","Needs SQLite migrations for state management","Cloudflare Workers only","Requires specific configuration in wrangler.jsonc"],"zh":["需要可靠的对象绑定","需要 SQLite 迁移进行状态管理","仅限 Cloudflare Workers","需要在 wrangler.jsonc 中进行特定配置"],"ja":["堅牢なオブジェクト バインディングが必要","状態管理のために SQLite 移行が必要","Cloudflare Workers 限定","wrangler.jsonc 内の特定の構成が必要"],"ko":["강력한 객체 바인딩이 필요","상태 관리를 위해 SQLite 마이그레이션이 필요","클라우드플레어 워커만 해당","wrangler.jsonc 내의 특정 구성이 필요"],"es":["Requiere enlaces de objetos duraderos","Necesita migraciones de SQLite para la gestión del estado","Solo para Cloudflare Workers","Requiere una configuración específica en wrangler.jsonc"],"fr":["Nécessite des liaisons d''objets durables","Requiert des migrations SQLite pour la gestion de l''état","Cloudflare Workers uniquement","Nécessite une configuration spécifique dans wrangler.jsonc"],"de":["Erfordert durable object bindings","Benötigt SQLite-Migrationen für das Zustandsmanagement","Nur Cloudflare Workers","Erfordert eine spezifische Konfiguration in wrangler.jsonc"],"pt":["Exige vinculações de objetos duráveis","Necessita de migrações SQLite para gerenciamento de estado","Apenas Cloudflare Workers","Exige configuração específica em wrangler.jsonc"],"ru":["Требует прочных связей объектов","Требует миграций SQLite для управления состоянием","Только Cloudflare Workers","Требует специальной конфигурации в wrangler.jsonc"],"ar":["يتطلب ربط كائنات متينة","يحتاج إلى ترحيلات SQLite لإدارة الحالة","Cloudflare Workers فقط","يتطلب تكوينًا محددًا في wrangler.jsonc"]},"version":4},"contentHash":"7c54b8dc6556f2a5698d29b6bd6409edd244e7e46031acacd14f4a5a6296a8f7","qualityScore":54}');
