INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('charl-kruger/charl/agents-sdk', 'agents-sdk', 'charl-kruger', 'charl', 'community', 'agents-sdk charl-kruger charl community The agents-sdk is an npm package for developers to build persistent, stateful AI agents on Cloudflare Workers. It requires durable object bindings and SQLite migrations for state management, targeting developers creating long-lived AI applications. Cloudflare Agents SDK 是一个用于构建持久、状态管理的 AI 代理的工具，基于 Cloudflare Workers 和 SQLite 存储 Cloudflare Agents SDK は、Cloudflare Workers と SQLite ストレージに基づいて、持続的で状態管理された AI エージェントを構築するためのツール Cloudflare Agents SDK는 Cloudflare Workers와 SQLite 스토리지를 기반으로 지속적이고 상태 관리된 AI 에이전트를 구축하는 도구 El SDK de agents permite a los desarrolladores crear agentes de inteligencia artificial estatales en Cloudflare Workers utilizando el paquete npm ''agents'' Le SDK d''agents permet aux développeurs de créer des agents d''intelligence artificielle étatiques sur Cloudflare Workers en utilisant le paquet npm ''agents'' Das agents-SDK ermöglicht es Entwicklern, Zustands-IA-Agenten in Cloudflare Workers mithilfe des npm-Pakets ''agents'' zu erstellen O Agents SDK permite criar agentes de IA persistentes e stateful com Cloudflare Workers. Veja como instalar e configurar. Agents SDK позволяет создавать персистентные и состоятельные ИИ агенты с Cloudflare Workers. Узнайте, как установить и настроить. يسمح Agents SDK بإنشاء وكلاء ذكاء اصطناعي متواصلين وثابتين مع Cloudflare Workers. تعلم كيفية التثبيت والتكوين. how to use agents-sdk what is agents-sdk agents-sdk vs durable objects agents-sdk alternative agents-sdk install guide agents-sdk setup Cloudflare Workers agents-sdk npm package agents-sdk wrangler.jsonc configuration Cloudflare Agents SDK AI 代理 持久性 状态管理 SQLite 存储 Cloudflare Workers npm 包 wrangler.jsonc Installs via npm install agents for immediate use in projects Requires durable_objects bindings in wrangler.jsonc for state management Uses class_name binding that must match your Agent class name exactly Requires SQLite migrations tagged for persistent data storage Enables building stateful AI agents on the Cloudflare Workers platform agents-sdk is an npm package that provides the tools to build persistent, stateful AI agents on Cloudflare Workers. It utilizes Durable Objects for statefulness and requires specific bindings and SQLite migrations in the wrangler.jsonc configuration file.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('artalis-io/hull/c-audit', 'community', 'artalis-io', 'hull', 'artalis-io/hull', 'c-audit', 6, 1, 54, '2026-03-03T22:25:32Z', '2026-03-06T06:53:20.162Z', 'c61adde98caa4776d4553453701cb70ab4f8085ad0c75deb8d525dd3bed0a1a4', '{"id":"artalis-io/hull/c-audit","name":"c-audit","description":{"en":"The c-audit skill performs comprehensive security, safety, and quality audits on Hull C code, targeting source files in src/cap/, src/runtime/, and include/hull/. It benefits developers by identifying critical issues and applying fixes.","zh":"C-Audit 是一个本地优先应用平台，提供单一二进制、零依赖的安全审计和代码质量保证解决方案","ja":"C-Audit はローカルファーストアプリケーションプラットフォームであり、単一のバイナリ、ゼロ依存のセキュリティ監査とコード品質の保証ソリューションを提供","ko":"C-Audit는 로컬 우선 애플리케이션 플랫폼으로 단일 바이너리, 영 종속성의 보안 감사 및 코드 품질 보증 솔루션을 제공","es":"c-audit es una plataforma de aplicación local que realiza auditorías de seguridad, seguridad de la memoria y calidad en código C. Se ejecuta en cualquier lugar sin dependencias.","fr":"c-audit est une plateforme d''application locale qui effectue des audits de sécurité, de sécurité de la mémoire et de qualité sur du code C. Elle s''exécute partout sans dépendances.","de":"c-audit ist eine lokale Anwendungsplattform, die Sicherheits-, Speichersicherheits- und Qualitätsaudits für C-Code durchführt. Sie läuft überall ohne Abhängigkeiten.","pt":"O c-audit é uma plataforma de aplicativos locais que executa auditorias de segurança, segurança e qualidade em código C. Ele é leve, com um único binário e sem dependências.","ru":"c-audit - это платформа локальных приложений, которая выполняет комплексные аудиты безопасности, безопасности и качества кода C. Она легкая, с единичным бинарным файлом и без зависимостей.","ar":"c-audit هي منصة تطبيقات محلية تقوم بتدقيق شامل لأمان وسلامة و质量 رمز سي. وهي خفيفة، ذات ثنائي واحد وبدون зависимости"},"seo":{"title":{"en":"c-audit: Comprehensive C Code Audit Setup Guide | AI Agen...","zh":"C-Audit 设置指南：本地优先应用平台安全审计","ja":"C-Audit のベストプラクティス：ローカルファーストアプリケーションプラットフォームのセキュリティ監査","ko":"C-Audit 설정 가이드: 로컬 우선 애플리케이션 플랫폼 보안 감사","es":"Guía de configuración de c-audit: Análisis de código C","fr":"Guide de configuration de c-audit: Audit de code C","de":"Einrichtungsleitfaden für c-audit: C-Code-Audit-Tool","pt":"Guia de Configuração do c-audit: Plataforma de Aplicativo...","ru":"Настройка c-audit: Платформа локальных приложений для ИИ ...","ar":"دليل إعداد c-audit: منصة تطبيقات محلية للوكلاء الذكاء الا..."},"description":{"en":"Discover how to perform security, safety, and quality audits on Hull C code with c-audit. Learn to identify memory safety issues and apply fixes with ease.","zh":"了解 C-Audit 的功能和用法，实现本地优先应用平台的安全审计和代码质量保证","ja":"C-Audit の機能と使い方を学び、ローカルファーストアプリケーションプラットフォームのセキュリティ監査とコード品質の保証を実現","ko":"C-Audit의 기능과 사용법을 알아보고 로컬 우선 애플리케이션 플랫폼의 보안 감사 및 코드 품질 보증을 구현","es":"Aprende a utilizar c-audit para analizar la seguridad, la seguridad de la memoria y la calidad de tu código C. Descubre cómo funciona esta herramienta de aná...","fr":"Découvrez comment utiliser c-audit pour analyser la sécurité, la sécurité de la mémoire et la qualité de votre code C. Comprenez les fonctionnalités de cet o...","de":"Erfahren Sie, wie Sie c-audit verwenden, um die Sicherheit, die Speichersicherheit und die Qualität Ihres C-Codes zu analysieren. Entdecken Sie die Funktione...","pt":"Aprenda a configurar o c-audit, uma plataforma de aplicativos locais com um único binário e sem dependências, para auditorias de segurança e qualidade de cód...","ru":"Узнайте, как настроить c-audit, платформу локальных приложений с единичным бинарным файлом и без зависимостей, для аудита безопасности и качества кода C для ...","ar":"تعلم كيفية إعداد c-audit، منصة تطبيقات محلية ذات ثنائي واحد وبدون зависимости، لتدقيق أمان و质量 رمز سي"},"definition":{"en":"c-audit is a local-first application platform that runs anywhere, providing a single binary with zero dependencies for auditing C code.","zh":"C-Audit 是一个用于进行 C 代码安全审计和质量保证的 AI 工具","ja":"C-Audit は C コードのセキュリティ監査と品質保証を行う AI エージェント","ko":"C-Audit는 C 코드의 보안 감사 및 품질 보증을 수행하는 AI 에이전트","es":"c-audit es una herramienta de análisis de código que realiza auditorías de seguridad y calidad en código C.","fr":"c-audit est un outil d''analyse de code qui effectue des audits de sécurité et de qualité sur du code C.","de":"c-audit ist ein Code-Analyse-Tool, das Sicherheits- und Qualitätsaudits für C-Code durchführt.","pt":"O c-audit é uma ferramenta de auditoria de código C que executa verificações de segurança, segurança e qualidade em código C","ru":"c-audit - это инструмент аудита кода C, который выполняет проверки безопасности, безопасности и качества кода C для ИИ Агентов","ar":"c-audit هي أداة تدقيق رمز سي تقوم بفحص أمان وسلامة و质量 رمز سي"},"features":{"en":["Performs comprehensive security, safety, and quality audits on Hull C code","Audits specific files or all source files in src/cap/, src/runtime/, and include/hull/","Identifies memory safety issues with critical severity","Applies fixes to audited code using the --fix command","Runs as a single binary with zero dependencies"],"zh":["单一二进制、零依赖的设计","支持对 C 代码进行安全审计和质量保证","可对特定文件或目录进行审计","支持自动修复功能"],"ja":["単一のバイナリ、ゼロ依存の設計","C コードのセキュリティ監査と品質保証をサポート","特定のファイルまたはディレクトリに対して監査を実行可能","自動修復機能をサポート"],"ko":["단일 바이너리, 영 종속성의 디자인","C 코드의 보안 감사 및 품질 보증을 지원","특정 파일 또는 디렉토리に対한 감사를 실행할 수 있음","자동 수정 기능을 지원"],"es":["Análisis de seguridad y calidad del código C","Detección de problemas de seguridad de la memoria","Capacidad de ejecución en cualquier lugar sin dependencias","Soporte para la auditoría de archivos específicos","Opción para aplicar correcciones automáticamente"],"fr":["Analyse de la sécurité et de la qualité du code C","Détection de problèmes de sécurité de la mémoire","Capacité d''exécution partout sans dépendances","Prise en charge de l''audit de fichiers spécifiques","Option pour appliquer des corrections automatiquement"],"de":["Sicherheits- und Qualitätsanalyse für C-Code","Erkennung von Speichersicherheitsproblemen","Fähigkeit, überall ohne Abhängigkeiten auszuführen","Unterstützung für die Auditerstellung von bestimmten Dateien","Option, Korrekturen automatisch anzuwenden"],"pt":["Executa auditorias de segurança e qualidade em código C","Suporta auditoria de arquivos específicos ou todos os arquivos em um diretório","Permite aplicar correções automáticas com a opção --fix","Verifica memória segura para evitar vulnerabilidades críticas","Executa em qualquer lugar, sem dependências ou configuração adicional"],"ru":["Выполняет аудиты безопасности и качества кода C","Поддерживает аудит конкретных файлов или всех файлов в директории","Позволяет применять автоматические исправления с опцией --fix","Проверяет безопасность памяти, чтобы избежать критических уязвимостей","Выполняется где угодно, без зависимостей или дополнительной настройки для ИИ Агентов"],"ar":["يقوم بتدقيق أمان و质量 رمز سي","يدعم تدقيق الملفات المحددة أو جميع الملفات في الدليل","يسمح بتطبيق الإصلاحات التلقائية مع خيار --fix","يفحص سلامة الذاكرة لتجنب الثغرات الحرجة","يعمل في أي مكان، بدون зависимости أو إعداد إضافي للوكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use c-audit","c-audit setup guide","c-audit alternative","c-audit vs other audit tools","c-audit install","what is c-audit","c-audit memory safety","c-audit security audit","c-audit quality audit"],"zh":["C-Audit","AI 工具","本地优先应用平台","安全审计","代码质量保证","C 代码审计","单一二进制","零依赖"],"ja":["C-Audit","AI エージェント","ローカルファーストアプリケーションプラットフォーム","セキュリティ監査","コード品質の保証","C コード監査","単一のバイナリ","ゼロ依存"],"ko":["C-Audit","AI 에이전트","로컬 우선 애플리케이션 플랫폼","보안 감사","코드 품질 보증","C 코드 감사","단일 바이너리","영 종속성"],"es":["c-audit","análisis de código C","seguridad de la memoria","calidad del código","herramienta de análisis de código","auditoría de código","desarrollo de software","seguridad del software"],"fr":["c-audit","analyse de code C","sécurité de la mémoire","qualité du code","outil d''analyse de code","audit de code","développement de logiciels","sécurité des logiciels"],"de":["c-audit","Code-Analyse C","Speichersicherheit","Code-Qualität","Code-Analyse-Tool","Code-Auditor","Software-Entwicklung","Software-Sicherheit"],"pt":["c-audit","auditoria de código C","segurança de código","qualidade de código","plataforma de aplicativos locais","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["c-audit","аудит кода C","безопасность кода","качество кода","платформа локальных приложений","разработка программного обеспечения","инструменты разработки для ИИ Агентов"],"ar":["c-audit","تدقيق رمز سي","أمان رمز","جودة رمز","منصة تطبيقات محلية","تطوير البرمجيات","أدوات التطوير للوكلاء الذكاء الاصطناعي"]}},"owner":"artalis-io","repo":"hull","repoPath":"artalis-io/hull","stars":6,"forks":1,"updatedAt":"2026-03-03T22:25:32Z","topics":[],"category":"community","skillMd":{"name":"c-audit","description":"Audit C code for security, safety, and memory management. Use when reviewing or hardening C modules.","bodyPreview":"# C Code Audit Skill\n\nPerform comprehensive security, safety, and quality audits on Hull C code.\n\n**Target:** $ARGUMENTS (default: all `src/cap/`, `src/runtime/`, and `include/hull/` files)\n\n## Usage\n\n```\n/c-audit                              # Audit all source files\n/c-audit src/cap/hull_cap_db.c        # Audit a specific file\n/c-audit --fix                        # Audit and apply fixes\n```\n\n## Audit Categories\n\n### 1. Memory Safety (Critical)\n\n| Issue | Pattern to Find | Severity |\n|-------|-","body":"# C Code Audit Skill\n\nPerform comprehensive security, safety, and quality audits on Hull C code.\n\n**Target:** $ARGUMENTS (default: all `src/cap/`, `src/runtime/`, and `include/hull/` files)\n\n## Usage\n\n```\n/c-audit                              # Audit all source files\n/c-audit src/cap/hull_cap_db.c        # Audit a specific file\n/c-audit --fix                        # Audit and apply fixes\n```\n\n## Audit Categories\n\n### 1. Memory Safety (Critical)\n\n| Issue | Pattern to Find | Severity |\n|-------|-----------------|----------|\n| Buffer overflow | `strcpy`, `strcat`, `sprintf`, `gets`, unbounded loops | Critical |\n| Unbounded string ops | `strlen`, `strcmp` on untrusted input | Critical |\n| Unsafe integer parsing | `atoi`, `atol`, `atof` (no error detection, no bounds) | High |\n| Integer overflow | `malloc(a * b)` without overflow check | Critical |\n| Use-after-free | Pointer used after `free()` | Critical |\n| Double-free | `free()` called twice on same pointer | Critical |\n| Null dereference | Pointer used without NULL check | High |\n| Uninitialized memory | Variables used before assignment | High |\n| Missing null terminator | String buffer not explicitly terminated | High |\n| Memory leak | `malloc` without corresponding `free` | Medium |\n| Stack buffer overflow | Large stack arrays, VLAs | Medium |\n\n**Safe Replacements:**\n```c\n// Copying\nstrcpy(dst, src)           -> strncpy(dst, src, sizeof(dst)-1); dst[sizeof(dst)-1] = ''\\0'';\nstrcat(dst, src)           -> strncat(dst, src, sizeof(dst)-strlen(dst)-1);\n\n// Formatting\nsprintf(buf, fmt, ...)     -> snprintf(buf, sizeof(buf), fmt, ...);\ngets(buf)                  -> fgets(buf, sizeof(buf), stdin);\n\n// Memory allocation (overflow-safe)\nmalloc(count * size)       -> calloc(count, size);\n\n// Integer parsing (atoi/atol have no error detection!)\natoi(str)                  -> strtol(str, &end, 10) with validation\natof(str)                  -> strtof(str, &end) with validation\n```\n\n**Allocator Discipline:**\n```c\n// Hull uses malloc/free directly (no custom allocator like Keel)\n// Verify: every malloc has a matching free\n// Verify: every malloc return is checked for NULL\n// Verify: calloc used when count*size multiplication is needed\n\n// BAD:\nvoid *p = malloc(count * elem_size);  // overflow risk\n\n// GOOD:\nvoid *p = calloc(count, elem_size);   // overflow-safe\nif (!p) return -1;\n```\n\n### 2. Input Validation\n\n| Issue | What to Check |\n|-------|---------------|\n| Array bounds | All array indices validated before access |\n| Pointer validity | NULL checks before dereference |\n| Size parameters | Non-negative, within reasonable bounds |\n| String length | Length checked before copy/concat |\n| Numeric ranges | Values within expected domain |\n| SQL parameters | `param_count` checked before binding in `hl_cap_db_*` |\n| File paths | Path validation via `hl_cap_fs_validate()` before any I/O |\n| Env allowlist | Variable name checked against allowlist in `hl_cap_env_get()` |\n\n### 3. Resource Management\n\n| Issue | What to Check |\n|-------|---------------|\n| File descriptors | `fopen` paired with `fclose` |\n| Memory | `malloc`/`calloc` paired with `free` |\n| SQLite | `sqlite3_open` paired with `sqlite3_close` |\n| SQLite statements | `sqlite3_prepare_v2` paired with `sqlite3_finalize` |\n| QuickJS runtime | `JS_NewRuntime` paired with `JS_FreeRuntime` |\n| QuickJS context | `JS_NewContext` paired with `JS_FreeContext` |\n| Lua state | `lua_newstate` paired with `lua_close` |\n| Error paths | Resources freed on all exit paths |\n| I/O return values | `fwrite`/`fread` return values checked |\n\n**Hull Cleanup Pattern:**\n```c\n// Every init must have matching free\nhl_js_init()           -> hl_js_free()\nhl_lua_init()          -> hl_lua_free()\nsqlite3_open()         -> sqlite3_close()\nsqlite3_prepare_v2()   -> sqlite3_finalize()\nJS_NewRuntime()        -> JS_FreeRuntime()\nJS_NewContext()         -> JS_FreeContext()\nlua_newstate()         -> lua_close()\nfopen()                -> fclose()\n```\n\n### 4. Integer Overflow\n\nOverflow in size computations can cause undersized allocations and buffer overflows.\n\n```c\n// BAD: overflow on 32-bit\nint total = count * sizeof(HlColumn);\nvoid *buf = malloc(total);\n\n// GOOD: use size_t + calloc\nHlColumn *cols = calloc(count, sizeof(HlColumn));\n\n// GOOD: check before multiply\nif (count > 0 && (size_t)count > SIZE_MAX / sizeof(HlColumn)) {\n    return -1;  // overflow\n}\n```\n\n**Key areas in Hull:**\n- `HlColumn` array allocation in `hl_cap_db_query()` row callbacks\n- PBKDF2 output buffer sizing\n- SQL parameter arrays (`HlValue` binding arrays)\n- Filesystem path buffer construction (`base_dir + \"/\" + relative_path`)\n- QuickJS/Lua value conversion arrays\n\n### 5. Capability Boundary Enforcement\n\nHull''s security model depends on the shared `hl_cap_*` layer. Verify:\n\n| Issue | Severity | What to Check |\n|-------|----------|---------------|\n| Direct SQLite calls | Critical | JS/Lua bindings never call `sqlite3_*` directly |\n| Direct file I/O | Critical | JS/Lua bindings never call `fopen`/`fread`/`fwrite` directly |\n| Path traversal | Critical | `hl_cap_fs_validate()` called before every file operation |\n| SQL injection | Critical | All SQL uses parameterized binding via `hl_cap_db_*` |\n| Env leakage | High | All env access through `hl_cap_env_get()` with allowlist |\n| Sandbox escape | Critical | `eval()` removed, `io`/`os` libs not loaded, `loadfile`/`dofile` removed |\n\n### 6. Defensive Macros\n\nCheck for and suggest these patterns:\n```c\n#define ARRAY_LEN(a) (sizeof(a) / sizeof((a)[0]))\n#define SAFE_FREE(p) do { free(p); (p) = NULL; } while(0)\n#define CLAMP(x, lo, hi) ((x) < (lo) ? (lo) : ((x) > (hi) ? (hi) : (x)))\n```\n\n### 7. Test Coverage\n\nCheck test files (`tests/test_*.c`) for:\n- [ ] Basic functionality tests\n- [ ] Edge cases (empty input, max values, NULL)\n- [ ] Error path tests (what happens when things fail)\n- [ ] Bounds checking tests\n- [ ] All public API functions have at least one test\n- [ ] Path traversal rejection tested\n- [ ] SQL parameterization tested\n- [ ] Env allowlist enforcement tested\n- [ ] Sandbox restrictions tested (both JS and Lua)\n\n### 8. Dead Code Detection\n\n| Pattern | Issue | Fix |\n|---------|-------|-----|\n| `if (0) { ... }` | Dead branch | Remove |\n| `return; code_after;` | Unreachable code | Remove |\n| `#if 0 ... #endif` | Disabled code | Remove or document |\n| Unused `#define` | Dead macro | Remove |\n| Unused static function | Dead function | Remove |\n\nCompile with `-Wunused` flags to detect automatically.\n\n### 9. Build Hardening\n\n**Development build (`make debug`):**\n```makefile\n-fsanitize=address,undefined -g -O0 -fno-omit-frame-pointer\n```\n\n**Production build (`make`):**\n```makefile\n-Wall -Wextra -Wpedantic -Wshadow -Wformat=2\n-fstack-protector-strong\n-O2\n```\n\n**Full validation (`make check`):**\n```makefile\nclean + DEBUG=1 build + test + e2e\n```\n\n**Audit Checks:**\n- [ ] `-fstack-protector-strong` in production CFLAGS\n- [ ] Debug build with ASan + UBSan available (`make debug`)\n- [ ] Full validation available (`make check`)\n- [ ] All tests pass under sanitizers\n- [ ] No compiler warnings with `-Wall -Wextra -Wpedantic -Wshadow -Wformat=2`\n\n## Audit Procedure\n\nWhen `/c-audit` is invoked:\n\n1. **Locate Files**\n   ```\n   src/cap/*.c                 # Shared capability layer\n   src/runtime/js/*.c          # QuickJS runtime integration\n   src/runtime/lua/*.c         # Lua 5.4 runtime integration\n   src/main.c                  # Entry point\n   include/hull/*.h            # Public headers\n   tests/test_*.c              # Test files\n   Makefile                    # Build configuration\n   ```\n\n2. **Scan for Critical Issues**\n   - Search for unsafe functions: `strcpy`, `sprintf`, `gets`, `strcat`\n   - Search for unsafe integer parsing: `atoi`, `atol`, `atof`\n   - Search for unchecked allocations: `malloc`/`calloc` without NULL check\n   - Search for integer overflow in size calculations\n   - Search for missing bounds checks on array access\n   - Search for unchecked `fwrite()`/`fread()` return values\n   - Search for direct SQLite/file I/O calls in runtime bindings (bypass of `hl_cap_*`)\n\n3. **Review Public API**\n   - Check all public functions in headers (`hl_*` prefix)\n   - Verify NULL checks on pointer parameters\n   - Verify bounds checks on size parameters\n\n4. **Check Resource Management**\n   - Every `_init()`/`_create()` has matching `_free()`/`_close()`\n   - Error paths free allocated resources\n   - No memory leaks on early returns\n   - SQLite statements finalized on error paths\n   - QuickJS/Lua contexts cleaned up on error paths\n\n5. **Check Capability Boundaries**\n   - JS/Lua bindings only access resources through `hl_cap_*` functions\n   - Path validation enforced before every filesystem operation\n   - SQL always parameterized\n   - Sandbox restrictions in place (no eval, no io/os libs)\n\n6. **Detect Dead Code**\n   - Compile with `-Wunused` flags\n   - Find unused static functions\n   - Find unused variables and parameters\n   - Flag commented-out or `#if 0` code blocks\n\n7. **Check Build Hardening**\n   - Sanitizers available in debug build\n   - Stack protection in production build\n   - Warning flags comprehensive\n\n8. **Generate Report**\n   Format as markdown table with findings, severity, file:line, and suggested fix.\n\n## Report Format\n\n```markdown\n## C Audit Report: Hull\n\n**Date:** YYYY-MM-DD\n**Files Scanned:** N\n**Issues Found:** N (Critical: N, High: N, Medium: N, Low: N)\n\n### Critical Issues\n\n| # | File:Line | Issue | Current Code | Suggested Fix |\n|---|-----------|-------|--------------|---------------|\n| C1 | src/cap/hull_cap_db.c:42 | Buffer overflow | `strcpy(buf, src)` | `snprintf(buf, sizeof(buf), \"%s\", src)` |\n\n### High Issues\n...\n\n### Medium Issues\n...\n\n### Low Issues\n...\n\n### Recommendations\n1. ...\n```\n\n## Fix Mode (--fix)\n\nWhen `--fix` is specified:\n\n1. Generate the audit report first\n2. For each fixable issue, apply the transformation\n3. Rebuild (`make`)\n4. Re-run tests (`make test`)\n5. Report any test failures or new warnings\n\n**Auto-fixable Issues:**\n- `strcpy` -> `snprintf` with buffer size\n- `sprintf` -> `snprintf` with buffer size\n- `atoi` -> `strtol` with validation\n- Missing NULL checks (add early return)\n- Missing `malloc` return check (add NULL check)\n- Integer overflow in size calc -> `calloc` or overflow check\n- Missing `size_t` casts in size calculations\n- Unused local variables (remove)\n- Unused static functions (remove)\n\n**NOT Auto-fixable (require manual review):**\n- Logic errors\n- Resource leaks in complex control flow\n- Capability boundary violations\n- Sandbox escape paths\n- Architectural changes\n"},"lastSynced":"2026-03-06T06:53:20.162Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring in-depth C code analysis and security auditing capabilities.","zh":"适用于需要对C代码进行深入分析和安全审计的代码审查代理。","ja":"Cコードの深い分析とセキュリティ監査機能を必要とするコードレビュー代理に適しています。","ko":"C 코드의 심층 분석 및 보안 감사를 필요로 하는 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para Agentes de Revisión de Código que requieren un análisis en profundidad del código C y capacidades de auditoría de seguridad.","fr":"Idéal pour les agents de révision de code nécessitant une analyse approfondie du code C et des capacités d''audit de sécurité.","de":"Ideal für Code-Review-Agents, die eine umfassende C-Code-Analyse und Sicherheits-Audit-Funktionen erfordern.","pt":"Ideal para Agentes de Revisão de Código que exigem análise profunda de código C e capacidades de auditoria de segurança.","ru":"Идеально подходит для агентов проверки кода, требующих глубокого анализа кода C и возможностей аудита безопасности.","ar":"مثالي لعمليات مراجعة الشفرة التي تتطلب تحليلًا متعمقًا للشفرة C وقدرات تدقيق الأمان."},"recommendation":{"en":"Empowers agents to perform comprehensive security, safety, and quality audits on Hull C code, targeting source files and applying fixes using Memory Safety and other audit categories, including src/cap/, src/runtime/, and include/hull/ directories.","zh":"赋予代理执行对Hull C代码进行全面安全、安全性和质量审计的能力，针对源文件并使用内存安全和其他审计类别应用修复，包括src/cap/、src/runtime/和include/hull/目录。","ja":"Hull Cコードを対象とした総合的なセキュリティ、安全性、品質の監査を実行し、ソースファイルに対して修復を適用する機能を提供する。これは、Memory Safetyなどの監査カテゴリを使用して、src/cap/、src/runtime/、include/hull/ディレクトリを対象とする。","ko":"Hull C 코드를 대상으로 한 종합적인 보안, 안전성 및 품질 감사를 수행하고, 소스 파일에 대해 수정을 적용하는 기능을 제공한다. 이것은 Memory Safety 등의 감사 카테고리를 사용하여 src/cap/, src/runtime/, include/hull/ 디렉토리를 대상으로 한다.","es":"Habilita a los agentes a realizar auditorías de seguridad, seguridad y calidad integrales en el código C de Hull, apuntando a archivos de origen y aplicando soluciones utilizando Seguridad de Memoria y otras categorías de auditoría, incluyendo los directorios src/cap/, src/runtime/ e include/hull/.","fr":"Permet aux agents d''effectuer des audits de sécurité, de sûreté et de qualité complets sur le code C de Hull, ciblant les fichiers source et appliquant des correctifs à l''aide de la sécurité de la mémoire et d''autres catégories d''audit, notamment les répertoires src/cap/, src/runtime/ et include/hull/.","de":"Ermöglicht es Agents, umfassende Sicherheits-, Sicherheits- und Qualitätsaudits auf Hull-C-Code durchzuführen, der auf Quelldateien abzielt und mithilfe von Speicher-Sicherheit und anderen Audit-Kategorien Korrekturen anwendet, einschließlich der Verzeichnisse src/cap/, src/runtime/ und include/hull/.","pt":"Habilita agentes a realizar auditorias abrangentes de segurança, segurança e qualidade em código C Hull, visando arquivos de origem e aplicando correções usando Segurança de Memória e outras categorias de auditoria, incluindo diretórios src/cap/, src/runtime/ e include/hull/.","ru":"Наделяет агентов возможностью проводить комплексные аудиты безопасности, безопасности и качества кода Hull C, нацеливаясь на файлы исходного кода и применяя исправления с помощью Безопасности Памяти и других категорий аудита, включая директории src/cap/, src/runtime/ и include/hull/.","ar":"تمكّن الوكلاء من إجراء تدقيقات شاملة للأمان والسلامة والجودة في شفرة Hull C، تستهدف الملفات المصدرية وتطبق الإصلاحات باستخدام سلامة الذاكرة وفئات التدقيق الأخرى، بما في ذلك الدلائل src/cap/ و src/runtime/ و include/hull/."},"useCases":{"en":["Auditing C code for critical memory safety issues","Applying automated fixes to identified security vulnerabilities","Performing quality audits on Hull C source files"],"zh":["审核C代码中的关键内存安全问题","对已识别的安全漏洞应用自动修复","对Hull C源文件执行质量审计"],"ja":["重要なメモリセキュリティ問題のあるCコードの監査","特定のセキュリティ脆弱性に対する自動修復の適用","Hull Cソースファイルの品質監査の実行"],"ko":["중요한 메모리 보안 문제가 있는 C 코드의 감사","특정 보안 취약점에 대한 자동 수정 적용","Hull C 소스 파일의 품질 감사 수행"],"es":["Auditoría de código C para problemas críticos de seguridad de memoria","Aplicación de soluciones automatizadas a vulnerabilidades de seguridad identificadas","Realización de auditorías de calidad en archivos de origen de C de Hull"],"fr":["Audit de code C pour les problèmes critiques de sécurité de la mémoire","Application de correctifs automatisés aux vulnérabilités de sécurité identifiées","Réalisations d''audits de qualité sur les fichiers source de C de Hull"],"de":["Überprüfung von C-Code auf kritische Speicher-Sicherheitsprobleme","Anwenden automatisierter Korrekturen auf identifizierte Sicherheits-Schwachstellen","Durchführung von Qualitätsaudits auf Hull-C-Quelldateien"],"pt":["Auditoria de código C para problemas críticos de segurança de memória","Aplicação de correções automatizadas para vulnerabilidades de segurança identificadas","Realização de auditorias de qualidade em arquivos de origem C Hull"],"ru":["Аудит кода C для критических проблем безопасности памяти","Применение автоматических исправлений для выявленных уязвимостей безопасности","Проведение аудитов качества исходных файлов C Hull"],"ar":["تدقيق شفرة C لمشاكل حرجية في سلامة الذاكرة","تطبيق إصلاحات آلية للثغرات الأمنية المحددة","إجراء تدقيقات جودة لملفات مصدر شفرة Hull C"]},"limitations":{"en":["Requires access to Hull C codebase","Limited to auditing C code in specific directories (src/cap/, src/runtime/, include/hull/)"],"zh":["需要访问Hull C代码库","仅限于对特定目录（src/cap/、src/runtime/、include/hull/）中的C代码进行监査"],"ja":["Hull Cコードベースへのアクセスが必要","特定のディレクトリ（src/cap/、src/runtime/、include/hull/）内のCコードのみを監査可能"],"ko":["Hull C 코드베이스에 대한 접근이 필요","특정 디렉토리(src/cap/, src/runtime/, include/hull/) 내의 C 코드만 감사가 가능"],"es":["Requiere acceso a la base de código C de Hull","Limitado a la auditoría de código C en directorios específicos (src/cap/, src/runtime/, include/hull/)"],"fr":["Nécessite un accès à la base de code C de Hull","Limité à l''audit de code C dans des répertoires spécifiques (src/cap/, src/runtime/, include/hull/)"],"de":["Erfordert Zugriff auf die Hull-C-Codebasis","Begrenzt auf die Überprüfung von C-Code in bestimmten Verzeichnissen (src/cap/, src/runtime/, include/hull/)"],"pt":["Exige acesso à base de código C Hull","Limitado à auditoria de código C em diretórios específicos (src/cap/, src/runtime/, include/hull/)"],"ru":["Требует доступа к базе кода Hull C","Ограничен аудитом кода C в конкретных директориях (src/cap/, src/runtime/, include/hull/)"],"ar":["يتطلب الوصول إلى قاعدة شفرة Hull C","محدود بتدقيق شفرة C في دلائل محددة (src/cap/ و src/runtime/ و include/hull/)"]},"version":4},"contentHash":"c61adde98caa4776d4553453701cb70ab4f8085ad0c75deb8d525dd3bed0a1a4","qualityScore":54}');
