INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('artalis-io/hull/c-audit', 'c-audit', 'artalis-io', 'hull', 'community', 'c-audit artalis-io hull community The c-audit skill performs comprehensive security, safety, and quality audits on Hull C code, targeting source files in src/cap/, src/runtime/, and include/hull/. It benefits developers by identifying critical issues and applying fixes. C-Audit 是一个本地优先应用平台，提供单一二进制、零依赖的安全审计和代码质量保证解决方案 C-Audit はローカルファーストアプリケーションプラットフォームであり、単一のバイナリ、ゼロ依存のセキュリティ監査とコード品質の保証ソリューションを提供 C-Audit는 로컬 우선 애플리케이션 플랫폼으로 단일 바이너리, 영 종속성의 보안 감사 및 코드 품질 보증 솔루션을 제공 c-audit es una plataforma de aplicación local que realiza auditorías de seguridad, seguridad de la memoria y calidad en código C. Se ejecuta en cualquier lugar sin dependencias. c-audit est une plateforme d''application locale qui effectue des audits de sécurité, de sécurité de la mémoire et de qualité sur du code C. Elle s''exécute partout sans dépendances. c-audit ist eine lokale Anwendungsplattform, die Sicherheits-, Speichersicherheits- und Qualitätsaudits für C-Code durchführt. Sie läuft überall ohne Abhängigkeiten. O c-audit é uma plataforma de aplicativos locais que executa auditorias de segurança, segurança e qualidade em código C. Ele é leve, com um único binário e sem dependências. c-audit - это платформа локальных приложений, которая выполняет комплексные аудиты безопасности, безопасности и качества кода C. Она легкая, с единичным бинарным файлом и без зависимостей. c-audit هي منصة تطبيقات محلية تقوم بتدقيق شامل لأمان وسلامة و质量 رمز سي. وهي خفيفة، ذات ثنائي واحد وبدون зависимости how to use c-audit c-audit setup guide c-audit alternative c-audit vs other audit tools c-audit install what is c-audit c-audit memory safety c-audit security audit c-audit quality audit C-Audit AI 工具 本地优先应用平台 安全审计 代码质量保证 C 代码审计 单一二进制 零依赖 Performs comprehensive security, safety, and quality audits on Hull C code Audits specific files or all source files in src/cap/, src/runtime/, and include/hull/ Identifies memory safety issues with critical severity Applies fixes to audited code using the --fix command Runs as a single binary with zero dependencies c-audit is a local-first application platform that runs anywhere, providing a single binary with zero dependencies for auditing C code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('C0ntr0lledCha0s/logseq-template-graph/edn-analyzer', 'community', 'C0ntr0lledCha0s', 'logseq-template-graph', 'C0ntr0lledCha0s/logseq-template-graph', 'edn-analyzer', 5, 0, 54, '2026-02-23T16:12:58Z', '2026-03-06T06:54:22.192Z', '5c53ec6029b0d83ad25e271377864bb62eb88527b903f991e62c76f7769e9060', '{"id":"C0ntr0lledCha0s/logseq-template-graph/edn-analyzer","name":"edn-analyzer","description":{"en":"The edn-analyzer skill provides in-depth analysis of EDN template files for Logseq database graphs, helping developers optimize structure and quality. It benefits developers working with Logseq databases.","zh":"edn-analyzer 是一个 Logseq 数据库图结构分析工具，提供结构洞察和质量检查","ja":"edn-analyzer は Logseq データベースグラフ構造分析ツールであり、構造の洞察と品質チェックを提供します","ko":"edn-analyzer는 Logseq 데이터베이스 그래프 구조 분석 도구로서 구조에 대한 통찰력과 품질 검사를 제공합니다","es":"edn-analyzer es una herramienta para analizar plantillas EDN en Logseq, proporcionando informes sobre estructura y calidad","fr":"edn-analyzer est un outil pour analyser les modèles EDN dans Logseq, fournissant des rapports sur la structure et la qualité","de":"edn-analyzer ist ein Tool zum Analysieren von EDN-Vorlagen in Logseq, mit Berichten über Struktur und Qualität","pt":"O EDN Analyzer é uma ferramenta de análise de estrutura para bases de dados Logseq, que fornece insights sobre a estrutura, qualidade e problemas potenciais.","ru":"ИИ Агент EDN Analyzer - это инструмент для анализа структуры базы данных Logseq, который предоставляет информацию о структуре, качестве и потенциальных проблемах.","ar":"تطبيق EDN Analyzer هو أداة لتحليل البنية للقواعد البيانية Logseq، والتي توفر رؤى حول البنية وجودة والمشكلات المحتملة."},"seo":{"title":{"en":"edn-analyzer: Logseq DB Structure Analysis for AI Agents","zh":"edn-analyzer 结构分析工具：Logseq 数据库优化指南","ja":"edn-analyzer 構造分析ツール：Logseq データベース最適化ガイド","ko":"edn-analyzer 구조 분